window.__D("text/torat-chaim/c030",{"p":[[2300550542,"הרצון והתענוג אלקי שא\"א שיבא בגילוי בחו\"ב ובמדות שמקבלים מהם כלל. ואע\"פ שהי' לו גם אה\"ר זו במס\"נ [ממש] כמ\"ש התהלך לפני והי' תמים<sup data-n=\"2646\">389</sup> ממש, אך זה הי' [בא] בגילוי דרך צמצום השכל והמדות שבלב אבל לזקנותו העלה גם המדות ומוחין שבגילוי לאותן ימים העליוני' שבעצמו' הרצון והתענוג להיות גם הוא<sup data-n=\"2647\">390</sup> [ב]בחי' השלימות בלי שינוי כלל, והוא שנעשה מרכבה לבחי' ימי קדם בבחי' קדמונו של עולם<sup data-n=\"2648\">391</sup> וזהו בא בימים דימי קדם וכמ\"ש אשר נשבעת לאבותינו מימי קדם ([ב]בחי' חג\"ת דע\"י וא\"א<sup data-n=\"2649\">392</sup> כו'). והנה א' עוד בזהר בפי' בא בימים באינון לבושי' שהימים נק' לבושים לנפש כו'<sup data-n=\"2650\">393</sup>, [וכל יום] ויום עושה [לבוש חדש לנפשו] ע\"י תו\"מ שעושה האדם בכל יום ואם חסר [ב]יום א' שלא עשה בו לבוש דתו\"מ חסר לבושא חדא כו'. והענין הוא דהכל עולה לכוונה א' שבחי' הלבושין הם בחי' המקיפי' דנר\"נ דאדם הנ\"ל שהמקיפי' שורים על הלבושי'<sup data-n=\"2651\">394</sup> דוקא כידוע וע\"כ בחי' יומין עילאין הנ\"ל הוא שנק' ג\"כ לבושי' [שמקיפים הללו באים להתלבש בבחי' לבושים שהם בחי' מחדו\"מ שנק' לבושים] לנפש כידוע, וז\"ש באים בימים בבחי' לבושים דהיינו בחי' יומין עילאין דזקנה הנ\"ל ועיקר שרש הלבושים הם בלבושים דתו\"מ דוקא [שהן מחדו\"מ דתו\"מ בכל יום] כו'.\n(יז) <sup data-n=\"2652\">395</sup> <b>וביאור</b> הענין, הנה ידוע שהימים נית[נו] לאדם במספר כמה ימים<sup data-n=\"2653\">396</sup> יחי' בעוה\"ז כמ\"ש ימים יצרו<sup data-n=\"2654\">397</sup> ולא אחד<sup data-n=\"2655\">398</sup> כו', וכל מספר הימים שנותנים לאדם מלמעלה ה[ם] נקצ[ו]בים להיות בכל יום ויום איזה תיקון לתקן ולהשלים נפשו בבירורי' דעה\"ד [מ]רפ\"ח [ניצוצין]<sup data-n=\"2656\">399</sup> כו' ולא נתנו לבטל[ה] אפי' שעה א' ורגע א' [ממש שיהיו יתירים] על השיעור ומדה ששיערו למעלה כמה שהוא צריך לתקן ולהשלים נפשו בסו\"מ וע\"ט [ו]באוי\"ר כו'. ולזאת אם יבטל יום א' בלי יתן לבו לתקן נפשו בתו\"מ ואוי\"ר ותשו' וכה\"ג נק' יום זה יומא דפגרא<sup data-n=\"2657\">400</sup> לשון פגרא ומות שאין בו אור וחיות האלקי כלל וכלל ולא נמנה בחשבון מספר הימים שנתנו לאדם לתקן נפשו כו', וכ\"ש שלא די שלא עשה תיקון לנפשו בתו\"מ ואוי\"ר כו' עוד זאת שפגם בנפשו בהרהורי' רעים וטמאים<sup data-n=\"2658\">401</sup> מאד וכדומה במדות<sup data-n=\"2659\">402</sup> רעות כו', הרי פגם בזה יותר ממה שתיקן <span data-k=\"pg\">תלח</span> ּ בימים שעשה בהם מצות ותשו' כו', וכשיצורף לחשבון כו'<sup data-n=\"2660\">403</sup> הרי יעלה מספר [ימי] הבטלה לגמרי",[["2646","389","<b>והי' תמים</b>: הט: ליתא."],["2647","390","<b>הוא</b>: שם: הם."],["2648","391","<b>ימי קדם בבחי' קדמונו של עולם</b>: ראה גם לעיל קצט, ד. וש\"נ."],["2649","392","<b>אשר נשבעת. . חג\"ת דע\"י וא\"א</b>: מיכה ז, כ. ראה זהר (אד\"ר) נשא קלד, ב. קלח, ב. לעיל פ' בא צ, ג. וש\"נ."],["2650","393","<b>לנפש כו'</b>: ט: ליתא."],["2651","394","<b>שהמקיפי' שורים על הלבושי'</b>: ראה גם לעיל קפ, ג. וש\"נ."],["2652","395","<b>(יז)</b>: ט: יט. פ\"כ נרשם לקמן על יד הערה 409."],["2653","396","<b>ימים הט</b>: ליתא."],["2654","397","<b>ימים יצרו</b>: תהלים קלט, טז. ראה גם לעיל רעו, ג. וש\"נ."],["2655","398","<b>ולא אחד</b>: הט: ליתא."],["2656","399","<b>[מ]רפ\"ח [ניצוצין]</b>: נסמן לעיל פ' יתרו ערב, ד."],["2657","400","<b>יומא דפגרא</b>: ראה שבת קכט, ב ופרש\"י שם. ראה גם הנסמן במאמרי אדה\"א הנחות תקע\"ז ע' יד."],["2658","401","<b>וטמאים</b>: הט: וחטאים."],["2659","402","<b>מאד וכדומה במדות</b>: ה: ובדיבור ומעשה ובמדות."],["2660","403","<b>כו'</b>: הט: כל ימי חייו."]]],[2300550555,"[ו]<b>ימי</b> הרעה בפגם דמדו\"מ ומדות כו' יותר הרבה מימי הטוב בתו\"מ ואוי\"ר ותשובה. ולזאת צריך שיהא האדם נותן אל לבו בכל יום ויום וכמ\"ש והחי יתן אל לבו<sup data-n=\"2661\">404</sup> כו' על כל פרטי מחשבותיו ודבוריו ומעשיו, ויהי' ממארי דחושבנא<sup data-n=\"2662\">405</sup> היטב הדק לחשוב על כל המדו\"מ ומדותיו דבר יום ביומו ויעשה תשובה שלימה עליהם ל[ה]עלותם מן העולם הפירוד, ויבואו לתקן גם ימים האלה עם ימי הטוב שישלים נפשו בלבושים דקדושה [ש]נק' לבושא דכיא<sup data-n=\"2663\">406</sup> להסיר מעליו לבושא דמסאבותא<sup data-n=\"2664\">407</sup> דמדו\"מ הרעים וחטאים לה' כו' שנק' לבושים צואים<sup data-n=\"2665\">408</sup> ממש כידוע וד\"ל.\n<b>והנה</b><sup data-n=\"2666\">409</sup> עיקר ענין התיקון לנפש בבחי' לבושים טובים היינו בחי' לבושים דתו\"מ מה שהאדם לומד בתורה בדבור בפה גשמי בדבר ה' זו הלכה<sup data-n=\"2667\">410</sup> ומקרא, ומה שעושה מצוה בדברים גשמיי' [דוקא] כצדקה [ב]כסף גשמי'<sup data-n=\"2668\">411</sup> להחיות לעני גשמי<sup data-n=\"2669\">412</sup> ומצות טלית ותפילין בגשמי', וכה\"ג בכל יום ויום שעושה מצוה<sup data-n=\"2670\">413</sup> אע\"פ שאינו עושה ולומד מאוי\"ר פנימי' בהתגלות<sup data-n=\"2671\">414</sup> אלקות כלל רק דרך עול וכפיי' לבד שיכפה א\"ע לקבל לימוד התו' בעול ועול מעשה<sup data-n=\"2672\">415</sup> המצות לעשות רצון קונו מצד גזירת המלך בלבד. ואף שלא יגיע לו מעסק זה דתו\"מ שום התפעלות אוי\"ר במורגש כלל, עכ\"ז הרי נמשך גילוי אלקות ממש בתו\"מ הללו מצד שהתו\"מ הן בחי' פנימי' גילוי הרצון והתענוג העליון שבעצמותו ית' ממש כמו רחבה מצותך מאד<sup data-n=\"2673\">416</sup> [בבחי' א\"ס ממש, וכן התורה הקדומה כמו שהיא בבחי' חכמתו העצמי' ממש וכמ\"ש ואהי' אצלו אמון<sup data-n=\"2674\">417</sup> כו', והן בחי' המקיפי'] דע\"ס דאצי' שלמעלה מהגבלת האור בכלי<sup data-n=\"2675\">418</sup> דאצי', כמו מצות תפילין למעלה בחי' תפילין דמארי עלמא<sup data-n=\"2676\">419</sup> שהקב\"ה מניח תפילין שהן בבחי' בליטה ע\"ג הראש ומוחין דז\"א, וכן מתעטף בטלית<sup data-n=\"2677\">420</sup> שנא' עוטה אור כשלמה<sup data-n=\"2678\">421</sup> בבחי' מקיף הכללי וכמו לבושי' כתלג חיור<sup data-n=\"2679\">422</sup> כו', וכך מצות הצדקה למעלה שנק' חסד דרועא ימינא<sup data-n=\"2680\">423</sup> [הוא] למעלה מאור החסד המוגבל בכלי כו'. וא\"כ בעשות האדם איזה מצוה מן המצות בגשמי' בעוה\"ז הרי [מ]מש[י]ך גילוי רצה\"ע שבבחי' מקיפי' [ה]עליונים דע\"ס דאצי' שהוא בחי' פנימי' הכתר שהם בחי' תר\"ך עמודי אור<sup data-n=\"2681\">424</sup> בתרי\"ג",[["2661","404","<b>והחי יתן אל לבו</b>: קהלת ז, ב."],["2662","405","<b>ממארי דחושבנא</b>: ראה זהר קרח קעח, א. תניא פכ\"ט."],["2663","406","<b>לבושא דכיא</b>: זהר שלח קסט, ב."],["2664","407","<b>לבושא דמסאבותא</b>: תניא פ\"ו."],["2665","408","<b>לבושים צואים</b>: ראה זכרי' ג, ג. ד. זהר פינחס ריד, א."],["2666","409","<b>והנה</b>: ט: נרשם כאן פ\"כ. פי\"ט נרשם לעיל על יד הערה 395. פכ\"א נמצא לקמן על יד הערה 485)."],["2667","410","<b>בדבר ה' זו הלכה</b>: עמוס ח, יב. שבת קלח, ב."],["2668","411","<b>[דוקא]. . גשמי'</b>: ט: ליתא. ואולי נשמט מפני תיבות הדומות: גשמיי'. . גשמי'."],["2669","412","<b>לעני גשמי</b>: ה: לעניים לעני בגשמיות. ט: לעני."],["2670","413","<b>מצוה</b>: שם: תו\"מ."],["2671","414","<b>בהתגלות</b>: שם: בהתפעלות."],["2672","415","<b>ועול מעשה</b>: ה: ועושה."],["2673","416","<b>רחבה מצותך מאד</b>: תהלים קיט, צו. ראה גם לעיל פ' וארא סג, ג. וש\"נ."],["2674","417","<b>ואהי' אצלו אמון</b>: נסמן בהערה 448."],["2675","418","<b>האור בכלי</b>: ה: אוב\"כ. ט: אורות במל'."],["2676","419","<b>תפילין דמארי עלמא</b>: ברכות ו, א. ראה גם מאמרי אדה\"א ויקרא ח\"ב ע' תסז. וש\"נ."],["2677","420","<b>שהקב\"ה. . מתעטף בטלית</b>: ר\"ה יז, ב. ראה גם מאמרי אדה\"א שמות ח\"ב ע' שסו. וש\"נ."],["2678","421","<b>עוטה אור כשלמה</b>: תהלים קד, ב."],["2679","422","<b>לבושי' כתלג חיור</b>: דניאל ז, ט."],["2680","423","<b>הצדקה. . חסד דרועא ימינא</b>: ת\"ז בהקדמה (יז, א). ראה גם מאמרי אדה\"א שמות ח\"א ע' צט. וש\"נ."],["2681","424","<b>הכתר. . תר\"ך עמודי אור</b>: ראה פרדס (שער מהות והנהגה) ש\"ח, פ\"ג. לעיל פ' שמות ח, א. וש\"נ."]]],[2300550568,"מצות דאורייתא וז' מצות<sup data-n=\"2682\">426</sup> דרבנן<sup data-n=\"2683\">425</sup> כידוע. וכמו\"כ במצות ת\"ת בדבור בפה הרי ממשיך מאוא\"ס שבחה\"ק<sup data-n=\"2684\">428</sup> שלפני עולם האצי' כו' וכמ\"ש ואשים דברי בפיך<sup data-n=\"2685\">429</sup> כו' לנטוע שמים כו' שהן אבי\"ע בכלל. וכמ\"כ [כ]שמדבק האדם במחשבתו<sup data-n=\"2686\">430</sup> בהגיון ומח'<sup data-n=\"2687\">427</sup> שבתו'<sup data-n=\"2688\">431</sup> שהוא בח\"ע עצמה, הרי יש כאן ג' לבושי' דמדו\"מ דתו\"מ בזה יתקן אדם בכל יום ויום לנפשו לכל פגמי מחדו\"מ שלו הרעים [וחטאים כו'], ולא עוד אלא שמעלה לנפשו במדות אוי\"ר טבעים ושכליי' ע\"י בחי' הלבושי' דתו\"מ בכל יום למעלה מעלה משרש [ומקור] מחצב הנשמ[ה] והנפש, כי [שרשה היא] בארץ החיים העליונה ששם נזרעים מבחי' אור הזרוע לצ\"ע כידוע (שז\"ש רז\"ל אין ב\"ד בא<sup data-n=\"2689\">432</sup> עד שיכלו הנשמות מן האוצר ששמו גוף כו'). וכל זריעה הוא בשביל הקצירה בריבוי גדול שיהי' תולדות נשמות באוי\"ר אמיתי' כנ\"ל, ואז<sup data-n=\"2690\">433</sup> הרבוי בארץ<sup data-n=\"2691\">434</sup> רק מבחי' אור דתו\"מ הזרוע ג\"כ באה\"ח ששרשם בבחי' [ה]מקיפים דע\"ס דאצי', שעי\"ז בירידת <span data-k=\"pg\">878</span> ּ אור דתו\"מ למטה בבחי' לבושי' דתו\"מ הכל<sup data-n=\"2692\">435</sup> יצמחו בארץ עילאה צדקה ורב חסד העליון להמשיך משם לנשמות שבגופים שיאירו באור החיים בבחי' אה\"ר ונפלא[ה] [ב]דביקות וההתקשרות אמיתי[ת] להיות צרורה בצרור החיים העליון כו'<sup data-n=\"2693\">436</sup> ממש הרבה מכמו שהי' במקור חוצבה כמו והיתה נפש אדוני צרורה<sup data-n=\"2694\">437</sup> בצרור החיים הע[ליונים] כו'. וצרור זה הוא רק ע\"י [בחי'] הלבושי' דמחדו\"מ [דתו\"מ] בכל יום ויום שנעשו לבוש[א] דכי[א] לנשמה ששרשה במקיפים העליונים כו'. ע\"כ יש ביכולת[ם להעלות] הנשמה לקשרה בצרור החיים להאיר' באור אה\"ר שהן בחי' יומין עילאין דזקנה הנ\"ל באברהם שלא הי' בכח האדם כלל להגיע לזה [ב]כל מיני התפעלות אוי\"ר שמצד השכל והשגתו גם ברוב יגיעה כל ימיו רק ע\"י לבושים דתו\"מ שהן רק<sup data-n=\"2695\">438</sup> בחי' ימי השלימים<sup data-n=\"2696\">439</sup> דבחי' המקיפי' כנ\"ל<sup data-n=\"2697\">440</sup>. וז\"ש בזהר ואברהם זקן בא בימים באינון לבושין כו', דהיינו ענין ובחי' יומין עילאין הנ\"ל שהן בחי' המקיפי' דנר\"נ בהתפעלו' עצמיות התענוג והרצון שלמעלה מן הטעם ושכל הגלוי כו' שאין בזה שינוי כלל פעם כך כנ\"ל, ואמנם הימים אלה דבחי' הזקנה שקנה חכ' כנ\"ל באין למטה בבחי' לבושים דוקא והם בחי' לבושי' דמחדו\"מ דתו\"מ מצד שהמקיפי' שורים על הלבושי' כנ\"ל.",[["2682","426","<b>וז' מצות דרבנן</b>: ראה אגה\"ק סכ\"ט. ד\"ח פנ\"ו. פס\"ד. לקו\"ש יתרו (כרך כא) ע' 401 ואילך. שופטים (כרך כט) ע' 104 ואילך. וש\"נ."],["2683","425","<b>תר\"ך. . בתרי\"ג. . וז' מצות דרבנן</b>: ראה תורת העולה להרמ\"א ח\"ג פל\"ח (לב, א). של\"ה יתרו שיו, א. מאו\"א מערכת תר\"ך סנ\"ו. הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"א לע' שלח."],["2684","428","<b>שבחה\"ק</b>: הט: שבחכמה עילאה הקדומה."],["2685","429","<b>ואשים דברי בפיך</b>: ישעי' נא, טז."],["2686","430","<b>במחשבתו</b>: ה: לבו ומחשבתו בתו'."],["2687","427","<b>במצות ת\"ת בדבור בפה. . בהגיון ומח'</b>: ראה ה' ת\"ת לאדה\"ז פ\"ב, הי\"ב. לעיל פ' בשלח קסט, ב. וש\"נ."],["2688","431","<b>שבתו'</b>: ה: שבתו\"מ."],["2689","432","<b>אין בן דוד בא</b>: ראה ע\"ז ה, א וברש\"י ותוס' שם. הנסמן במאמרי אדה\"א בראשית ע' ק. שה\"א צח, א ובהנסמן במ\"מ לשם."],["2690","433","<b>ואז</b>: הט: ואין זה."],["2691","434","<b>בארץ</b>: שם: בא."],["2692","435","<b>דתו\"מ הכל</b>: שם: דמדו\"מ הנ\"ל."],["2693","436","<b>העליון כו'</b>: שם: ליתא."],["2694","437","<b>והיתה נפש אדוני צרורה</b>: שמו\"א כה, כט."],["2695","438","<b>רק</b>: הט: ליתא."],["2696","439","<b>השלימים</b>: ה: הזקנה. ט: השלימות."],["2697","440","<b>כנ\"ל</b>: שם: וד\"ל."]]],[2300550579,"(יח) <sup data-n=\"2698\">441</sup> <b>ושרש</b> התו\"מ הן בחי' מקיפים עילאין<sup data-n=\"2699\">442</sup> ששורים על הלבושי' דמחדו\"מ בג'<sup data-n=\"2700\">443</sup> לבושי' דמחדו\"מ דאדם בתו\"מ בכל יום ויום ועושה לבוש[א] דכי[א] מבירורי' דעה\"ד כו'. ובהגיע לג\"ע תוכל ע\"י דוקא להגיע למעלה משרש' ומקורה וכמו שמכריזין בג\"ע אשרי מי שבא לכאן ותלמודו בידו<sup data-n=\"2701\">444</sup> דוקא, שעי\"ז תתקשר בצרור החיים באה\"ר בתענוג העצמי' שא\"א להגיע ע\"י שום עבודה ויגיעה בעולם וה[וא] בחי' הלבושי' שע\"ז א' ואברהם זקן בא בימים שהי' לזקנותו דוקא שלא הי' כן קודם שנעשה זקן שקנה חכ', ואע\"פ שקיים אברהם כל התו[\"מ] ברוחני'<sup data-n=\"2702\">445</sup> למעלה<sup data-n=\"2703\">446</sup>, אבל בימי הזקנה בא בבחי' לבושי' לנפשו שהן בחי' מקיפים העליונים שנק' יומין עילאין שלמעלה הרבה מיחו\"ע שנעשה למעלה מכל התו\"מ שהן הע[ו]בדות שלו במס\"נ שעשה כל ימיו כו' וד\"ל.\n<b>וזהו</b> מ\"ש יחיינו מיומים<sup data-n=\"2704\">447</sup> ביום השלישי יקימנו ונחי' לפניו, פי' יחיינו מיומים ב' ימים היינו ענין ושרש התו\"מ כמו שהוא למעלה ממש [ב]עצמותו ית' דכתי' ואהי' אצלו אמון<sup data-n=\"2705\">448</sup> שעשועים יום יום ב' ימים ב' מדרגות דתושב\"כ ושבע\"פ או תו\"מ והכל א', וע\"ז א' ואהי' אצלו ממש שעשועים יום יום שהוא בחי' שעשועי' העצמי' שבעצמו' א\"ס ב\"ה ממש [ש]משתעשע בח\"ע הקדומה הכלולה בעצמותו ממש כו', והן בחי' פנימי' התענוג ורצה\"ע שבתו\"מ כמ\"ש למעלה שהן בחי' א\"ס ממש כמו ארוכה מארץ מדה<sup data-n=\"2706\">449</sup> ורחבה מני ים העליון, וכן רחבה מצותך מאד. ופי' יום יום שזהו כמו הימים שנמשכו למטה שנא' ימים יוצרו ולא אחד בהם כו', כך יש ימים למעלה שנק' ימי קדם בבחי' קדמונו ש\"ע שמאירים בבחי' א\"ס כמו ימי עולם ושנים קדמוניות<sup data-n=\"2707\">450</sup> והן בחי' מקיפי' [דמדות] דע\"י וא\"א, ומשם נמשך בחי' שעשועים שבתו\"מ לבא למטה בהתלבשות באבי\"ע עד לנשמות בג\"ע <span data-k=\"pg\">תלט</span> ּ וגם לנשמות בגופי' וכמ\"ש דוד אני תורתך שעשעתי<sup data-n=\"2708\">451</sup> וכתי' ושעשועי את בנ\"א<sup data-n=\"2709\">452</sup> כו'. וזהו יחיינו מיומים [ש]משעשועים דיום יום דתו\"מ שלמעלה יחיינו לנשמות בג\"ע שישיגו סודות התו' ופנימי' השעשועי' שבה, וגם למטה בעוה\"ז בתו' הנגלית לנו לשמור ולעשות ולברר לעה\"ד טו\"ר בסו\"מ וע\"ט בפו\"מ יחיינו לנשמות שעי\"ז יעלו להדבק [למעלה] בצרור החיים באוי\"ר ודביקות אמיתי'. וזהו יחיינו מיומים בתוס'<sup data-n=\"2710\">453</sup> אור וחיות חדש שלמעלה ממקור הנשמות כנ\"ל וקאי לע\"ל שהוא בימוהמ\"ש שיחיינו מיומים העליוני' שיתגלו טעמי תו' הע'",[["2698","441","<b>(יח)</b>: ט: ליתא. ראה לעיל הערה 409."],["2699","442","<b>עילאין</b>: הט: העליונים כנ\"ל."],["2700","443","<b>בג'</b>: ה: דוקא ובג'. ט: דוקא כנ\"ל ובכל."],["2701","444","<b>אשרי. . ותלמודו בידו</b>: פסחים נ, א."],["2702","445","<b>שקיים אברהם. . ברוחני'</b>: ראה יומא כח, ב. לעיל פ' וארא סג, ג. וש\"נ"],["2703","446","<b>למעלה</b>: ט: ליתא."],["2704","447","<b>יחיינו מיומים</b>: הושע ו, ב. ראה גם לעיל פ' בא צו, ג. וש\"נ."],["2705","448","<b>ואהי' אצלו אמון</b>: משלי ח, ל [בדילוג]."],["2706","449","<b>ארוכה מארץ מדה</b>: איוב יא, ט."],["2707","450","<b>ימי עולם ושנים קדמוניות</b>: ראה מלאכי ג, ד."],["2708","451","<b>אני תורתך שעשעתי</b>: תהלים קיט, ע."],["2709","452","<b>ושעשועי את בנ\"א</b>: משלי ח, לא."],["2710","453","<b>מיומים בתוס' אור</b>: ה: ממש בתוס' אור. ט: ממש בתו\"מ באור."]]],[2300550590,"כמ\"ש<sup data-n=\"2711\">454</sup> שהוא בבחי' שעשועי' העצמי' שנק' שעשוע[י] המלך בעצמותו<sup data-n=\"2712\">455</sup> ממש כו'.\n<b>וז\"ש</b> [ו]אברהם זקן שקנה חכ' דתו' כמו שהיא במקורה ממש בא בימים העליוני' בשעשועי' דיום יום כנ\"ל שז\"ש נשבעת לאבותינו מימי קדם כו', והן בחי' יומין [עילאין] הנ\"ל שנק' ימי הזקנה כמו דסבא דעתי' סתים כו' שנק' ימי השלימ[ים ב]שלימו' דיומין<sup data-n=\"2713\">456</sup> העליונים הנ\"ל שאין בהם שינוי כלל וכמ\"ש כי לא אדם הוא להנחם כו', דבחי' אדם דאצי' שמקבל מאו\"א שנק' יומין תתאין בכלל יש בו שינוי השכל והמדות<sup data-n=\"2714\">457</sup> מדבר להיפוכו כמו במבול שא' [ויתעצב כו'] וינחם ה'<sup data-n=\"2715\">458</sup> כו'. אבל ב[חי'] מדות וחכ' שבתו' הרי אין בהם שינוי כלל [וכלל] להתחלק<sup data-n=\"2716\">459</sup> מחסד לדין ומדין לחסד, כי משפט התו' במדות כמו כשר פסול טמא טהור זכאי חייב וכו' כמו שכבר נתבאר<sup data-n=\"2717\">460</sup> ע\"פ החה\"ק שבתו[רה] לא יהופך<sup data-n=\"2718\">461</sup> מטמא להיות טהור ולא מפסול כשר ומחייב זכאי כו' כמ\"ש להבדיל בין הטמא<sup data-n=\"2719\">462</sup> כו' וכמ\"ש כל אמרת אלוה צרופה<sup data-n=\"2720\">463</sup> כו' ולא ישתנה לעולם מכל מצות וחוקות דתו' אף כקוצו של יו\"ד, דאע\"פ שמפלפלים ומטהרים הטמא כו' [אבל] לאחר הבירור שע\"י הפלפול יבא על האמת דמשפט התו' שזה טמא וזה טהור ולא ישתנה עוד, שמפני זה נק' התו' אמת<sup data-n=\"2721\">464</sup> שהוא חותמו של הקב\"ה<sup data-n=\"2722\">465</sup> [שהוא] כמו החותם [ש]אין אחר החתימה שינוי כלל כמ\"ש חתום תו' בלמודי<sup data-n=\"2723\">466</sup> ונק' חותמו של הקב\"ה אמת שכל שינוי אינו אמת כו'. אע\"פ שגם התו\"מ נק' בבחי' אדם כמ\"ש וזאת תורת האדם<sup data-n=\"2724\">467</sup> ומצות נק' רמ\"ח אברים<sup data-n=\"2725\">468</sup> ובחי' אדם הוא<sup data-n=\"2726\">469</sup> להנחם ולהשתנות דוקא, זהו בבחי' אדם תתאה שהוא (בחי' ז\"א) אבל בחי' אדם עילאה (בחי' א\"ק או א\"א כו'<sup data-n=\"2727\">470</sup> שרש התו\"מ בחי' המדות דח\"ס<sup data-n=\"2728\">471</sup> והרצון שבו בלתי שינוי כלל, ולזאת ירדה התו' מלמעלה למטה להיות בדומה לאדם העליון וכמ\"ש ויקם עדות ביעקב<sup data-n=\"2729\">472</sup> ותו' שם בישראל וד\"ל (ומ[ה] ש[ארז\"ל] י\"ב שעות<sup data-n=\"2730\">473</sup> [הוי יום] ג\"ש יושב ועוסק בתו' שני' יושב ודן ע\"פ משפט התו' ויש בדין זה שינויים, היינו דוקא ע\"פ מדות וחכ' שבתו' דוקא).\n<b>וזהו</b> יחיינו מיומים [דתו\"מ] שהן בחי' מקיפי' דיומין עילאין הנ\"ל, אך ביום הג' יקימנו ונחי' לפניו ממש שזהו העוה\"ב [שלאחר תחה\"מ] שלמעלה גם מיומין דתו\"מ הנ\"ל, ד[ב]עוה\"ב הגם שהוא שכר המצות שבעוה\"ז, אבל שרשו בעצמו' א\"ס ב\"ה",[["2711","454","<b>תו' הע' כמ\"ש</b>: שם: התו\"מ העליונים כמו."],["2712","455","<b>שעשוע[י] המלך בעצמותו</b>: נסמן לקמן פ' תרומה שיח, ב."],["2713","456","<b>דיומין</b>: הט: ימים."],["2714","457","<b>השכל והמדות</b>: שם המדות והשכל."],["2715","458","<b>ויתעצב. . וינחם ה' </b>[הט: ליתא]: בראשית ו, ו [בהיפך הסדר]."],["2716","459","<b>להתחלק</b>: שם: להתחלף."],["2717","460","<b>נתבאר</b>: שם: נברר."],["2718","461","<b>יהופך</b>: שם: ישונה להפוך."],["2719","462","<b>להבדיל בין הטמא</b>: שמיני יא, מז."],["2720","463","<b>כל אמרת אלוה צרופה</b>: משלי ל, ה. ראה גם הנסמן לעיל פ' בשלח קעג, ב."],["2721","464","<b>נק' התו' אמת</b>: ראה ברכות ה, ב. מאמרי אדה\"א ויקרא ח\"א ע' שסט. וש\"נ."],["2722","465","<b>אמת שהוא חותמו של הקב\"ה</b>: שבת נה, א."],["2723","466","<b>חתום תו' בלמודי</b>: ישעי' ח, טז."],["2724","467","<b>וזאת תורת האדם</b>: שמו\"ב ז, יט. ראה גם זהר (רע\"מ) משפטים קיז, ב. צו כט, ב. הנסמן במאמרי אדה\"א דברים ח\"ד ע' א'שכז."],["2725","468","<b>ומצות נק' רמ\"ח אברים </b>[ט: ניתוסף: באדם העליון]: ראה ת\"ז ת\"ל (עד, סע\"א). שע\"ת עב, ג הערה 17."],["2726","469","<b>אדם הוא</b>: ה: אדה\"ע הוא. ט: אדם העליון."],["2727","470","<b>כו'</b>: כנצ\"ל: כו')."],["2728","471","<b>דח\"ס</b>: שם: והחכמה."],["2729","472","<b>ויקם עדות ביעקב</b>: תהלים עח, ה."],["2730","473","<b>י\"ב שעות</b>: ראה ע\"ז ג, ב."]]],[2300550601,"שלמעלה גם מתו\"מ שמשתעשע בה יום יום הנ\"ל. כי מ\"ש התו' ואהי' אצלו שעשועים כו' אין לזה ערך לגבי שעשוע המלך שמצד עצמותו ממש והוא בחי' העדן סתימאה<sup data-n=\"2731\">474</sup> שנא' בו עין לא ראתה<sup data-n=\"2732\">475</sup> אלקי' זולתך כו'. וז\"ש ונחי' לפניו ממש בחיי החיים דמהו\"ע א\"ס ב\"ה ממש וכמ\"ש ובשביעית יצא לחפשי חנם<sup data-n=\"2733\">476</sup> בלא תו[\"מ] כמ\"ש במ\"א. וז\"ש באברהם <span data-k=\"pg\">880</span> ּ אחר שהי' זקן בא בימים דתו\"מ הנ\"ל וה' בירך את אברהם בכל<sup data-n=\"2734\">477</sup> שהוא [חיי] העוה\"ב ממש שנק' כל<sup data-n=\"2735\">478</sup> כידוע שהאבות הטעימן מעין עוה\"ב<sup data-n=\"2736\">479</sup> ממש שזהו למעלה מיומין עילאין דזקנה הנ\"ל, וז\"ש רז\"ל מי איכא<sup data-n=\"2737\">480</sup> ספיקא<sup data-n=\"2738\">481</sup> קמי' קוב\"ה ממש [ד]מ\"ש [בדניאל] וע\"י יתיב<sup data-n=\"2739\">482</sup> כו' שהוא בחי' זקנה היינו בחי' ע\"י<sup data-n=\"2740\">483</sup> וא\"א דאצי' שהוא בחי' האחרונה שבעולם הא\"ס<sup data-n=\"2741\">484</sup> כידוע וד\"ל.\n(יט) <sup data-n=\"2742\">485</sup> <b>וזהו</b> [מ\"ש] את מספר ימיך אמלא, פי' מספר הימים שניתן לאדם ע' שנה לתקן נפשו בתו\"מ שעי\"ז יצליח לעשות פרי למעלה [ולמטה] כמ\"ש יחיינו מיומים כו', מספר הזה אמלא לימי[ך] שיעלו למעלה להיות בבחי' יומין עילאין דבחי' המקיפי' ע' שנה מליאי'<sup data-n=\"2743\">486</sup> בבחי' השלימות שאין בהם שינוי כלל כמו ימי קדם הנ\"ל וכמ\"ש בא בימים כו'. וזהו ענין אריכות ימים כזקן ושבע ימים שזהו פשט הכתוב שימלא ימיך להיות הרבה ביותר מכפי מדתם ע' שנה, [ו]כמו בימוהמ\"ש שהנער בן ק' שנה ימות<sup data-n=\"2744\">487</sup> כמו אריכות ימים דאדה\"ר ודורות שאחריו, אך מ\"מ יש בזה שיעור עד שיכלו מאחר שנק' ימי הזקנה עכ\"פ רק שהן בבחי' השלימות דחכ' ומדות דא\"ק כו'. אמנם עלי' שני' הוא שיעלו<sup data-n=\"2745\">488</sup> בימי עוה\"ב שיחיו חיי עולם בבחי'<sup data-n=\"2746\">489</sup> נצחי[י]' ממש [בבחי' נצחי'] דא\"ס ממש שליכא זקנה קמי' כלל וכמ\"ש אין קצבה לשנותיך<sup data-n=\"2747\">490</sup> ואין קץ לאורך ימיך כו' ונק' יום שכולו ארוך<sup data-n=\"2748\">491</sup> גם בתחלתו כו' שאין לו תחלה ואין לו תכלה<sup data-n=\"2749\">492</sup> כו' יום שכולו טוב<sup data-n=\"2750\">493</sup> שלמעלה גם מבחי' ימי קדם ושנים קדמוניות דא\"ק<sup data-n=\"2751\">494</sup> כו' כמ\"ש ונחי' לפניו ממש [שלמעלה] מחי[ות] ימים העליונים דתו\"מ. וגם<sup data-n=\"2752\">495</sup> את מספר ימיך אמלא בשלימות העצמו'<sup data-n=\"2753\">496</sup> דא\"ס ממש והוא לעוה\"ב אחר תחה\"מ שלמעלה מבחי' אדם לגמרי, וזהו שאחר שא[מר] לא תהי' משכלה ועקרה בארציך באה\"ח דתו\"מ להיות' מבחי' מקיפי'",[["2731","474","<b>העדן סתימאה</b>: ראה גם לעיל פ' שמות ה, ג. וש\"נ."],["2732","475","<b>העדן. . עין לא ראתה</b>: ראה ברכות לד, ב. ישעי' סד, ג."],["2733","476","<b>ובשביעית יצא לחפשי חנם</b>: משפטים כא, ב. ראה גם לעיל פ' שמות א, ב. וש\"נ."],["2734","477","<b>וה' בירך את אברהם בכל</b>: ח\"ש כד, א."],["2735","478","<b>העוה\"ב. . שנק' כל</b>: ראה גם לעיל פ' בשלח קמט, א. וש\"נ."],["2736","479","<b>שהאבות הטעימן מעין עוה\"ב</b>: ראה ב\"ב טז, סע\"ב ואילך."],["2737","480","<b>מי איכא זקנה קמי'</b>: יבמות טז, ב."],["2738","481","<b>ספיקא</b>: הט: זקנה."],["2739","482","<b>[בדניאל] וע\"י יתיב</b>: ז, ט. ראה גם לקמן פ' פקודי תנז, ג הערה 316."],["2740","483","<b>ע\"י. . בחי' האחרונה שבעולם הא\"ס</b>: ראה גם לעיל פ' בשלח רד, ג. וש\"נ."],["2741","484","<b>וא\"א. . בחי' האחרונה שבעולם הא\"ס</b>: ראה גם מאמרי אדה\"א קונטרסים ע' ד. וש\"נ."],["2742","485","<b>(יט)</b>: ט: (כא). פ\"כ נרשם לעיל על יד הערה 409. פכ\"ב נרשם להלן על יד הערה 515."],["2743","486","<b>ע' שנה מליאי'</b>: הט: העליונים שנק' מ[י]לואים."],["2744","487","<b>שהנער בן ק' שנה ימות</b>: ישעי' סה, כ."],["2745","488","<b>שיעלו</b>: הט: שיהי'."],["2746","489","<b>בבחי'</b>: שם: ליתא."],["2747","490","<b>אין קצבה לשנותיך</b>: תפלת מוסף לימים נוראים קודם קדושת כתר."],["2748","491","<b>יום שכולו ארוך</b>: ראה קדושין לט, ב. הנסמן לעיל פ' בשלח רט, ג."],["2749","492","<b>שאין לו תחלה ואין לו תכלה</b>: ראה חובת הלבבות שער היחוד פ\"ה. המשך תרס\"ו ע' כ."],["2750","493","<b>יום שכולו טוב</b>: נוסח הרחמן (שבברכת המזון) ליו\"ט."],["2751","494","<b>ימי קדם. . דא\"ק</b>: ראה גם שה\"א קה, א ובהערה 7."],["2752","495","<b>וגם</b>: הט: וז\"ש."],["2753","496","<b>העצמו'</b>: שם: דימים."]]],[2300550611,"דנר\"נ דאדם א[מר] עוד למעלה מזה את מספר ימיך אמלא בחיי עוה\"ב וד\"ל.\n<b>ונמצא</b> שיש ב' אופנים בפי' את מספר ימיך אמלא א' דקאי על הימים שנק' לבושי' דוקא [כנ\"ל], והן לבושי' דתו\"מ במחדו\"מ שאדם לומד ועושה מצות בכל יום ויום שנעשים לבושי' לנשמה שנק' לבושי' דכיא שמתבררים מעה\"ד טו\"ר, ועי\"ז מקבל אדם גילוי אלקו' בנפשו באוי\"ר ודביקות אמיתי שנמשכי' לו מכח הצומח שבארץ העליונה בתוס' אור גדול אע\"פ שלומד בפשוטי התו\"מ ואין מגיע לו מזה שום אוי\"ר בשעת מעשה, מ\"מ הרי התו\"מ<sup data-n=\"2754\">497</sup> נק' אור זרוע בארץ עליונה שתצמיח רב חסד העליון על הנשמות להחיותם ולהאיר להם בלבושים הללו בחי' אה\"ר בתענוגי' בג\"ע. וז\"ש והלך לפניך צדקיך שהן המצות וכבוד ה' יאספך<sup data-n=\"2755\">498</sup> זהו אור דתו' שנעשו לבושי מקיפים לנשמות בג\"ע ולבושים הללו מאירים ומזהירים בתוס' אור גדול בהבהקה יתירה (ונק' זיהרא עילאה<sup data-n=\"2756\">499</sup> כמ\"ש במ\"א בתו[רתו] של ר\"מ כתיב כתנות אור [באל\"ף]<sup data-n=\"2757\">500</sup> שזהו לאחר הבירור דחשמ\"ל דנוגה ע\"י התו\"מ בעוה\"ז שנק' לבושי דכיא דוקא). וז\"ש את מספר ימיך אמלא ש[ה]ימים עצמ[ן] שנק' לבושי' לנפש יאירו ויזהירו בתוס' אור וחיות גדול, והוא בחי' אור הגנוז שבתוך <span data-k=\"pg\">תמ</span> ּ הימים האלה משרש התו\"מ כמ\"ש שהוא<sup data-n=\"2758\">501</sup> למעלה בשעשועי' העצמי' יום יום הנ\"ל, וע\"ד שא' בזהר [בפי'] השמים מספרים מנהרין ומנצצין<sup data-n=\"2759\">502</sup> כל' ספי' ובהירות כאבן ספיר<sup data-n=\"2760\">503</sup> כו' כך פי' מספר ימיך אמלא<sup data-n=\"2761\">504</sup> לשון ספיר[ות] ובהירות אור להיות בבחי' אור דתוה\"ק<sup data-n=\"2762\">505</sup>. וזהו את מספר ימיך אמלא למלאות מבחי' ימים העליוני' דתו\"מ וכמו שהתו' אור זרוע בארץ העליונה<sup data-n=\"2763\">506</sup> מאיר גם בימי[ם] שניתן לאדם במספר ש[י]צמיח מכח הצומח שבארץ כנ\"ל. ופי' הב' במספר הזה דימי[ם] שא' אמלא אני אמלא דוקא, כי בלימוד דתו' בכל יום זהו על האדם לעשות ולתקן לבושי' דכיא שעי\"ז יאיר[ו] אור העליון דתו\"מ שלמעלה וד\"ל<sup data-n=\"2764\">507</sup>, ועוי\"ל<sup data-n=\"2765\">508</sup> זה ישיגו פנימי' התו\"מ<sup data-n=\"2766\">509</sup> בג\"ע כנ\"ל, אבל בחי' לבושי' אלו שרשם רק בשעשועי' העצמי'<sup data-n=\"2767\">510</sup> דיום יום דתו\"מ הנ\"ל<sup data-n=\"2768\">511</sup>. ואמנם עלי' הב' הנ\"ל שלמעלה מזה שהוא בחי' השלימות דחיי עולם הנצחי' [ד]עוה\"ב שהוא בבחי' א\"ס ממש [שלמעלה] מימים",[["2754","497","<b>התו\"מ</b>: שם: התורה."],["2755","498","<b>והלך לפניך צדקיך. . וכבוד ה' יאספך</b>: ישעי' נח, ח [ושם כבוד — ראה גם לקמן פ' ויקהל תיט, ג. לעיל פ' וארא סב, ג. מאמרי אדה\"א נ\"ך ע' תסז]."],["2756","499","<b>זיהרא עילאה</b>: ראה זהר בראשית לו, ב. הנסמן לעיל פ' שמות ח, ב."],["2757","500","<b>כתנות אור [באל\"ף]</b>: נסמן לעיל רפז, ב."],["2758","501","<b>כמ\"ש שהוא</b>: הט: כמו שהן."],["2759","502","<b>השמים מספרים מנהרין ומנצצין</b>: תהלים יט, ב. ראה זהר תרומה קלו, ב. סידור שחרית לשבת קעח, א ואילך. פיה\"מ ו, ב."],["2760","503","<b>כאבן ספיר</b>: יחזקאל א, כו."],["2761","504","<b>אמלא</b>: הט: ליתא."],["2762","505","<b>דתוה\"ק</b>: שם: דתורה העליונה."],["2763","506","<b>העליונה</b>: שם: ע[י]לאה."],["2764","507","<b>וד\"ל. . . כנ\"ל</b>: ה: (וע\"י. . כנ\"ל)."],["2765","508","<b>וד\"ל ועוי\"ל</b>: הט: וע\"י לבוש."],["2766","509","<b>התו\"מ</b>: שם: התורה."],["2767","510","<b>העצמי'</b>: שם: ליתא."],["2768","511","<b>הנ\"ל</b>: שם: ליתא."]]],[2300550619,"דתו\"מ כנ\"ל שהוא נק' יום שכולו ארוך, אין זה בכח האדם כלל<sup data-n=\"2769\">512</sup> למלאות ולהשלים לימי[ו] גם בעסקו בתו\"מ מטעם הנ\"ל בענין חיי עוה\"ב שע\"ז א' ובשביעית יצא לחפשי חנם בלא מצות דאם צדקת מה תתן לו<sup data-n=\"2770\">513</sup> כו'. וע\"כ ע\"ז א' את מספר ימיך שע\"י תו\"מ אלו אמלא דוקא במילוי ושלימות דעצמו' א\"ס ב\"ה שנק' שלימותא דכולא<sup data-n=\"2771\">514</sup> (וכמו במשיח שא' חיים נתת לו חיים נצחי' וד\"ל). ומעתה<sup data-n=\"2772\">515</sup> י\"ל ענין בחי' הסמיכות הזאת דאת מספר ימיך אמלא למה שקדם לו לא תהי' משכלה ועקרה בארציך כו', דלפי כל הנ\"ל אין להם סמיכות [כ\"כ ד]גם דבארציך קאי בא\"י שהוא נק' אה\"ח למעלה וע\"י תו\"מ הזרועים בה וע\"י אור הזרוע לצ\"ע [כו' כנ\"ל] מ\"מ עיקר ענין זה דמספר ימיך אמלא קאי לע\"ל בימוהמ\"ש ועוה\"ב [כנ\"ל].\n(ך) <sup data-n=\"2773\">516</sup> <b>אך</b> הנה תחלה י\"ל סמיכת פסוק זה דלא תהי' משכלה [כו' לפסוק] שקדם לו והוא מ\"ש ועבדתם את ה' אלקיכם ובירך את לחמך ואת מימך והסרותי מחלה מקרבך, ואח\"כ סמך לו לא תהי' משכלה [כו'] דמשמע דהא בהא תליא. והענין הוא ע\"פ פשוט שכדי שלא תהי' משכלה ועקרה בארצך צריך שיברך ה' תחלה לחמך ומימך ולהסיר כל מחלה כו' ואז ממילא לא תהי' משכלה כו' [כי ידוע דכל סיבת חיי אדם<sup data-n=\"2774\">517</sup> בבריאות שלימה תלוי במזג הרכבה שבארץ ומים טהורים ונקיים שבסביבה כמו שאמרו המרגלים על א\"י דארץ אוכלת יושביה<sup data-n=\"2775\">518</sup> כו', ויש ארץ מגדלת בני אדם לאורך ימים וזה תלוי ג\"כ במים שבנהרות שלא יהי' בהן סיבת התחלואים הרעים שממיתים את בני אדם. וז\"ש תחלה ובירך את לחמך שבארץ ומימיך שיהי' נקי מכל פסולת ומכל סיג ורע והסירותי מחלה שלא תבא בקרביך ואז ממילא לא תהי' משכלה] יולדת וקוברת שגם בבחי' הארץ<sup data-n=\"2776\">519</sup> לא תהי' הארץ יושבת<sup data-n=\"2777\">520</sup> ואוכלת יושביה. והנה הזכיר כאן ג' דברים בכלל בני חיי ומזוני, תחלה הזכיר מזוני שהוא סיבת החי[ות] הטוב והוא כשיברך לחם ומים ויסור כל חולי רעה, ואח\"כ בני שלא תהי' משכלה כו' ואח\"כ חיי שהוא אריכות הימים כמ\"ש את מספר ימיך אמלא ביתר מכפי מדתם כנ\"ל. וכמו\"כ<sup data-n=\"2778\">521</sup> יובן כ\"ז ברוחניות החיות האלקי [ל]נשמות בארץ עילאה וארץ תתאה [כו', כנ\"ל דתחלה הזכיר בחי' מזוני דלחם ומים שהוא התו\"מ בגשמיות שבאו למטה לברר לעה\"ד טו\"ר שנק' מזון לחם לנשמה וכמו ותורתך בתוך מעי<sup data-n=\"2779\">522</sup> וכתיב לכו לחמו בלחמי<sup data-n=\"2780\">523</sup>, ולחם זה דתורה יוצא מארץ עילאה לארץ תתאה",[["2769","512","<b>כלל</b>: שם: ליתא."],["2770","513","<b>דאם צדקת מה תתן לו</b>: איוב לה, ז."],["2771","514","<b>א\"ס. . שלימותא דכולא</b>: ראה ת\"ז בהקדמה (יז, ב). עבודת הקדש ח\"א רפ\"ח."],["2772","515","<b>ומעתה</b>: ט: נרשם כאן פכ\"ב. פכ\"א נרשם לעיל על יד הערה 485. פכ\"ג נרשם להלן על יד הערה 521."],["2773","516","<b>(ך)</b>: ט: ליתא. ראה הערה שלפנ\"ז."],["2774","517","<b>דכל סיבת חיי אדם</b>: ראה גם מאמרי אדה\"א הנחות תקע\"ז ע' עז וע' פה. לעיל פ' שמות מ, ב. וש\"נ."],["2775","518","<b>דארץ אוכלת יושביה</b>: שלח יג, לב."],["2776","519","<b>בבחי' הארץ</b>: ה: במין האדם. ט: בני האדם."],["2777","520","<b>יושבת</b>: שם: משכלת."],["2778","521","<b>וכמו\"כ</b>: ט: נרשם כאן פכ\"ג. פכ\"ב נרשם על יד הערה 515. פכ\"ד נרשם לקמן על יד הערה 580."],["2779","522","<b>ותורתך בתוך מעי</b>: תהלים מ, ט."],["2780","523","<b>לכו לחמו בלחמי</b>: משלי ט, ה."]]],[2300550625,"ו]כמ\"ש ארץ יצא ממנה לחם<sup data-n=\"2781\">524</sup> כו', וכנ\"ל בענין ארץ דמפקי מזון רוחני לנשמות ומלאכי' וכן המזון<sup data-n=\"2782\">525</sup> דתו' נק' ג\"כ בשם מים כמ\"ש<sup data-n=\"2783\">526</sup> הוי כל צמא לכו למים<sup data-n=\"2784\">527</sup> כו' שזהו<sup data-n=\"2785\">528</sup> בכלל אכילה ושתי' שע\"ז הוסד יסוד מזג ההרכבה דטבע הארץ לחי[ות] הטוב דבנ\"א ולהסיר כל מחלה כו'. וכך הוא בבחי' לחם ומים דתו' בארץ העליונה שבא למטה בעה\"ד טו\"ר להיות מזון רוחני לנשה\"א<sup data-n=\"2786\">529</sup>, וע\"ז א[מר] ועבדתם את ה' אלקיכם ע\"ד הנ\"ל שיוקלט אור דה' ממש בפנימי' המוח והלב אז ובירך את לחמך ואת מימיך כו' <span data-k=\"pg\">882</span> ּ דתו\"מ שיעשו בארץ באופן שיהא בחי' חיות [טוב מאד] לנשמות שנק' אדם שעל הארץ כו' ויוסר מהם כל מחלה רעה כו'.\n<b>ותחלה</b> י\"ל מהו ענין מחלה ולא [אמר] חולי רעה<sup data-n=\"2787\">530</sup> ומ\"ש מקרבי[ך] דוקא דמשמע המחלה שכבר נשרשה ונדבקה [בקרביך] בתוך תוכם כו'. והענין הוא כידוע בבחי' עה\"ד טו\"ר שחטא בו אדה\"ר שעי\"ז נתקללה הארץ שחוץ לג\"ע שנעשה בה תערובות טו\"ר<sup data-n=\"2788\">531</sup>, והעיקר מ[ן ה]נהרות שיצאו חוץ לג\"ע עד שבכל אקלים יש בדצח\"מ שבו תערובות טו\"ר כמו עשבים ממיתים ומחיים, וכך יש בחלק החי טורפי' ומזיקים וגם בבנ\"א רעים וטובים. והיינו ג\"כ סיבת כל חולי רעה דממית שיש בכל חלקי הארץ מסיבת העכרורית שב[אויר ה]ארץ ומים שבנהרות כו' ולע\"ל תטהר הארץ מחטא עה\"ד וע\"כ יוסר כל מחלה כו' ויהי' הכל בבחי' טוב ולא רע כלל, וגם בחיות ובהמות וצו\"ד<sup data-n=\"2789\">532</sup> כמו לא ירעו ולא ישחיתו<sup data-n=\"2790\">533</sup> כו' וכה\"ג במ\"ש<sup data-n=\"2791\">534</sup> בג\"ע קודם חטא עה\"ד שלא הי' שם מחלקי הרע כלל וכלל רק בחי' הטוב כו'. וכך הוא בבחי' חיות הרוחני האלקי' הנמשך באדם שהוא בצלם אלקי'<sup data-n=\"2792\">535</sup> יבוער ממנו רוח הטומאה ולא יהי' בו רק בחי' הטוב ולא רע כלל וכלל כמו באדה\"ר קודם החטא שלא הי' יניקה לחיצונים כלל שנק' נגעי [בני אד]ם<sup data-n=\"2793\">536</sup>, וז\"ש והסירותי כו' כל מחלה גם ברוחני' הרע שהוא שרש החטא עה\"ד כו'. והענין הוא כידוע שז' מדות הרעות דק\"נ כמו התאוות הרעות באש זרה והרציחה וכעס וכל מיני רע הכל בא מכח ומקור א[חד] והוא בחי' דעת דקליפה שזהו שנק' עה\"ד טו\"ר, והוא בחי' ההרגשה<sup data-n=\"2794\">537</sup> שמרגיש א\"ע ביותר כמו בידיעת והרגשת הטוב והרע שמרגיש שזה [ה]דבר טוב לנפשו ונמשך אחריו במורגש ביותר וכמ\"כ מרגיש ויודע בחי' הרע לברוח ממנו, דהיינו הטו\"ר שבנפשו אם הוא שלם במעלה<sup data-n=\"2795\">538</sup> טובה מאד<sup data-n=\"2796\">539</sup> ירגיש הדבר בעצמו ואם יש",[["2781","524","<b>ארץ יצא ממנה </b>[הט: ממנה יצא]<b> לחם</b>: איוב כח, ה."],["2782","525","<b>המזון</b>: הט: (ה)מים."],["2783","526","<b>כמ\"ש</b>: ה: וכמ\"ש. ט: כידוע ממ\"ש."],["2784","527","<b>הוי כל צמא לכו למים</b>: ישעי' נה, א."],["2785","528","<b>שזהו</b>: הט: שמים."],["2786","529","<b>לנשה\"א</b>: שם: לנשמה האלקית."],["2787","530","<b>רעה</b>: שם: ליתא."],["2788","531","<b>עה\"ד טו\"ר. . אדה\"ר. . תערובות טו\"ר</b>: ראה לעיל פ' שמות מ, ב. וש\"נ."],["2789","532","<b>וצו\"ד</b>: הט: וצומח ודומם."],["2790","533","<b>לא ירעו ולא ישחיתו</b>: ישעי' יא, ט. סה, כה."],["2791","534","<b>במ\"ש</b>: הט: וכמו שהי'."],["2792","535","<b>באדם שהוא בצלם אלקי'</b>: בראשית א, כז. נח ט, ו."],["2793","536","<b>נגעי [בני אד]ם</b>: שמו\"ב ז, יד. ראה גם מאמרי אדה\"א קונטרסים ע' תקלט. וש\"נ. שע\"ת נא, סע\"ב."],["2794","537","<b>עה\"ד. . ההרגשה</b>: ראה תו\"ח בראשית ל, ב ואילך. לקו\"ש ויקרא (כרך יז) ע' 1 ובהערה 5."],["2795","538","<b>שלם במעלה</b>: ט: מעשה."],["2796","539","<b>מאד</b>: הט: ליתא."]]],[2300550631,"בו חסרון מאד ירגיש ויצער<sup data-n=\"2797\">540</sup> לו מאד מצד הגסות כלל<sup data-n=\"2798\">541</sup>. וכמו שאנו מוצאים [ש]מיד אחר חטא אדה\"ר בעה\"ד התחיל להרגיש החסרון בעצמו מה שהוא ערום בלי לבוש וכמ\"ש ויתחבא האדם ואשתו<sup data-n=\"2799\">542</sup> כו' וקודם החטא היו שניהם ערומים ולא יתבוששו<sup data-n=\"2800\">543</sup> כלל וא[מר לו] מי הגיד לך<sup data-n=\"2801\">544</sup> כי עירום אתה המן העץ [אשר צויתיך] כו' כי לא הי' מרגיש שום הרגשת חסרון או מעלה טובה בעצמם שזהו ההרגש בטוב<sup data-n=\"2802\">545</sup> שנעשה אצלם אחר החטא דוקא כידוע.\n(ךא) <sup data-n=\"2803\">546</sup> <b>ובאמת</b> י\"ל וכי בשביל ההרגשה זו בטו\"ר יהי' [נק'] מקור כל רע דז' מדות הרעות הנ\"ל. אך הענין הוא דמבחי' הרגשה זאת באה לבחי' קליפ[ת נוגה] דגס[ות] הרוח שהיא קליפה דעמלק ממש כו', שהרי [אמר] המן מן התו[רה]<sup data-n=\"2804\">547</sup> מניין שנא' המן העץ [אשר] כו', הרי קליפה דהמן [ב]גסות [ו]חוצפא יתירה שלמעלה מז' מדות הרעות דק\"נ שנא' בו ראשית גוים עמלק<sup data-n=\"2805\">548</sup> כו' היינו במה שחטא לאכול מעה\"ד שזהו רק מה שהרגיש בעצמו שהוא ערום שהוא הרגש החסרון בעצמו וכמו\"כ בהרגש המעלה הטובה בעצמו ביותר. וז\"ש [מי הגיד לך כו'] המן העץ [כו'] שעה\"ד זה הוא הנותן כח ההרגש [בטו\"ר שהוא בא בבחי' הגסות שנק' גסות הרוח, כמו שאנו רואים בכל אדם שיש בטבעו גסות והתנשאות הלב ומוח שהוא הוא העושה דבר מה בין במו\"מ שדעתו ולבו גסה לאמר כחו כו', ובלתי זה לא יוכל לעשות דבר וכן בלימוד בחכמה אם לא הגסות וישות שהוא כח ההרגש] במעלות עצמו לא יתחכם כ\"כ כו' וכה\"ג. וע\"כ גם ת\"ח יש בו שמיני' שבשמינית<sup data-n=\"2806\">549</sup> גסות שהוא בחי' גס וס\"ג<sup data-n=\"2807\">550</sup> שבשבה\"כ שבחטא עה\"ד כמ\"ש במ\"א, ואפי' תינוק קטן בלימודו אם לא ינשאו אותו לא ישכיל כ\"כ, וזה נראה בעליל גם דקות השכל והסברא<sup data-n=\"2808\">551</sup> והטבע ביותר שיתפתחו<sup data-n=\"2809\">552</sup> <span data-k=\"pg\">תמא</span> ּ בשכלם ומדות שלהם בגסות כו'. וגם בבחי' יראי<sup data-n=\"2810\">553</sup> ועובדי ה' באמת וגם בצ\"ג מן ההכרח שיש בהן מעט מן בחי' הגסות והישות [מ]פרי טוב מעשיהם ועבודתם כו', ואע\"פ שיכול להיות שמופשטים בתכלית [מכל העכרורית רע דז' מדות ומכל תאוות חומריות וענוה שלהן גדולה ביותר מפני שהכניע לגסות הגוף בתכלית] והם בתכלית בחי' הביטול דמ\"ה שהי' בחי' אין בעצם כידוע, ועכ\"ז [מצד] שרש אחיזתם בעה\"ד טו\"ר מחטא אדה\"ר בהכרח שיש בהם מבחי' ההרגשה גדול בעצם בטו\"ר, כמו ההרגש להכיר חסרונו עד שיצער<sup data-n=\"2811\">554</sup> לו",[["2797","540","<b>ויצער</b>: שם: ויצר."],["2798","541","<b>כלל</b>: שם: כו'."],["2799","542","<b>ויתחבא האדם ואשתו</b>: בראשית ג, ח."],["2800","543","<b>שניהם ערומים ולא יתבוששו</b>: בראשית ב, כה."],["2801","544","<b>מי הגיד לך</b>: בראשית ג, יא."],["2802","545","<b>בטוב</b>: הט: בטו\"ר."],["2803","546","<b>(ךא)</b>: ט: ליתא. ראה הנרשם לעיל הערה 521."],["2804","547","<b>המן מן התו[רה]</b>: חולין קלט, ב."],["2805","548","<b>ראשית גוים עמלק</b>: בלק כד, כ."],["2806","549","<b>ת\"ח. . שמיני' שבשמינית</b>: ראה סוטה ה, א. מאמרי אדה\"א ויקרא ח\"ב ע' תעז. וש\"נ. ש\"א סב, א ובהערה 11. לקמן פ' תצוה שסו, ב."],["2807","550","<b>גס וס\"ג</b>: ראה גם לעיל פ' בשלח קסא, ג ובהערה 600."],["2808","551","<b>דקות השכל והסברא</b>: הט: בכל דקי השכל."],["2809","552","<b>שיתפתחו</b>: ה: שיתפארו. ט: שיתפעלו."],["2810","553","<b>בבחי' יראי</b>: שם: בת\"ח ויראים."],["2811","554","<b>שיצער</b>: ה: שיצר. ט: שמיצר."]]],[2300550637,"מאד מזה, וכ\"ש הרגשת הטוב והמעלה שבולט בעצמו ביותר בישות גדולה, וגם שיוגדל אור הביטול באין ומ\"ה האלקי בנפשו עד שלא ירגיש כ\"כ בעצ[מו] הטוב כו', מ\"מ נשאר החושי'<sup data-n=\"2812\">555</sup> דגסות וישות דנחה\"ק שנעשה ע\"י שטעם מעה\"ד כו' שהוא המקור דז' מדות דרע שמזה יבא ממילא כל רע וטומאה בתאוו' עד שיחטיא לאדם בעבירות חומריו'<sup data-n=\"2813\">556</sup> רק שבצ\"ג לא ישלוט יצה\"ר שהוא הנחה\"ק כי הכניע אותו בתכלית אבל רושם שלו [ש]נעשה בחטא עה\"ד והיינו מ\"ש דבא נחש על חוה<sup data-n=\"2814\">557</sup> והטיל בה זוהמא כו' שמזה נסתעף המות בבנ\"א כידוע וזהו הנשאר גם בצ\"ג שבאים לכלל מות עכ\"פ. וראי' לזה ממ\"ש ד' מתו בעטיו של נחש<sup data-n=\"2815\">558</sup> כו' ורמז בזה שד' צ\"ג אלה [היו] מופשטי' בתכלית מכל ז' מדות דק\"נ ולא היו ראוים למות [כלל] רק מצד עטיו של נחש להאשה [לאכול] מעה\"ד לבד [כו' ש]מ\"מ נשאר בהם איזה שמץ רושם בעלמא מבחי' זוהמא של נחה\"ק שהטיל בחוה כו' שלא הוסר [מ]כל וכל עדיין וע\"כ מתו ולא מצד חומריות גופם כו' [וכמ\"ש ישראל שעמדו בהר סיני פסקה זוהמתן<sup data-n=\"2816\">559</sup> כו'] וד\"ל. אבל בשאר בנ\"א בחי' זוהמא זו דנחה\"ק נמשך במורגש בחומר גופ[ם ש]הוא בחי' הגסות הקשה שבא מן הרגשה החומרי[ת] בטו\"ר בטבע האדם מצד עה\"ד עד שמזה דוקא יבא לכל מיני רע כו'. ואע\"פ שאין עיקר ענין עה\"ד טו\"ר יבא רק מבחי' דקו[ת] ההרגשה כמו ותרא האשה כו'<sup data-n=\"2817\">560</sup> כי טוב העץ למאכל וכי תאוה הוא לעינים כו' ואמנם ע\"י אכילתה נמשך בה זוהמא של נחש שהוא מקור [לכל תאוות הרעות כו', משא\"כ קודם החטא לא הי' באדם וחוה מבחי' ההרגש בעצמם לא בחסרון שבעצמם ולא מטוב ומעלת ש]בעצמם כלל, רק שהי[ו ב]תכלית בחי' הביטול בעצמו'<sup data-n=\"2818\">561</sup> [ל]אלקו' בהשגה וראי' תמידי' ולא היו מרג[י]שי' שהן ערומים כו', ומיד שטעמו מעה\"ד כתיב ויתחבא כו' וא' עוד את קולך שמעתי ואירא<sup data-n=\"2819\">562</sup> כו'. וכדוגמא זאת שקודם החטא הי' בכמה צדיקים כמו במשה שהי' עניו מכל אדם<sup data-n=\"2820\">563</sup> כו' שנא' בו כי טוב הוא בטי\"ת רבתי<sup data-n=\"2821\">564</sup> שהוא מבחי' עה\"ח שלמעלה מעה\"ד, וכן משיח שנא' בו חיים נתת לו חיים נצחי דעה\"ח כו', וכן באלי' וחנוך שעלו למעלה<sup data-n=\"2822\">565</sup>. וכה\"ג גם בת\"ח כמו שיהב[ו רבנן] עינייהו בר[ב עולא בר] אבא<sup data-n=\"2823\">566</sup> דגריס באורייתא תדיר[א] ולא [מ]חזיק טיבותא לנפשו כלל וכלל שהוא האיש שראוי שתשרה שכינה עליו<sup data-n=\"2824\">567</sup> מטעם הנ\"ל, וכן כשר ששמשו בבהמ\"ק<sup data-n=\"2825\">568</sup> הי' שמואל הקטן<sup data-n=\"2826\">569</sup> הי'<sup data-n=\"2827\">570</sup> ראוי להשרות שכינה כו' וכן רבי ור'<sup data-n=\"2828\">571</sup>",[["2812","555","<b>החושי'</b>: שם: הרושם."],["2813","556","<b>חומריו'</b>: שם: חמורות."],["2814","557","<b>דבא נחש על חוה</b>: שבת קמו, רע\"א."],["2815","558","<b>ד' מתו בעטיו של נחש</b>: שבת נה, ב. ב\"ב יז, א."],["2816","559","<b>ישראל. . פסקה זוהמתן</b>: שבת קמו, רע\"א."],["2817","560","<b>ותרא האשה כו' </b>[הט: ליתא]: בראשית ג, ו."],["2818","561","<b>בעצמו'</b>: שם: בעצ[מ]ם."],["2819","562","<b>את קולך שמעתי ואירא</b>: בראשית ג, י [בדילוג]."],["2820","563","<b>במשה שהי' עניו מכל אדם</b>: בהעלותך יב, ג."],["2821","564","<b>במשה. . כי טוב הוא בטי\"ת רבתי</b>: שמות ב, ב ובמנחת שי שם. ראה גם לעיל פ' שמות מג, ד. וש\"נ."],["2822","565","<b>באלי' וחנוך שעלו למעלה</b>: ראה גם לעיל קצו, ג. וש\"נ."],["2823","566","<b>שיהב[ו רבנן] עינייהו בר[ב עולא בר] אבא</b>: ראה סנהדרין פח, ב. מאמרי אדה\"א דברים ח\"א ע' ח. וש\"נ. תו\"ח בראשית טו, ד ובהערה 37. שע\"ת כג, ב."],["2824","567","<b>שהוא האיש שראוי שתשרה שכינה עליו</b>: בסנהדרין שם: איזהו בן עולם הבא."],["2825","568","<b>כשר ששמשו בבהמ\"ק</b>: הט: כאשר שמשו בבת קול."],["2826","569","<b>שמואל הקטן. . להשרות </b>[ה: להשראות. ט: שתשרה עליו]<b> שכינה</b>: סוטה מח, ב."],["2827","570","<b>הי'</b>: שם: ליתא."],["2828","571","<b>ור'</b>: הט: ורב."]]],[2300550643,"יהודה וכה\"ג, ור' בנאי<sup data-n=\"2829\">572</sup> הי' ג\"כ מנשמות דלא שלטא בהו נחה\"ק וכן ר' ישעי'<sup data-n=\"2830\">573</sup> דגששי' והוה כמו משה<sup data-n=\"2831\">574</sup> כו' משום דלא שליט בי' הקנאה דנחה\"ק דהקנאה בא מעוצם ההרגש וגסות וכתי' ורקב בעצמו' קנאה<sup data-n=\"2832\">575</sup> כל שיש בו קנאה<sup data-n=\"2833\">576</sup> עצמותיו מרקיבי' כו' מטעם הנ\"ל (וכמ\"ש הקנאה ו[ה]תאוה<sup data-n=\"2834\">577</sup> והכבוד מוציאי' את האדם<sup data-n=\"2835\">578</sup> דקנאה מחמת גבר<sup data-n=\"2836\">579</sup> כו' [שזה הכל] מחטא עה\"ד וד\"ל.\n<span data-k=\"pg\">884</span> ּ<b>(ךב)</b><sup data-n=\"2837\">580</sup> ובכ\"ז יובן מ\"ש והסירותי מחלה מקרבך בחי' מחלה זו היינו בחי' נקודה דגסה\"ר שהוא קליפה הקשה<sup data-n=\"2838\">581</sup> שמושרש ומוטבע ב[טבע ה]אדם [מ]חטא עה\"ד בבחי' הרגשה הקשה בישות וגסות עצמו שמזה יתפעל<sup data-n=\"2839\">582</sup> בתאוות [רעות] שאינו רק למלאות לבו שנדמה לו שזהו טובתו ע\"כ יתפעל מזה בבחי' ההרגש ביותר כמו ותרא האשה כי טוב העץ כו' (וכן [ב]היפוכו שחסר לו איזה דבר צרכו שירגיש בעצמו ביותר). וכן [י]ש בהרגשה זו ברעת חבירו שישמח בזה או בטובת חבירו שיעצב מזה או לקנא בו ביותר שכ\"ז מחמת חטא עה\"ד כו', ולע\"ל שיבורר עה\"ד טו\"ר [לגמרי ב]ד' חלקי דצח\"מ כו'<sup data-n=\"2840\">583</sup> אז גם בבחי' הרוחני דאדם שבצלם אלקי' יבוער ממנו כל רע הרוחני שהי' בחטא עה\"ד והוא ש[יו]פסק זוהמא של נחה\"ק לגמרי מעיקרו ושרשו, שזהו שלא יהי' שום תערובות ישות וגסות אפי' בדק שבדקות שזהו רוחני' דרע דקליפת עמלק שנא' בו מלחמה לה' בעמלק<sup data-n=\"2841\">584</sup> מדור דור עד ימוהמ\"ש כידוע. וזהו והסירותי מחלה מקרבך [מקרבך] דוקא מאשר כבר נשרש ונדבק בקרבך מחטא עה\"ד והוא הנק' מלחמה<sup data-n=\"2842\">585</sup> לשון מפעיל שהוא שורש ומקור לחל[אים] רעי' דז' מדות הרעות בחולי הנפש עד שימות וכענין הנ\"ל גם בצ\"ג שמזה נסתעף המות וכמ\"ש ד' מתו בעטיו של נחש כו', ובחוטא[ים] ממש מסיבת הרגשת עצמם ביותר למלאות תאוות לבם נא' תמותת רשע רעה<sup data-n=\"2843\">586</sup> כו' כמו שיש רע הממית בחלקי דצ\"ח כו' כך הוא ברוחני' הרע דאדם שימיתנו ולע\"ל שיבורר הרע כתיב ובלע המות לנצח<sup data-n=\"2844\">587</sup> כו' וד\"ל. ודוגמא לזה מצינו בכתוב שכבר הי' לעולמים במי מרה דכתי' ויורהו ה' עץ<sup data-n=\"2845\">588</sup> וישלך אל המים וימתקו המים כו' ויאמר אם שמוע תשמע כו' עד [כל] המחלה אשר שמתי במצרים [לא אשים עליך כי אני ה' רופאיך<sup data-n=\"2846\">589</sup> ] כו' ולכאורה אין הפשט מובן מתחלה א[מר] לא אשים עליך ואח\"כ א' כי אני ה' רופאך שצריך לרפואה עכ\"פ.",[["2829","572","<b>ור' בנאי </b>[שם: בנאה]: ראה גם תו\"ח ח\"ש קכז, ד."],["2830","573","<b>ר' ישעי'</b>: הט: יאשי' — ראה לעיל פ' בשלח ריד, ג ושם: בר' אחאי בר' יאשי' — שבת קנב, ב."],["2831","574","<b>כמו משה</b>: שם: בי' מששא."],["2832","575","<b>ורקב בעצמו' </b>[שם: עצמות]<b> קנאה</b>: משלי יד, ל."],["2833","576","<b>כל שיש בו קנאה</b>: ראה שבת שם."],["2834","577","<b>הקנאה ו[ה]תאוה</b>: אבות פ\"ד, מכ\"א."],["2835","578","<b>והכבוד. . האדם</b>: הט: כו'."],["2836","579","<b>דקנאה מחמת </b>[הט: חמת]<b> גבר</b>: משלי ו, לד."],["2837","580","<b>(ךב)</b>: ט: כד."],["2838","581","<b>הקשה</b>: ה: הגסה."],["2839","582","<b>יתפעל</b>: הט: יפול."],["2840","583","<b>דצח\"מ כו'</b>: ה: גשמיות דצח\"מ כנ\"ל. ט: דצח\"מ גשמיי'."],["2841","584","<b>מלחמה לה' בעמלק</b>: בשלח יז, טז. ראה תרגום יוב\"ע שם."],["2842","585","<b>מלחמה</b>: הט: מחלה."],["2843","586","<b>תמותת רשע רעה</b>: תהלים לד, כב. ראה גם מאמרי אדה\"א נ\"ך ע' תצח. וש\"נ."],["2844","587","<b>ובלע </b>[ט: בלע]<b> המות לנצח</b>: נסמן לעיל פ' יתרו ערב, א."],["2845","588","<b>ויורהו ה' עץ</b>: בשלח טו, כה. ראה גם לעיל פ' בשלח רטו, ב. וש\"נ."],["2846","589","<b>ויאמר אם שמוע. . רופאיך</b>: בשלח שם, כו."]]],[2300550649,"(ךג) <sup data-n=\"2847\">590</sup> <b>אך</b> הענין הוא כנ\"ל במי<sup data-n=\"2848\">591</sup> מרה [הללו] הי' מבחי' מים מר[ור]ים דק\"נ שהן גבורות קשות דכל חולי רעה נמצא מהם וז\"ש כי מרים הם והוא מחמת חטא עה\"ד שנפל תערובות דרע גמור בד' נהרות עד שיצאו<sup data-n=\"2849\">592</sup> מים מרים שיגיעו ויבואו לשערי מות ברוחני' ובגשמי' כו'. ואמנם ציוה ה' למשה להשליך העץ מבחי' עה\"ח שיכול לתקן ולהמתיק הרע והמות שבמרירות המים וימתקו ממש שזהו ענין התו[רה] ששרשה בעה\"ח כמ\"ש כי עץ חיים היא<sup data-n=\"2850\">593</sup> כו' שמתקן לגבי גבורות<sup data-n=\"2851\">594</sup> קשות להמתיק ולהפוך מרירות למתיקו כו', שזה[ו] ממש כמו [הרפואה] שמרפא לחולי רעה שממתיק הדין הקשה ממות לחיים וז\"ש וישלך אל המים וימתקו כו'<sup data-n=\"2852\">595</sup> שנהפך הרע והמות לחיים וטוב ע\"י עה\"ח דתו'. וז\"ש שם לו חוק ומשפט<sup data-n=\"2853\">596</sup> שזהו הבירורי' שע\"י התו' דעה\"ד לבער הרע שנק' חוק ומשפט ושם נסהו שבא בנסיון. וזהו ויאמר אם שמוע תשמע כו' כל המחלה כו' לא אשים שלא יתפשט לבא כמו במדות רעות דק\"נ אשר שמתי במצרים, ומפרש הטעם כי אני ה' <span data-k=\"pg\">תמב</span> ּ רופאך ע\"י עה\"ח דתו' שמהפך מרירו למיתקו כמו רפאות תהי לשרך<sup data-n=\"2854\">597</sup> כו' שהתורה מביאה רפואה לנפש לרפא חלאי' רעים שבנה\"א כמשרז\"ל חש בראשו יעסוק בתורה<sup data-n=\"2855\">598</sup> וכה\"ג בציור כל קומת אדם שבצלם אלקי' שנפגם ויתקן אור דתו' מטעם הנ\"ל, וז\"ש כי אני ה' [דתו\"מ] רופאך. אך המחלה עצמה כמו שהיא במקורה ושרשה בק\"נ מחטא עה\"ד לא אשים עליך כלל ומה שיתפשט הרע משרשו בז' מדות דק\"נ ירופא ע\"י התו' שמברר לעה\"ד להבדיל כו' וד\"ל.\n(ךד) <sup data-n=\"2856\">599</sup> <b>אך</b> הנה עדיין לא יתורץ מ\"ש תחלה לא אשים עליך כו' ואח\"כ אני ה' רופאך משמע שמרפא למחלה שא' תחלה, ואם קאי על החול[י] שמתפשט מן הרע לבד הרי אין זה קשור וחיבור בסדר הדברים שא' כל המחלה כו' לא אשים כלל כי אני כו' שזהו [כ]נתינת טעם ולפיכך אני רופאך. אך הענין יובן בהקדים תחלה מ\"ש כאן ועבדתם כו' ובירך ה'<sup data-n=\"2857\">600</sup> לחמך ומימך והסירותי מחלה מקרבך, [ד]הנה מבואר לעיל בפי' לחמך ומימך שהוא בחי' לחם ומים דתו\"מ<sup data-n=\"2858\">601</sup> שנמשך בארץ מאור הזרוע דתו\"מ הע[ליונים] בארץ עילאה ונק' ארץ דמפקי מזון רוחני לנשמות בבחי' החיות הטוב האלקי'<sup data-n=\"2859\">602</sup> בנפשו<sup data-n=\"2860\">603</sup> שלא יהי' [בזה] שום תערובות והסתעפות לחיצוני' כלל (כמו שהתו' היא למעלה בבחי' עה\"ח שלמעלה מעה\"ד כו' וכלחם המן וכלחם הפנים",[["2847","590","<b>(ךג)</b>: ט: ליתא. ראה לעיל הערה 580."],["2848","591","<b>כנ\"ל במי</b>: הט: דמי."],["2849","592","<b>שיצאו</b>: שם: שיש."],["2850","593","<b>כי עץ חיים היא</b>: משלי ג, יח [בהוספת תיבת ”כי\" — ראה מאמרי אדה\"א שמות ח\"א ע' צט. וש\"נ. דברים ח\"א ע' כא וע' עה. תו\"ח מקץ רכז, ד]."],["2851","594","<b>לגבי גבורות</b>: הט: לגבורות."],["2852","595","<b>כו'</b>: ה: המים. ט: המים ממש."],["2853","596","<b>שם לו חוק ומשפט</b>: בשלח טו, כה."],["2854","597","<b>רפאות תהי לשרך</b>: משלי ג, ח."],["2855","598","<b>חש בראשו יעסוק בתורה</b>: ערובין נד, א."],["2856","599","<b>(ךד)</b>: ט: כה. ראה לעיל הערה 580."],["2857","600","<b>ה'</b>: הט: את."],["2858","601","<b>דתו\"מ</b>: ט: דתורה."],["2859","602","<b>החיות הטוב האלקי'</b>: ט: חיות הטובים האלו."],["2860","603","<b>בנפשו</b>: הט: באופן."]]],[2300550655,"שכולו פנים<sup data-n=\"2861\">604</sup> כו'), ו[הוא] כמו [ב]ימוהמ\"ש שאין הסתעפות לרע מזה כלל, וברכה זאת מאת ה' שיברך לחמך ומימך דאורייתא גם בארץ תתאה וזהו אחר הבירור דעה\"ד כאשר יושלם העבודה דתו\"מ בסו\"מ וע\"ט [כמ\"ש] ועבדתם את ה' ואז ממילא והסירותי מחלה מקרבך שהוא שרש הרע שנמשך בחטא עה\"ד שנק' מחלה כנ\"ל שיסור המחלה ממילא מכל [וכל] מעיקרא ושרשא כל<sup data-n=\"2862\">605</sup> להיות רק [ב]בחי' הביטול לאלקו' בתכלית בלי הרגש עצמו בשום אופן בחי' גסות וישות כלל וכלל כמו שהי' באדה\"ר קודם החטא כנ\"ל. והיינו מ\"ש ג\"כ ענין במי מרה [שם] שם לו חוק כו' ושם הי' מצד שהשליך עליו<sup data-n=\"2863\">606</sup> מעה\"ח להמתיק המים שזהו כמו הרפואה לחולי ממש להמתיק הרע, ואח\"כ א' אם שמוע תשמע בקול ה'<sup data-n=\"2864\">607</sup> כו' [ש]זהו כמ\"ש כאן ועבדתם את כו' כל המחלה דנחה\"ק אשר שמתי במצרים בי' מכות (שהן הדינים הקשות דגבו' קשות דע\"ס דק\"נ כידוע) לא אשים עליך כי אני ה'<sup data-n=\"2865\">608</sup> כו' בלי יצטרך המתקה מעה\"ח בעה\"ד אלא אני ה' בעצמי רופאך שזהו כמ\"ש כאן ובירך את לחמך ומימך כו', דהיינו מצד שרש התו\"מ כמו שהן למעלה שיתברכו גם למטה בארץ להיות מזון טוב לנשמות עד שיוסר מהם כל המחלה ממילא כמו אדם הטוב<sup data-n=\"2866\">609</sup> בבריאות בתכלית שלא יבא לכלל סיבת חולי, כי מושלל מהם שלא יוכל לשלוט בגופו כלל כמ\"ש למעלה בענין ברורי' הרכבו'<sup data-n=\"2867\">610</sup> טובה שבארץ ומים גשמי' שמזה יבא שלימות הבירור<sup data-n=\"2868\">611</sup> באדם שמושלל מכל חולי רעה בגשמיות כו' (אך [בכאן] א[מר] ובירך ה' את לחמך ומימך והסירותי כו' ושם א[מר] לא אשים כלל כי אני ה' רופאך <span data-k=\"pg\">886</span> ּ כמ\"ש רפאני ה' וארפא<sup data-n=\"2869\">612</sup> כו').\n(ךה) <sup data-n=\"2870\">613</sup> <b>ומעתה</b> יובן סדר הסמיכות דפ[סוק] לא תהי' משכלה ועקרה למה שקדם לו ועבדתם כו', דהנה מבואר לעיל בשרש בחי' המחלה הנ\"ל שבא מזוהמא של נחה\"ק שהטיל בחוה אחר החטא דעה\"ד דוקא, וע\"כ אחר שא' ובירך את לחמך ומימך דתו\"מ עד שיסור מזה<sup data-n=\"2871\">614</sup> כל בחי' המחלה הנ\"ל מקרבך [מעיקרו] ושרשו כנ\"ל אז לא תהי' משכלה ועקרה בארצך, כמו שבגשמיות ש[ה]ארץ שתטהר מעכרורית אוירים וכן הימים<sup data-n=\"2872\">615</sup> יהי' תולדות האדם בקיום יותר [כנ\"ל]. וכך הוא בבחי' חיות<sup data-n=\"2873\">616</sup> הרוחני' [כ]שלא יהי' בחי' הגסות ולגרמי' הזה<sup data-n=\"2874\">617</sup> קליפה דנחה\"ק שנק' מחלה אז ממילא יהי' קיום לתולדות אוי\"ר שנק' בנים [מ]בחי' בינה אם המיילדת בקיום נצחי שלא יבוטלו לעולם ולא תהי' יולדת וקוברת, משא\"כ כשהי'<sup data-n=\"2875\">618</sup> עדיין בקרבך אין קיום לתולדות המדות שיולדת וקוברת, מצד המחלה שממית גם לולד הנולד שיפול בתאוות [ו]אהבות רעות לגרמי'<sup data-n=\"2876\">619</sup> כו'. וכמו",[["2861","604","<b>וכלחם הפנים שכולו פנים</b>: ראה מנחות צו, א. הנסמן לעיל פ' בא קכז, א."],["2862","605","<b>כל</b>: הט: ליתא."],["2863","606","<b>עליו</b>: שם: עץ."],["2864","607","<b>בקול ה'</b>: שם: ליתא."],["2865","608","<b>ה'</b>: ה: ניתוסף: רופאך. ט: ליתא."],["2866","609","<b>הטוב</b>: שם: השלם."],["2867","610","<b>ברורי' הרכבו'</b>: שם: בירור הרכבה."],["2868","611","<b>הבירור</b>: שם: הבריאות."],["2869","612","<b>רפאני ה' וארפא</b>: ירמי' יז, יד. הט: רפאנו ה' ונרפא — תפלת שמו\"ע."],["2870","613","<b>(ךה)</b>: ט: כו."],["2871","614","<b>שיסור מזה</b>: שם: שיוסר."],["2872","615","<b>הימים</b>: שם: המים."],["2873","616","<b>חיות</b>: שם: ליתא."],["2874","617","<b>הזה</b>: שם: דזהו."],["2875","618","<b>כשהי'</b>: ה: חסר. ט: כשהמחלה."],["2876","619","<b>לגרמי'</b>: ה: ליתא. ט: לגמרי."]]],[2300550661,"שבארץ הגשמי' דמפק[א] מזון גשמי [כ]שאינו מנוקה מכל סיג שנק' ארץ אוכלת יושביה, וכן הימים שמגדלים ומצמיחים אם אין [ה]מים נקי[ים] מכל רע וממשיכי'<sup data-n=\"2877\">620</sup> חלאים רעים. ולכך מיד שא' ובירך ה' את לחמך ומימך סמך לזה לא תהי' משכלה ועקרה בארציך [בארציך] דוקא שהוא אה\"ח העליונה דמפקת מזון דלחם התו'<sup data-n=\"2878\">621</sup>, ולפ\"ע הטוב ברכת הטוב<sup data-n=\"2879\">622</sup> לנשמות כך יהי' ערך הטוב בברכת הטוב<sup data-n=\"2880\">623</sup> דפרי הבטן דכנ\"י שלא תהי' משכלה כו' וגם לא תהי' עקרה שאינה מולדת, כי אין מקום לשליטת החיצוני' כלל שימנע התולדה מצד התערובות טו\"ר שבעה\"ד מאחר שכבר הסיר המחלה כנ\"ל וד\"ל.\n(ךו) <sup data-n=\"2881\">624</sup> <b>ומעתה</b> יובן ג\"כ מה שאחר מזוני ובני הזכיר חיי שז\"ש את מספר ימיך אמלא שהוא אריכות [ימים] ביותר [ו]הוא מטעם הנ\"ל מאחר שהסיר המחלה דנחה\"ק שרש הקליפה<sup data-n=\"2882\">625</sup> דעה\"ד ותטהר הארץ מתערובות רע לגמרי לכן ודאי יהי' מזה אריכות ימים ביותר מן מדת הימים שנתנו במספר כנ\"ל. אך עדיין י\"ל והלא ענין המילוי הזה דימים הוא בבחי' יומין עילאין [דימי קדם שהן ימים דתורה הקדומה שנק' אדם הגדול כנ\"ל בבחי' ימי הזקנה, ועוד למעלה מזה והוא בבחי' עולם דעוה\"ב הנצחי ואיך יבא זה ממה שהסיר המחלה ובירך לחמך כו', שאין זה מועיל רק לענין היפוכו שלא תהי' משכלה כו' ואיך מיד שלא תהי' משכלה שזה רק להסיר המות שבא מן המחלה הנ\"ל אמר את מספר ימיך אמלא בחיים ארוכים דחיי עוה\"ב דימות המשיח כו']. אך הענין הוא דכמו שא' תחלה<sup data-n=\"2883\">626</sup> והסירותי מחלה מקרבך קאי רק<sup data-n=\"2884\">627</sup> על זוהמא דנחה\"ק שהטיל בחוה שזהו מחלה לשון נקבה וא' בזהר דנחה\"ק הטיל [בה בחוה ולא בבעלה<sup data-n=\"2885\">628</sup> כו' דמה שבא נחש על חוה כו' לא הזיק ופגם לאדם עצמו כלל ולא נמשך זוהמא דנחה\"ק רק] בחוה לבד ע\"כ חיוי[א] קטיר לרגלוהי כו' דנוק'<sup data-n=\"2886\">629</sup> דוקא ונתקלקלה<sup data-n=\"2887\">630</sup> [בעצב תלדי בנים<sup data-n=\"2888\">631</sup> והוא מ\"ש לא תהי' משכלה כו' וחטא האדם לא הי' מצד הנחש רק מה ששמע לקול חוה לאכול] מעה\"ד כו' כמ\"ש ולאדם אמר<sup data-n=\"2889\">632</sup> כי שמעת לקול אשתך<sup data-n=\"2890\">633</sup> כו' וא\"כ בחי' קליפה דנחה\"ק לא שלט באדם עצמו ממש רק מצד חוה עצמה שהטיל בה זוהמא כו'. ולזאת אחר הבירור דעה\"ד טו\"ר [ע\"י התו\"מ] שנק' אדם הגדול כו' יכול להיות ש[יהי'] מעל[ת] האדם בעילוי הימים דבחי' ימי קדם שהן ימי הזקנה וכמ\"ש זקן בא בימים ביומין עילאין כמו יומין דתו\"מ כו'. ו[עוד] למעלה מז[ה] בבחי' ח\"ע<sup data-n=\"2891\">634</sup> דעוה\"ב שנק' אדם בדומה לעליון<sup data-n=\"2892\">635</sup> ממש, וז\"ש את מספר ימיך אמלא בשלימות העליון ממש<sup data-n=\"2893\">636</sup> כנ\"ל [רק לאחר",[["2877","620","<b>וממשיכי'</b>: שם: ימשיכו."],["2878","621","<b>התו'</b>: ט: התו\"מ."],["2879","622","<b>הטוב</b>: הט: המזון."],["2880","623","<b>בברכת הטוב</b>: ה: בברכת דתולדה. ט: דתולדה."],["2881","624","<b>(ךו)</b>: ט: כז."],["2882","625","<b>הקליפה</b>: הט: הקלקול."],["2883","626","<b>דכמו שא' תחלה</b>: ה: דכל מ\"ש תחלה. ט: דמ\"ש."],["2884","627","<b>רק</b>: שם: ליתא."],["2885","628","<b>דנחה\"ק הטיל [בה בחוה ולא בבעלה</b>: ראה זהר ח\"ש קכו, א."],["2886","629","<b>חיוי[א] קטיר לרגלוהי דנוק'</b>: ראה ת\"ז תכ\"ו (עב, א)."],["2887","630","<b>ונתקלקלה</b>: הט: ונתקללה."],["2888","631","<b>בעצב תלדי בנים</b>: בראשית ג, טז."],["2889","632","<b>ולאדם אמר</b>: בראשית ג, יז."],["2890","633","<b>כי שמעת לקול אשתך</b>: הט: ליתא."],["2891","634","<b>ח\"ע</b>: שם: חיי עולם."],["2892","635","<b>אדם בדומה לעליון</b>: נסמן לעיל פ' יתרו רסב, א הערה 284."],["2893","636","<b>ממש</b>: הט: ליתא."]]],[2300550667,"שהסיר בחי' המחלה דהיינו זוהמא דנחה\"ק מבחי' הנוק' שכלולה בדכורא שלא תהי' משכלה כו'] ואז ממילא מצד עצמו' האדם את מספר ימיך אמלא לימוהמ\"ש ולחיי עוה\"ב וד\"ל. ובזה יובן מ\"ש כל המחלה כו' לא אשים עליך [כי] אני ה' דוקא<sup data-n=\"2894\">637</sup> דקאי בבחי' [ה]דכורא וז\"ש<sup data-n=\"2895\">638</sup> והסירותי מחלה מקרבך כו'<sup data-n=\"2896\">639</sup> בבחי' הנוק' ומטעם הנ\"ל שא' בזהר וד\"ל.",[["2894","637","<b>דוקא</b>: שם: רופאיך."],["2895","638","<b>וז\"ש</b>: שם: ומ\"ש."],["2896","639","<b>כו'</b>: שם: קאי."]]],[2300550054,"<b>תורה מאדמו\"ר הרב ר' דובער נבג\"מ שבת פ' תרומה</b>\n<span data-k=\"pg\">תמג</span> ּ<b>ועשו</b> לי מקדש<sup data-n=\"2897\">1</sup> ושכנתי בתוכם<sup data-n=\"2898\">2</sup>, וי\"ל דהל\"ל ושכנתי בתוכו [בתוך המקדש] דהא [במקדש קאי ו]מהו בתוכם בתוך כנס\"י, ומהו ענין הקמת<sup data-n=\"2899\">3</sup> המקדש להשראת השכינה בכנ\"י. אך הנה י\"ל תחלה בכל ענין פרטי מעשה המשכן בעשר יריעות וארון ומנורה ושולחן ומזבח הזהב ומזבח החיצון כו', והנה [ידוע] דכל ציור המשכן הוא לנגד ע\"ס<sup data-n=\"2900\">4</sup> עליונות דאצי' באו\"כ ומקיפים. ויובן זה בהקדים תחלה בכללות ענין המשכן שהיו בו ב' דברים כוללים, הא' היריעות שהם בחי' המקיפים העליונים, והב' הכלים [ה]ארון ומנורה ושולחן וכה\"ג שהם בחי' הכלים. ולהבין זה יש להבין<sup data-n=\"2901\">5</sup> ענין הפסוק וידעת היום<sup data-n=\"2902\">6</sup> והשבות אל לבבך [כו'] דידוע שכלל הענין ב' דברים הם, הא' הידיעה בתחלה בכלי המוח ביחוד אלקי' וז\"ש וידעת היום. [ו]הב' ענין ההשבה אל הלב דהיינו אות[ה] הידיעה וההשגה שבמוחו יש[י]ב אל הלב, וז\"ש והשבות אל לבבך שב' מצות הן ומשמע דאם קיים רצון<sup data-n=\"2903\">7</sup> הידיעה במוח ולא השיב אל הלב אין זה כלום דהעיקר הוא [ה]השבה אל הלב, שמזה שהשיב אל הלב יולד אהוי\"ר בלב והוא מצות ואהבת שבק\"ש כו'. ואע\"פ שקיים מצות יחוד אלקי' בהשגה שבמוח אין זה מצוה כלל שיהי' שורה בזה יחוד עליון דהוי' ואלקים ממש כ\"א בבוא אור ההשגה אלקי' בכלי הלב דוקא, לפי שזהו עיקר בחי' אדם כמ\"ש<sup data-n=\"2904\">8</sup>, וזהו ושכנתי בתוכם בתוך לב של כאו\"א מישראל. ומ\"ש בתוכם לשון רבים משמע גם בכל אחד ואחד, והיינו מפני שיש ב' לבבות לב הפנימי ולב החיצון, ואמר בתוכם בתוך ב' [ה]לבבות שמתייחסים כא'<sup data-n=\"2905\">9</sup>, והוא מה שאנו אומרים ויחד לבבינו<sup data-n=\"2906\">10</sup> כו' כמ\"ש.",[["2897","1","<b>ועשו לי מקדש</b>: מיוסד על מאמר ד\"ה ראו קרא ה' בשם בצלאל בן אורי שנדפס במאמרי אדה\"ז תקס\"ד ע' סה. וראה בהנסמן במ\"מ לשם. ראה גם מאמרי אדה\"א שמות ח\"ב ע' תרעא ואילך. ראה עוד ע\"ד המאמר לקמן ברשימת הכת\"י [ושם ג\"כ מפורט סימני האותיות הבאות לקמן בהמראי מקומות]."],["2898","2","<b>ועשו לי מקדש ושכנתי בתוכם</b>: תרומה כה, ח. ראה גם לקמן פ' ויקהל תלא, ג ובהערה 1591."],["2899","3","<b>הקמת</b>: אד: ליתא."],["2900","4","<b>ציור המשכן. . ע\"ס</b>: ראה גם מאמרי אדה\"א שמות ח\"ב ע' תט. ע' תרסא. לקמן פ' ויקהל שפו, ד. תכו, סע\"ד ואילך (ובהנסמן שם)."],["2901","5","<b>להבין</b>: אד: להקדים."],["2902","6","<b>וידעת היום</b>: ואתחנן ד, לט."],["2903","7","<b>רצון</b>: אד: מצות."],["2904","8","<b>כמ\"ש</b>: שם: כמשי\"ת."],["2905","9","<b>שמתייחסים כא'</b>: א: שמתייחדים כא'. ד: ליתא."],["2906","10","<b>ויחד לבבינו</b>: ברכת ק\"ש. ראה גם לקמן שט, ב ואילך. פ' תצוה שנג, ב. מאמרי אדה\"א קונטרסים ע' שט. וש\"נ. הנחות תקע\"ז ע' קצ. וש\"נ."]]],[2300550086,"<b>ויש</b> להבין תחלה בענין מצות הידיעה ביחוד אלקי' שהוא כמ\"ש כי הוי' הוא האלקי' דכולא חד<sup data-n=\"2907\">11</sup> [מהיחוד עליון] יש בזה שמתייחדי' ב' שמות דהוי' ואלקי' דוקא. והנה ידוע בענין כי שמש ומגן<sup data-n=\"2908\">12</sup> הוי' אלקים, כמו המגן של השמש שהוא הנרתק להסתיר ולהעלים אור [ה]שמש, כך שם אלקי' הוא המצמצם ומסתיר על שם הוי', וא\"כ י\"ל איך אמר דהוי' הוא [ה]אלקי' ממש מאחר שב' הפכים הם דשם הוי' בבחי' חסד<sup data-n=\"2909\">13</sup> ואור<sup data-n=\"2910\">14</sup> ושם אלקי' המצמצם ומסתיר האור כו'. אך הענין [הוא] כידוע שבאמת הוא [דבר] פלא מהיכן יהי' התהוות בע\"ג מבלתי בע\"ג [ש]הם ב' [דברים] הפכים, ואיך יפעול כח הבלתי בע\"ג פעולה מוגבלת, הלא כל פועל [י]פעול בדומה לו, ואם כחו בלתי גבול הרי גם הפעולה ידמה לו שתהי' בלתי מוגבלת ולמה אנו רואים שכח הפועל [ה]אלקי שב[ר]א שמים וארץ הוא בלתי בע\"ג ותכלית ושמים וארץ וכל צבאם הוא בעלי גבול ותכלית כו', והוו[י'] ונפסדי' כו'. אלא צ\"ל שלא ממהות ועצמות כח [ה]אלקי י[מ]צא הפעולה והבריאה כ\"א<sup data-n=\"2911\">15</sup> ע\"י אמצעי ביניהם, והוא ענין הנרתק ומגן שבא לצמצם עצם אור דשם הוי' כו', והוא הנק' מסך ופרגוד המפסיק בין אצי' לבריאה<sup data-n=\"2912\">16</sup>, כמו מגן ונרתק השמש שאינו מכסה לגמרי אור השמש אלא כדי שיוכל[ו] לקבל אור השמש הבהיר ביותר מתלבש בלבוש זה שנק' מגן ונרתק שע\"י יבוא האור בשינוי המהות קצת, ואז יאיר אור שיוכלו לקבל, ונמצא עיקר ההארה בעולם הוא מן האור היוצא מן הנרתק ומגן השמש דוקא וד\"ל. וזהו הנק' הארה דהארה או אור של תולדה [ו]כמ\"ש במ\"א, וז\"ש באורך נראה <span data-k=\"pg\">888</span> ּ אור<sup data-n=\"2913\">17</sup> [כו'], וזהו ענין שם אלקים המצמצם לאור של שם הוי' ואמנם צמצום [ה]זה הוא בשביל המקבלים דהיינו שיוכל להיות התהוות הבריאה יש מאין בבחי' גבול, ואם לא בבחי' הצמצום דשם אלקים הי' כל",[["2907","11","<b>כי הוי' הוא האלקי' דכולא חד</b>: ואתחנן ד, לה. לט. ראה גם לעיל פ' וארא ס, א. וש\"נ."],["2908","12","<b>כי שמש ומגן</b>: תהלים פד, יב. ראה שער היחוה\"א רפ\"ו. לעיל פ' שמות לד, ד. וש\"נ."],["2909","13","<b>דשם הוי' בבחי' חסד</b>: ראה גם לעיל פ' בא פז, א. וש\"נ."],["2910","14","<b>חסד ואור</b>: א: אור."],["2911","15","<b>כ\"א</b>: אד: רק."],["2912","16","<b>מסך ופרגוד. . אצי' לבריאה</b>: ראה ע\"ח (שער דרושי אבי\"ע) שמ\"ב, פ\"ד. מאמרי אדה\"א דברים ח\"ג ע' תתפא. וש\"נ."],["2913","17","<b>הארה דהארה. . באורך נראה אור</b>: תהלים לו, י. ראה גם לעיל פ' וארא ס, ב ובהערה 24."]]],[2300550118,"התפשטו' [ו]שפע אלקי' מש' הוי' [ה]כל בלתי בע\"ג, ונמצא מובן שמבחי' המגן ונרתק שהוא שם אלקי' דוקא ממנו וע\"י דוקא נמשך כל התהוות הברואים<sup data-n=\"2914\">18</sup> מאין ליש וד\"ל.\n<b>ובזה</b> יובן במע\"ב מה שנזכר שם אלקי'<sup data-n=\"2915\">19</sup> דוקא כי מ\"ש<sup data-n=\"2916\">20</sup> בראשית ברא אלקי'<sup data-n=\"2917\">21</sup>, ויאמר אלקים יהי אור<sup data-n=\"2918\">22</sup> וכל [ה]מאמר[ות] הכל בשם אלקים דוקא, ואלקים הוא לשון כח<sup data-n=\"2919\">23</sup> ומקור ומשפיע, והוא תיבת אל שבאלקים וגם כלול ממדו\"מ<sup data-n=\"2920\">24</sup> הצמצום וכמארז\"ל בתחלה עלה במח' לברוא במדה\"ד<sup data-n=\"2921\">25</sup> כו' וד\"ל. וזהו שאמר קודם שנברא העולם<sup data-n=\"2922\">26</sup> הי' הוא ושמו בלבד, פי' הוא ושמו היינו שם הוי' ב\"ה שזהו עיקר שמו העצמי ולא ע\"ש הפעולה שמהווה את הכל, כי יו\"ד דשם הוי' מורה לעתיד ולהבא<sup data-n=\"2923\">27</sup> שמהווה את הכל והוא ע\"י שם אלקים דוקא מטעם הנ\"ל, ע\"כ קודם הבריאה הי' שם הוי' [זה] כלול בעצמותו ממש. וכמו שהוא בעצמו לבד[ו] ביחוד האמיתי בעצמות הא\"ס, כך שמו דשם הוי' מיוחד בו ממש, וז\"ש הי' הוא ושמו בלבד ואין עוד דבר להתייחד זולת שמו העצמי. משא\"כ אחר הצמצום דשם אלקי' שנמשך מזה התהוות הברואי' הוצרך לומר וידעת כו' בשמים ממעל כו' אין עוד, אבל קודם הצמצום לא הי' עוד זולת הוא ושמו בלבד [כו' וד\"ל]. וכמו\"כ גם לאחר הצמצום דשם אלקי' אמר כי הוי' הוא האלקי' דכולא חד ממש לפי שגם שם אלקי' המצמצם הרי הוא מכחו של א\"ס בעצמו שהוא ית' כ\"ל יכו\"ל, ויש בו גם כח המגביל והוא שם אלקים זה, ומאחר שהוא בעצמו ית' עשה בחי' המגן ונרתק זה דשם אלקי' כדי שיהי' בריאה בע\"ג כו' א\"כ אין זה הגבלה וצמצום כלל לגבי עצמותו רק למקבלים לבד כדי שיהי' במציאות יש וגבול כו'. ואדרבה שם אלקים זה מתייחד בעצמות א\"ס ב\"ה כמו שם הוי' קודם הבריאה שהי' הוא ושמו בלבד ממש גם עתה אחר הצמצום דשם אלקים הרי אין עוד זולתו ית' הגם שכבר נברא העולם וכמ\"ש בשמים ממעל ועל הארץ מתחת אין עוד<sup data-n=\"2924\">28</sup>. והיינו מפני היחוד דשם הוי' ואלקי' בתכלית היחוד מאחר שמכח א[חד] דאח\"פ שניהם מכח א'<sup data-n=\"2925\">29</sup> יצאו ביחוד גמור ואינ[ן] ב' הפכים כלל לגבי עצמותו ית' וכמ\"ש אני הוי' לא שניתי<sup data-n=\"2926\">30</sup> בין קודם הבריאה שהי' הוא ושמו בלבד, כך אחר הבריאה הוא ושמו כו' שאין שם אלקי' מצמצם כלל וד\"ל, וכמו שאנו אומרים אתה הוא קודם שנברא כו', אתה בגילוי והוא נסתר היינו הוא ושמו הנ\"ל שאין בזה שום שינוי כלל מקודם הבריאה לאח\"כ מטעם הנ\"ל וד\"ל. וזהו עיקר מצות",[["2914","18","<b>הברואים</b>: א: הבריאה."],["2915","19","<b>במע\"ב. . שם אלקי'</b>: ראה גם לעיל פ' יתרו רסו, ב. הנסמן לעיל פ' שמות ל, ב הערה 128."],["2916","20","<b>כי מ\"ש</b>: אד: כמ\"."],["2917","21","<b>בראשית ברא אלקי'</b>: בראשית א, א."],["2918","22","<b>ויאמר אלקים יהי אור</b>: שם א, ג."],["2919","23","<b>ואלקים הוא לשון כח</b>: ראה שו\"ע אדה\"ז דין כוונת הברכות ס\"ה, ס\"ג. לקמן פ' תצוה שכז, ד. לעיל פ' וארא עה, ב. וש\"נ."],["2920","24","<b>ממדו\"מ</b>: אד: ממדת."],["2921","25","<b>בתחלה עלה במח' לברוא במדה\"ד</b>: ראה רש\"י בראשית א, א. הנסמן במאמרי אדה\"א דברים ח\"ד ע' א'תכ."],["2922","26","<b>קודם שנברא העולם</b>: ראה פדר\"א פ\"ג. לעיל פ' וארא נג, ב. וש\"נ."],["2923","27","<b>יו\"ד. . מורה לעתיד ולהבא</b>: ראה שער היחוה\"א פ\"ד. לעיל פ' בשלח קנ, א. וש\"נ."],["2924","28","<b>בשמים ממעל. . אין עוד</b>: ואתחנן ד, לט."],["2925","29","<b>מכח א'</b>: אד: כא'."],["2926","30","<b>אני הוי' לא שניתי</b>: מלאכי ג, ו."]]],[2300550150,"היחוד באלקות כמ\"ש וידעת היום כו' כי הוי' הוא [ה]אלקים כו' דב' שמות דהוי' אלקים הן מיוחדים בתכלית, וזהו דוקא באדם שהוא בצלם אדה\"ע שכלול מב' שמות הללו דהוי' ואלקים, ע\"כ נצטווה בידיעה זו והשבה אל הלב שהוי' הוא [ה]אלקים ולא שום בריאה זולתו אפי' מלאכים <span data-k=\"pg\">תמד</span> ּ עליונים, וראי' לזה הוא [מ]מה שאנו רואים שבכל הברואים זולת האדם לא נז' בו רק שם אלקי' לבד כמו ויאמר [אלקים] יהי אור כו', שכל הנבראי' לא נבראו רק בשם אלקי' מטעם הנ\"ל.\n[ב] <b>אך</b> כ\"ז הי' קודם שנברא האדם, אבל ביצירת האדם נא' וייצר הוי' אלקי'<sup data-n=\"2927\">31</sup> את האדם (אע\"פ שבבריאה נאמר גם באדם ויברא אלקים<sup data-n=\"2928\">32</sup> ). וגם מ\"ש קודם אלה תולדות השמים<sup data-n=\"2929\">33</sup> [כו'] ביום עשות הוי' אלקי' ארץ ושמים, היינו מפני [ה]טעם שמפרש ואומר אח\"כ וכל שיח השדה כו', כי לא המטיר<sup data-n=\"2930\">34</sup> הוי' אלקי' כו' לפי שאדם אין לעבוד כו' עד שיצר את האדם בב' שמות הללו דהוי' אלקים דוקא כדי שע\"י יהי' היחוד העליון דהוי' אלקים דוקא. והטעם הוא לפי שכל ברכה ושפע א\"א להיות כ\"א ע\"י יחודים העליונים דהיינו הוי' [ו]אלקי' [דוקא] וז\"ש כי לא המטיר הוי' אלקי' כו', ומה שלא המטיר הוא מפני שאדם אין לעבוד בהעלאת מ\"ן. והענין הוא כי עיקר בחי' אדם הוא בחי' המדות<sup data-n=\"2931\">35</sup> שבלב דוקא, ואע\"פ שלכאורה עיקר בחי' אדם שהוא בר דעת חכים<sup data-n=\"2932\">36</sup> בכלי המוחין דוקא, מ\"מ עיקר מהות שם אדם הן המדות (וראי' לזה ממה שבבריאה שהוא בחי' מח' נא' ויברא אלקי' את האדם, וביצי' שהן במדות נא' וייצר הוי' אלקים) כי המדות שבלב הן הן עיקר האדם. ומה שנמשך שכל ודעת במדות הוא רק בדרך מעבר בלבד כו', דהיינו כדי שיהי' במדות טוב ההכרה וההבחנה ע\"פ הדעת והשכל שיורה דרכם בין טוב לרע שלא יטעו להחליף על הרע טוב ועל טוב רע כמו עד\"מ המורה דרך או אור המאיר שלאור זה ילך ולא י[ו]זק במקום רק<sup data-n=\"2933\">38</sup> יבחין הטוב<sup data-n=\"2934\">39</sup> בטוב ומואס ברע ע\"פ הוראת השכל<sup data-n=\"2935\">37</sup> כמ\"ש במ\"א באורך (וראי' לזה מכל התו\"מ שעיקר יסודם על המדות שבלב באוי\"ר כאשר הן נשלמים ע\"פ הדעת בהיות[ו] בן י\"ג שנה שאז הוא בר עונשין<sup data-n=\"2936\">40</sup> להתחייב בעונש בעברו על ל\"ת כו', ובפחות מי\"ג שנה אע\"פ ש[הוא] חריף אינו בר עונשין [כלל], ולמה לא נחייב עד היותו בן כ' שנה שאז נשלמו המוחין<sup data-n=\"2937\">41</sup> אם היו המוחין עיקר האדם, וכן לענין דיני ממונות תלוי במדות שבלב אם נשלמו גם בקטנות המוחין כמו הפעוטות [בן ו' שנים]",[["2927","31","<b>וייצר הוי' אלקים</b>: בראשית ב, ז. במאמרי אדה\"ז תקס\"ד כאן ע' סו מציין כ\"ק אדמו\"ר הצ\"צ וע' זח\"ג נשא קמא\"ב."],["2928","32","<b>ויברא אלקים</b>: בראשית א, כז."],["2929","33","<b>אלה תולדות השמים</b>: בראשית ב, ד."],["2930","34","<b>וכל שיח השדה. . כי לא המטיר</b>: בראשית שם, ה."],["2931","35","<b>עיקר בחי' אדם. . המדות</b>: ראה גם מאמרי אדה\"א דברים ח\"ב ע' תקלז. שע\"ת ט, א ובהערה 5."],["2932","36","<b>חכים</b>: א: וחכ' שזהו. ד: וחכ' שהוא."],["2933","38","<b>רק</b>: אד: רע כו כך."],["2934","39","<b>יבחין הטוב</b>: א: יבחר. ד: יבחין היטיב."],["2935","37","<b>במדות. . ע\"פ הוראת השכל</b>: ראה מאמרי אדה\"ז תקס\"ח ח\"א ע' ג' ואילך. תו\"ח בראשית יא, ב ואילך."],["2936","40","<b>י\"ג שנה. . בר עונשין</b>: ראה סנהדרין סח, ב. מאמרי אדה\"א קונטרסים ע' תיג. וש\"נ."],["2937","41","<b>בן כ' שנה. . המוחין</b>: ראה ע\"ח (שער דרושי הצלם) שכ\"ה דרוש ח. לקו\"ת במדבר ב, א. שע\"ת ז, א. שעה\"י קלג, ב (וראה גם בהנסמן לשם). לקמן פ' תצוה שסא, ד."]]],[2300550182,"מקחן מקח<sup data-n=\"2938\">42</sup> וממכרן ממכר כו') וד\"ל. [ו]כך כל עבוד[ה] שבלב באוי\"ר אע\"פ שצריך להיות בדעת דייקא כמ\"ש וידעת והשבות, אבל ההשבה אל הלב הוא עיקר האדם, אבל כ\"ז שהידיעה הזאת אינה עדיין רק [במוחו] במח' בלבד, הגם שיתפעל מאד במח' אין זה נק' אד\"ם שאע\"פ שמייחד יחוד הוי' אלקים בהשגה טובה ונקלט מאד במוחו, הרי ידיעה זו שבמוחו כו'<sup data-n=\"2939\">43</sup>, הוי' הוא [ה]אלקי' אינה אלא במחשבה במוח שהוא בחי' מקיף בלבד (כידוע דכל המקיפי' בבינה<sup data-n=\"2940\">44</sup> ) ולא בעיקר האדם שהוא הלב. אך במצוה השני' דוהשבות אל לבבך, היינו שידיעה והשגה זו דיחוד הוי' ואלקי' יהי' נכנס ונקלט בלבו של אדם זהו עיקר היחוד דשם הוי' ואלקי' שבו שורה גילוי אור עצמות א\"ס ב\"ה כמ\"ש ושכנתי בתוכם שהוא ית' שוכן בלב כאו\"א מישראל ביחוד זה דהוי' ואלקי' כשהוא בא בגילוי אור בלב דוקא כמ\"ש והשבות אל לבבך דוקא כי הוי' הוא האלקי', מפני שבלב האדם דוקא תלוי עיקר היחוד דהוי' הוא האלקי' לפי שהוא בצלם אדם העליון כמ\"ש נעשה אדם בצלמנו<sup data-n=\"2941\">45</sup> כו'. וכאשר בלבו של אדם למטה מתייחדי' <span data-k=\"pg\">890</span> ּ ב' שמות דהוי' ואלקים כ\"כ<sup data-n=\"2942\">46</sup>, כמו\"כ מתייחדים בלב [ה]אדה\"ע ב' שמות הללו דהוי' ואלקי', וכמ\"ש כמים הפנים לפנים<sup data-n=\"2943\">47</sup> כן לב האדם אל האדם, וזהו ועשו לי מקדש ושכנתי בתוכם בתוך לב כאו\"א [ביחוד] דהוי' ואלקים וד\"ל.\n<b>אך</b> [הנה] מ\"ש בתוכם [ב]כאו\"א שהן ב' לבבות לב הפנימי החיצון כו' שזהו ב' שמות דהוי' ואלקים שמתייחדי' זהו ענין מזבח הפנימי ומזבח החיצון, דהנה כל ענין מזבח החיצון הי' להקריב עליו כי<sup data-n=\"2944\">48</sup> קרבנות פרים וכבשים דהיינו שיערכו עצים על המזבח באש שלמטה, וישרפו את הבהמה בהקטרת אימורים להיות לריח ניחוח כו', והיינו ע\"י בחי' אש שלמעלה שהי' יורד ונק' אר\"י' דאכיל קורבנין<sup data-n=\"2945\">49</sup> כמ\"ש בזהר. ונמצא דאש שלמטה שמצוה להביא מן ההדיוט<sup data-n=\"2946\">50</sup> דבני אהרן ערכו עצים<sup data-n=\"2947\">51</sup> ואש הוא הגורם ירידת אש שלמעלה ברוחניות שהוא בחי' הריח ניחוח לה' כו'. וכך יובן בתפלה דעכשיו שבמקום קרבן<sup data-n=\"2948\">52</sup> תקנו, כידוע דאד\"ם הוא המקריב מן הבהמה<sup data-n=\"2949\">53</sup> דהיינו בחי' שם מ\"ה דאד\"ם<sup data-n=\"2950\">54</sup> שהוא הנשמה האלקית מעלה ומקריב לנפש הבהמית שהוא נפש המתאווה [ל]תאוות חומריות [ב]אש זרה כבהמה ממש. וכמו שהבהמה גשמי' הי' לגחלת אש בוערת בשריפ' ע\"ג המזבח ע\"י אש שלמעלה שירד כו', כך אש זה שנתפעל בלב החומריות לאלקות זהו כמו אש שלמטה דמזבח",[["2938","42","<b>הפעוטות [בן ו' שנים] מקחן מקח</b>: גיטין נט, א."],["2939","43","<b>כו'</b>: ד: כי."],["2940","44","<b>דכל המקיפי' בבינה</b>: ראה ע\"ח (שער טנת\"א) ש\"ה, פ\"ג."],["2941","45","<b>נעשה אדם בצלמנו</b>: בראשית א, כו."],["2942","46","<b>כ\"כ</b>: אד: ליתא."],["2943","47","<b>כמים הפנים לפנים</b>: משלי כז, יט [ושם: להאדם]."],["2944","48","<b>כי</b>: אד: ליתא."],["2945","49","<b>אר\"י' דאכיל קורבנין</b>: נסמן לעיל פ' יתרו ער, א."],["2946","50","<b>שמצוה להביא מן ההדיוט</b>: ראה ערובין סג, א. תו\"כ ויקרא א, ז. מאמרי אדה\"א דברים ח\"ד ע' א'תפה. וש\"נ."],["2947","51","<b>דבני אהרן ערכו עצים</b>: ויקרא א, ז."],["2948","52","<b>בתפלה. . שבמקום קרבן</b>: נסמן לעיל פ' יתרו רסח, ב."],["2949","53","<b>דאד\"ם הוא המקריב מן הבהמה</b>: ראה גם מאמרי אדה\"א ויקרא ח\"א ע' ב. ע' יח. הנחות תקע\"ז ע' יד. וש\"נ."],["2950","54","<b>שם מ\"ה דאד\"ם</b>: נסמן לעיל פ' משפטים רפא, ד."]]],[2300550214,"ובחי' התלהבות דרשפי אש שלהבת י\"ה שבא מחמת ההשבה<sup data-n=\"2951\">55</sup> אלקי' שנכנס וירד בלב האדם, זהו כמו אש שלמעלה שהי' יורד ע\"ג המזבח. כי הרי התפעלות זאת שבהשג' אלקות בלב נק' שלהבת י\"ה ממש ונכלל בה התפעלו' [חום הטבעי] שבלב ונשרף והי' לגחלת כו', היינו שנהפך מרע לטוב כי נתבער כל הרע שבו [כ]גחלת ע\"ג המזבח שמן שריפת הפר והכבש כו'. וזה הנק' בחי' גבורות קשות דאש זרה דק\"נ שנברר ונתפעל'<sup data-n=\"2952\">56</sup> באש שלמעלה להיות לריח ניחוח [כו', פי' לריח ניחוח] לשון נחות<sup data-n=\"2953\">58</sup> דרגא<sup data-n=\"2954\">57</sup> שזהו ריח הקרבן הנשרף בשלהבת י\"ה שמברר בירורים דנוגה גורם עי\"ז ירידה והמשכה מלמעלה למטה להיות אור העצמות א\"ס ב\"ה למטה<sup data-n=\"2955\">59</sup> נחות דרגא מעצמות[ו] להיות שוכן בגילוי<sup data-n=\"2956\">60</sup> בהיכל ק\"ק ובלב כאו\"א מישראל ולא יסתירנו ולא יעלימנו שם אלקי' כלל כו'. וכמו\"כ עכשיו בכל תפלה שבמקום קרבן נעשה זה ע\"י התלהבות אלקי' שלהבת י\"ה כאשר יורד בבשר לב החיצוני דוקא, וכמו לבי ובשרי ירננו<sup data-n=\"2957\">61</sup> אל אל חי, וכן צמאה לך נפשי<sup data-n=\"2958\">62</sup> כמה לך בשרי כו', ובזה נמשך גילוי אור א\"ס עצמו בלב כאו\"א כשהוא דוקא בחיצוני' הלב כמו הקרבנו' [ש]על מזבח החיצון שנק' ריח ניחוח לה' ממש וד\"ל.\n[ג] <b>ומעתה</b> יש להבין ענין מזבח הפנימי, דהנה ידוע ענין מזבח הפנימי שלא הי' מיוחד רק להקטיר עליו קטרת ולא הי' יורד עליו אש שלמעלה כמו במזבח החיצון כלל ולא נאמר בקטורת לריח ניחוח כו', ועכ\"ז מעלת הקטורת גבוה הרבה מן קרבנות<sup data-n=\"2959\">63</sup> של מזבח החיצון וכידוע שהיו מביאים גחלים לוחשות מן מזבח החיצון ונותנים ע\"ג מזבח הפנימי<sup data-n=\"2960\">64</sup> [מפני שמצוה להביא אש מן ההדיוט הרי גחלי מזבח החיצון שכבר נאכלו היו לאש של מטה במזבח הפנימי] והריח העולה משריפת הקטרת הוא למעלה <span data-k=\"pg\">תמה</span> ּ מריח ניחוח דקרבנות כידוע. והענין הוא דמזבח הפנימי הוא [כמו] ענין פנימי[' הלב] ומזבח החיצון הוא כמו בחי' חיצוניות הלב שנשרף באש שלמעלה כנ\"ל, מאחר שנעשה גחלים לוחשות במזבח החיצון היינו כאשר כבר נהפך לב החיצון ל[י]כלל באש שלהבת י\"ה כנ\"ל אזי מביאים למזבח הפנימי שהוא פנימית הלב כדי שיוכל להיות ריח הקטורת עולה מעלה מעלה משום דמצוה להביא' מן ההדיוט כו'. וביאור ענין פנימית הלב הוא מזבח הפנימי וענין הקטרת שהוא למעלה גם מאש שלמעלה כו'.",[["2951","55","<b>ההשבה</b>: אד: ההשגה."],["2952","56","<b>ונתפעל'</b>: אד: ונתעלה."],["2953","58","<b>נחות דרגא</b>: יבמות סג, א."],["2954","57","<b>ניחוח] לשון נחות דרגא</b>: ראה גם מאמרי אדה\"ז תקס\"ד כאן (ע' סז) ובהנסמן במ\"מ לשם. מאמרי אדה\"א הנחות תקע\"ז ע' מט. וש\"נ. לקמן פ' תצוה שמח, ג."],["2955","59","<b>למטה</b>: אד: ליתא."],["2956","60","<b>בגילוי</b>: שם ניתוסף: למטה."],["2957","61","<b>לבי ובשרי ירננו</b>: תהלים פד, ג."],["2958","62","<b>צמאה לך נפשי</b>: שם סג, ב."],["2959","63","<b>הקטורת גבוה הרבה מן קרבנות</b>: ראה גם לקו\"ת נשא כט, א. מאמרי אדה\"א דברים ח\"ג ע' א'קלו. וש\"נ. ח\"ד ע' א'רמד. ש\"א ז, א ואילך."],["2960","64","<b>גחלים. . מן מזבח החיצון. . הפנימי</b>: ראה תמיד לג, א. רמב\"ם הל' תמידין ומוספין פ\"ג, ה\"ה. וראה גם אוה\"ת סוכות ע' א'תשכג. שמות כרך ח ע' ג'פג."]]],[2300550246,"<b>והנה</b> יש להקדים ענין הידוע בהפרש שבין תפלות חול לתפלת שבת<sup data-n=\"2961\">65</sup> כמ\"ש בזהר ע\"פ אז תתענג על הוי'<sup data-n=\"2962\">66</sup> דא צלותא [דמעלי שבתא] כו' דתפלת החול הוא לברר לאש זרה דחום הטבעי מרע לטוב כו' ע\"י אש שלהבת י\"ה בביטול כל רצון זר כו', ובשבת העיקר הוא התפעלות הנשמה האלקי' מצד עצמה כמו [שא'] כל הנשמ\"ה תהל\"ל י\"ה<sup data-n=\"2963\">67</sup> שהנשמה עצמה תהל\"ל י\"ה בלי יש בזה חיבור עם הלב בשר כלל. והוא ענין התפעלות העונג האלקי שמתענג על ה', שזהו למעלה גם מבחי' שלהבת י\"ה כנ\"ל, וכדמיון התענוג שבריח הבושם שאין הגוף נהנה ממנו רק הנשמה לבד<sup data-n=\"2964\">68</sup> כו'. וכמו הנשמות בג\"ע שנהנין בעונג אלקי ממש בבחי' עריבות מתיקות ידידות<sup data-n=\"2965\">69</sup> כו' בסודות וטעמי תורה בבחי' שעשועי' העצמי' (בל\"א איין קוועלונג) כו', וזהו דוקא בפנימי' הלב ששם משכן הרוח והנשמה שבמוח<sup data-n=\"2966\">70</sup> שמתענג בעונג נפלא בהתקשרות עוז כו' נק' קטורת, והוא מלשון התקשרות כמ\"ש בזהר שנק' קשורא דנשמתא<sup data-n=\"2967\">71</sup> כו'. ופנימי' הלב הוא בחי' הכלי לזה כמו מזבח הפנימי להקטיר הקטרת, לפי שהתפעלות פנימית הלב הוא למעלה מהתלהבות שלהבת י\"ה ג\"כ כי הוא הנק' קלא פנימאה דלא משתמע<sup data-n=\"2968\">72</sup> כו', שאינו רק בבחי' העומק של ההתקשרו' הגדולה ליכלל ולידבק למעלה כמו בה' תתהלל נפשי<sup data-n=\"2969\">73</sup> כו' וכמ\"ש רשב\"י בחד קטירא אתקטרנא כו', בי' אחידא<sup data-n=\"2970\">74</sup> בי' להיטא. ולכך לא הי' צריך להיות אש שלמעלה ע\"ג המזבח כו', כי אש שלמעלה כמו שלהבת י\"ה דנשמה הוא הבא בלב בשר לברר כו', אבל הנשמה עצמה א\"צ בירור ותיקון<sup data-n=\"2971\">75</sup> מאחר שכבר הובררה כי שרשם מעולם התיקון רק צריכה עלי' ודיבוק למעלה בבחי' התכללות והתקשרות עי\"ז<sup data-n=\"2972\">76</sup> בעצמותו ית' [ליכלל וליבטל] כביטול הנר בפני האבוקה שזהו כמו לאשתאבא בגופא דמלכא<sup data-n=\"2973\">77</sup> ממש. והיינו ענין מיכאל מקריב נשמות<sup data-n=\"2974\">78</sup> ע\"ג המזבח שהוא [על] מזבח הפנימי [דוקא] ולא על מזבח החיצון (רק שמצוה להביא גחלי אש ממזבח החיצון למזבח הפנימי דהיינו שיהי' מן הבירורי' דרפ\"ח כו' שכבר הוברר להיות עי\"ז ענין הקטרת העולה מן הגחלים מעלה לנשמות למעלה מעלה) דעיקר הענין במזבח החיצון הוא לברר בירורים דרפ\"ח כו', והיינו להפוך חשוכא לנהורא ומרירו כו', ובעבודת ה' היינו להפוך טבעיות המדות [ה]רעות דנה\"ט שיהי' בהם ביטול הרצון להיות לבו רק להטותו כו', גם בועש\"ט ביתר מכפי",[["2961","65","<b>בהפרש שבין תפילות חול לתפלת שבת</b>: ראה סידור שער הר\"ח ריא, ג. מאמרי אדה\"א שמות ח\"א ע' קפה ואילך. וש\"נ. לעיל פ' יתרו רסח, ב. וראה גם לקמן פ' ויקהל תלז, ג. תמא, ב ואילך."],["2962","66","<b>אז תתענג על הוי'</b>: ישעי' נח, יד. וכ\"ה בכ\"מ בשם הזהר — ראה לקמן פ' ויקהל תלז, ג. תמא, ג. הנסמן במאמרי אדה\"א שמות ח\"א ע' קצ."],["2963","67","<b>כל הנשמ\"ה תהל\"ל י\"ה</b>: תהלים קנ, ו. ראה גם דרך חיים שער התפלה עז, ג. פג, ד. מאמרי אדה\"א בראשית ס\"ע קכח ואילך וע' תקע."],["2964","68","<b>התענוג שבריח. . הנשמה לבד</b>: ראה ברכות מג, ב."],["2965","69","<b>עריבות מתיקות ידידות</b>: ראה אוה\"ח ר\"פ אחרי ד\"ה א\"י עז\"ה. ומובא בכ\"מ בדא\"ח ומהם מאמרי אדה\"א בראשית ע' קעו. וש\"נ. ש\"א ב, א. טו, א. שה\"א ז, ב ובהערה 28."],["2966","70","<b>הלב ששם משכן הרוח והנשמה שבמוח</b>: ראה אבן עזרא משפטים כג, כה. לעיל פ' בשלח קמה, א. וש\"נ."],["2967","71","<b>קטורת. . קשורא דנשמתא</b>: במאמרי אדה\"ז תקס\"ד כאן (ע' סז): קשורא דכולא. — ראה זהר ויחי רל, א. ויקהל ריט, ב. שמיני לז, ב. הלשון קשורא דנשמתא מובא גם לעיל פ' וארא סג, ב. וש\"נ."],["2968","72","<b>קלא פנימאה דלא משתמע</b>: נסמן לעיל פ' משפטים רפז, ד."],["2969","73","<b>בה' תתהלל נפשי</b>: תהלים לד, ג."],["2970","74","<b>בחד קטירא. . בי' אחידא</b>: נסמן לעיל פ' משפטים רפט, ב הערה 131."],["2971","75","<b>הנשמה עצמה א\"צ בירור ותיקון</b>: ראה תניא פל\"ז. ש\"א ט, א ובהערה 4. לעיל פ' בשלח רכו, א."],["2972","76","<b>עי\"ז</b>: א: ליתא. ד: עוז."],["2973","77","<b>לאשתאבא בגופא דמלכא</b>: נסמן לעיל פ' יתרו רסט, ד."],["2974","78","<b>מיכאל מקריב נשמות</b>: ראה גם לעיל פ' שמות ה, א. וש\"נ."]]],[2300550277,"המדה בתו\"מ כו', וזהו ע\"י אש שלמעלה דוקא. אבל מזבח הפנימי ששם א\"צ בירור כלל רק להעלות את הנשמות שתתקשר ונכלל למעלה לאשתאבא בגופא דמלכא <span data-k=\"pg\">892</span> ּ התורה<sup data-n=\"2975\">79</sup> למעלה גם מבחי' שלהבת י\"ה הנק' אש שלמעלה רק בבחי' אור התענוג וההתקשרות לבד שזהו בבחי' פנימי' הלב כו', [והוא ענין ה]ריח [שב]קטורת בבשמים הנשרפים על הגחלים שנלקחים מן מזבח החיצון. והנה אנו רואים בריח הבושם שהוא ערב לנפש ביותר עד שיעלה למעלה בעומק עצם הנפש שלמעלה מן המוחין דחו\"ב כו', עד שמכח הריח הזה מחזק ומאיר אור חדש להשיב ולהמשיך תוס' אור גדול בחו\"ב וגם ברצון ותענוג דהיינו ממקור הרצון ותענוג ושכל [כו'], כך הקטורת בענן העולה מריח הבשמים בזאת להריח<sup data-n=\"2976\">80</sup> תעלה הנשמה למעלה מעלה בעילוי אחר עילוי עד רום המעלות במהו\"ע א\"ס ב\"ה ונתקשר[ה] שם בקשר אחר קשר ומוסיף לחדש אור [גדול במוחין עליוני' וגם באור הרצון והתענוג העליון וכמ\"ש שמן וקטרת ישמח לב<sup data-n=\"2977\">81</sup> העליון בתוס' אור] התענוג ורצון ומוחין חדשים שלא הי' כמוהו גם בריח ניחוח דקרבנות [הגם] שנק' לחם שסועד הלב ומחזק המוח, אבל אין זה רק מה שמתחבר השכל ורצון ותענוג מהנפש בגוף, אבל ריח הקטורת הוא רק לנשמות ולא לגוף [כלל כנ\"ל] וד\"ל.\n<b>וזהו</b> ויחד לבבינו לאהוי\"ר כו', פי' יחוד [ה]לבבות היינו יחוד הב' לבבות הפנימי והחיצון שהוא מזבח הפנימי ומזבח החיצון ע\"י הבאת גחלי אש ממזבח החיצון למזבח הפנימי בשביל העלאת ריח הקטרת כנ\"ל, וכמו\"כ למעלה [ב]מזבח העליון שמיכאל כה\"ר מקריב נשמות האלקי' מביאים גחלי אש ממזבח החיצון, והוא ממה שמקריבים פרים [כו'] שהן בירורי' דשם ב\"ן כמו פני שור שבמרכבה [כו'] שעז\"א אש תמיד תוקד<sup data-n=\"2978\">82</sup> על המזבח כו' וד\"ל. וזהו וערכו בני אהרן עצים<sup data-n=\"2979\">83</sup> ונת[נו] אש כו' שמצוה להביא מן ההדיוט, דהיינו ע\"י רשפי אש שבאה\"ר דאהרן שוש' דמטרוניתא<sup data-n=\"2980\">84</sup> שממשי[כים ובוערים] בלב החיצון שנק' מזבח החיצון עי\"ז ביכולתם להעלות נש\"י ועוזרים אותם להעלות בריח הקטורת דמזבח הפנימי כו'. [ו]כמו\"כ [ב]ק\"ש ותפלה הנה ידוע דט\"ו ווי\"ן דאמת ויציב<sup data-n=\"2981\">85</sup> הוא ענין הקטרת וכמ\"ש תק\"ה<sup data-n=\"2982\">86</sup>, וזה ואנ\"י תפלה<sup data-n=\"2983\">87</sup> כו', מה שבתפלה שנק' סולם<sup data-n=\"2984\">88</sup> עולות כל הנשמות בשלהבת י\"ה בהתלהבות לב בשר",[["2975","79","<b>התורה</b>: אד: ה\"ז."],["2976","80","<b>בזאת להריח</b>: א: בריח זה. ד: בזאת בריח זה."],["2977","81","<b>שמן וקטורת ישמח לב</b>: משלי כז, ט."],["2978","82","<b>אש תמיד תוקד</b>: צו ו, ו."],["2979","83","<b>וערכו בני אהרן עצים</b>: ראה ויקרא א, ז."],["2980","84","<b>דאהרן שוש' דמטרוניתא</b>: נסמן לעיל פ' יתרו רסט, ד."],["2981","85","<b>דט\"ו ווי\"ן דאמת ויציב</b>: ראה גם מאמרי אדה\"א ויקרא ח\"א ע' ג. הנסמן לעיל פ' וארא סג, ב."],["2982","86","<b>וכמ\"ש תק\"ה</b>: אד: וכמשי\"ת ב(ע)\"ה."],["2983","87","<b>ואנ\"י תפלה</b>: תהלים קט, ד. ראה זהר תזריע מט, ב. פע\"ח (שער התפלה) בתחלתו. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תקצב."],["2984","88","<b>שבתפלה שנק' סולם</b>: ראה זח\"א (רע\"מ בהשמטות) רסו, ב. ח\"ג (תוספת) שו, ב. ת\"ז תמ\"ה (פג, א)."]]],[2300550305,"ובהתקשרות דריח הקטורת בנשמות הכל ע\"י אנ\"י שהוא מכח האלקי עצמ[ו] שהוא מבחי' המל' שנק' אנ\"י, כמו ואנ\"י בתוך הגול\"ה<sup data-n=\"2985\">89</sup>, [ד]גלו לאדום שכינה עמהם<sup data-n=\"2986\">90</sup> ששוכן אתם גם בתוך טומאותם<sup data-n=\"2987\">91</sup>, והוא המעויל<sup data-n=\"2988\">92</sup> ללב בשר לטהרו ולזככו עד שישרף כמו גחלי אש, ולהיות כח במזבח הפנימי לק[ש]רם למעלה מעלה וד\"ל, וזהו אש תמיד תוקד על המזבח החיצון שהוא הלב בשר לא תכבה לעולם וד\"ל.\n[ד] <b>והנה</b> מעתה יש להבין בענין היריעות שבמשכן שהי' בחי' המקיפים ו[ב]ענין הכלים שהן אור פנימי, דהנה ביריעות המשכן היו ד' מינים תכלת וארגמן ותולעת שני ושש משזר<sup data-n=\"2989\">93</sup> כידוע, וכנגד זה [הי'] בכלים ג\"כ ארבעה היינו [ה]ארון ומנורה ושולחן ומזבח הפנימי לבד ממזבח החיצון שהי' בחצר האוהל<sup data-n=\"2990\">94</sup> אהל מועד. והנה תחלה י\"ל ענין הד' מינים שביריעות תכלת וארגמן כו', והנה אמרו תכלת דומה לים וים לרקיע<sup data-n=\"2991\">95</sup> הרי תכלת נדמו<sup data-n=\"2992\">96</sup> לרקיע בגוונין שזהו מורה על בחי' המקיף וסובב, ועוד מורה על הוראות<sup data-n=\"2993\">97</sup> שהרקיע נורא הוא, וכמ\"ש ועל ראשי החיות<sup data-n=\"2994\">98</sup> רקיע <span data-k=\"pg\">תמו</span> ּ כעין הקרח הנורא כו'. ושניהם ענין א' הוא שזהו מדת היראה שמבחי' מקיף דוקא כמ\"ש בזהר דאית יראה ואית יראה<sup data-n=\"2995\">99</sup> יר\"ע ויר\"ת כו', פי' יראת הרוממות נק' יר\"ע שלא תוכל להכיל [ב]כלי המוח והלב ומה שיכול להכיל היראה בלבו נק' יר\"ת. וביאור הדבר הנה אנו רואים באדם כאשר מתפעל ביראה ופחד בלבו מאיזה אדם גדול או שר גדול הנה [ת]בא היראה בלבו באופן שיוכל שאת מפני שהוא לפי המדה וערך גדלות ורוממות השר [כו'], אבל כאשר נתפעל ביראה ופחד מן המלך הגדול שמצד עצם הרוממות וההתנשאות של המלך תפול [אימתו] עליו ביתר מכפי המדה שלא תוכלל<sup data-n=\"2996\">100</sup> במוחו ולבו ויעמוד מרחוק ברתת וזיע כו', הנה זהו הנק' יר\"ע שבאה בבחי' מקיף, וכמו במ\"ת דכתיב וירא העם וינועו<sup data-n=\"2997\">101</sup> ויעמדו מרחוק כי לא יכלו להכיל היראה בלב מקרוב ע\"כ עמדו מרחוק מיראה לגשת מקרוב שלא יתבטלו ממציאות לגמרי. וכה\"ג בקעומ\"ש בכל אדם יש בזה ב' מדריגות, הא' אשר מקבל אימת מל' שמים בלבו ודעתו בטעם ודעת שיוכל להכיל במוחו ולבו דוקא מצד ההשגה והכרה בגדולת ה' ונפלאותיו וחסדי' ורחמי' אשר<sup data-n=\"2998\">102</sup>",[["2985","89","<b>ואנ\"י בתוך הגול\"ה</b>: יחזקאל א, א."],["2986","90","<b>[ד]גלו לאדום שכינה עמהם</b>: ספרי מסעי לה, לד. ראה הנסמן לעיל פ' שמות א, ד הערה 53."],["2987","91","<b>ששוכן אתם גם בתוך טומאותם</b>: אחרי טז, טז. ראה גם שה\"א א, א. מאמרי אדה\"א הנחות תקע\"ז ע' רפו."],["2988","92","<b>המעויל</b>: אד: המעורר."],["2989","93","<b>ביריעות המשכן. . תכלת. . ושש משזר</b>: תרומה כו, א."],["2990","94","<b>האוהל</b>: אד: ליתא."],["2991","95","<b>תכלת דומה לים וים לרקיע</b>: ראה חולין פט, א. הנסמן במאמרי אדה\"ז תקס\"ד כאן (לע' סח)."],["2992","96","<b>נדמו</b>: א: ידמה. ד: דומה."],["2993","97","<b>הוראות</b>: שם: היראה."],["2994","98","<b>ועל ראשי החיות</b>: יחזקאל א, כב [ושם: ודמות על ראשי החי' — נסמן לעיל פ' בא צז, ד]."],["2995","99","<b>דאית יראה ואית יראה</b>: ראה זהר בהקדמה יא, ב. מאמרי אדה\"א נ\"ך ע' סח. וש\"נ."],["2996","100","<b>תוכלל</b>: אד: יוכל שאת כלל."],["2997","101","<b>וירא העם וינועו</b>: יתרו כ, טו."],["2998","102","<b>ורחמי' אשר</b>: אד: ורוממו' אור."]]],[2300550330,"שפעו הבלתי מוגבל, וכך הוא במלאכי' שיש בחי' מפארים<sup data-n=\"2999\">103</sup> ליוצרם ע\"י השג[ה] ודעת המצומצם בהם כו', וכולם מקבלים עליהם עומ\"ש כו'. אבל התפעלות האדם ביראה ופחד מצד עוצם הרוממות דעצמות א\"ס ב\"ה שלמעלה מעלה מאור השפע הנמשך מאתו בעולמות רק כמו שהוא במהו\"ע [ד]לית מח' תפיסא בי' כלל<sup data-n=\"3000\">104</sup> וכולא קמי' כלא<sup data-n=\"3001\">105</sup> כו' שהוא הנק' מל' דא\"ס עצמו בחי' ההתנשאות שמצד עצמו שמתנשא ומרומם לבדו כו', וכאשר משם יתגלה או\"מ נק' סוכ\"ע בכלל, אזי לא יוכל כלי מוחו ולבו להכיל היראה ופחד, וכמו לע\"ל דכתיב ובאו במערות צורים<sup data-n=\"3002\">106</sup> מפני פחד ה' כו', וכמו שאנו אומרים תן פחדך<sup data-n=\"3003\">107</sup> כו'. וכך הוא [גם עתה] בעולמות עליונים ותחתונים רק שבא האור בבחי' מקיף עליהם, וכמו במלאכים שיש בהם אימת מ\"ש עליהם בבחי' מקיף, וכמו שא' ואימתו עליהם<sup data-n=\"3004\">108</sup>, מלמטה<sup data-n=\"3005\">109</sup> היינו כמ\"ש שום תשים עליך [מלך]<sup data-n=\"3006\">110</sup> בקבלת עומ\"ש עליהם<sup data-n=\"3007\">111</sup> בבחי' מקיף עליך בפחד ויראה מרחוק מצד עוצם הרוממות וההתנשאות של מדת [ה]מל' כו', וזהו הנק' בחי' מקיף דמדת מל' שלא יוכל לבוא במקבלים בבחי' או\"פ בכלי כלל כו' וד\"ל. וזהו ענין התכלת שדומה לים ולרקיע שהוא רקיע המקיף מרחוק (ו[לא] כמו שאמר חבקוק שמעתי שמעך יראתי<sup data-n=\"3008\">112</sup> שמוגבל בכלי), והנה [בבחי'] מקיף זה דמל' בבריאה<sup data-n=\"3009\">113</sup> עילאה הנ\"ל ויש<sup data-n=\"3010\">114</sup> עוד טעם לזה לבד הרוממות וההתנשאו' שמקיף מלמעלה [הנה] המראה והגוון הוא נורא בעצם, והוא כמו מראה התכלת ומראה הרקיע שנורא הוא בעצם. וכך הוא מובן<sup data-n=\"3011\">115</sup> במדת מל' למעלה שנק' אש אוכלה<sup data-n=\"3012\">116</sup> כו', וכמ\"ש כי ה' אלקיך אש אוכלה הוא<sup data-n=\"3013\">117</sup> כו' שמראה דאש זה נורא ביותר והכל א' הוא<sup data-n=\"3014\">118</sup> וד\"ל. וזהו ענין היריע[ות] דתכלת שהי' בבחי' [מקיף] על המשכן כמו שלמעלה בחי' המל' דמלכותך מל' כ\"ע<sup data-n=\"3015\">119</sup> הוא בבחי' מקיף וסובב והוא בחי' ההתנשאות מרחוק על הנבראים לפי שלא יכילנו לקבל בתוכם האור מעוצם הרוממות כו' וד\"ל.\n<b>וענין</b> הארגמן ותולעת שני, הנה התולעת שני <span data-k=\"pg\">894</span> ּ בא מבחי' [הגבו']<sup data-n=\"3016\">120</sup> שהוא מראה האודם<sup data-n=\"3017\">121</sup> בתכלית וכמ\"ש במ\"א בפי' אם יהיו חטאיכם כשנים<sup data-n=\"3018\">122</sup> כשלג<sup data-n=\"3019\">123</sup> כו' שהתולע הוא המוציא חום בשני<sup data-n=\"3020\">124</sup>, וזהו אם יאדימו כתולע עצמו כו'. ולנגד זה",[["2999","103","<b>שיש בחי' מפארים</b>: שם: שמשבחי' ומפארים."],["3000","104","<b>[ד]לית מח' תפיסא בי' כלל</b>: ראה ת\"ז בהקדמה (יז, א)."],["3001","105","<b>וכולא קמי' כלא</b>: נסמן לעיל פ' משפטים רעז, ב."],["3002","106","<b>ובאו במערות צורים</b>: ישעי' ב, יט [בדילוג]."],["3003","107","<b>תן פחדך</b>: תפלת העמידה לימים נוראים."],["3004","108","<b>ואימתו </b>[אד: ואימתך]<b> עליהם</b>: ראה גם לעיל פ' וארא עה, ב. וש\"נ."],["3005","109","<b>מלמטה</b>: אד: ומלמטה."],["3006","110","<b>שום תשים עליך [מלך]</b>: פ' שופטים יז, טו."],["3007","111","<b>עומ\"ש עליהם</b>: אד: מ\"ש."],["3008","112","<b>שמעתי שמעך יראתי</b>: חבקוק ג, ב."],["3009","113","<b>בבריאה</b>: אד: דיראה."],["3010","114","<b>ויש</b>: שם: יש."],["3011","115","<b>הוא מובן</b>: שם: יובן."],["3012","116","<b>אש אוכלה</b>: נסמן בהערה הבאה. אד: אשא תכלא — זהר (רע\"מ) צו כט, ב. בראשית נא, א."],["3013","117","<b>כי ה' אלקיך אש אוכלה הוא</b>: ואתחנן ד, כד."],["3014","118","<b>הוא</b>: אד: ליתא."],["3015","119","<b>דמלכותך מל' כ\"ע</b>: תהלים קמה, יג."],["3016","120","<b>התולעת שני. . [הגבו']</b>: ראה מאמרי אדה\"א שמות ח\"ב ע' תרעז. דברים ח\"ד ע' א'שפב. וש\"נ. תורת חיים בראשית מא, ג. אוה\"ת ויקהל כאן (ע' ב'קפז)."],["3017","121","<b>[הגבו'] שהוא מראה האודם</b>: ראה פרדס (שער הגוונים) ש\"י, פ\"א. פע\"ח (שער עולם העשי') ש\"ה, פ\"ג. לקוטי תורה להאריז\"ל ישעי' א, יח."],["3018","122","<b>אם יהיו חטאיכם כשנים</b>: ישעי' א, יח. ראה גם מאמרי אדה\"א דברים ח\"ד ע' א'שפא ואילך."],["3019","123","<b>כשלג</b>: אד: ליתא."],["3020","124","<b>שהתולע. . חום בשני</b>: ראה גם מאמרי אדה\"א דברים ח\"ד ע' א'שפב. וש\"נ."]]],[2300550355,"בקדושה האלקי' הוא עצם ומקור [כל] הגבורות עליונות [ו]הוא בחי' המקור לכל התפעלות של המלאכים ברשפי אש כו', וכמ\"ש והחיות רצוא<sup data-n=\"3021\">125</sup> כו' בתשוקה נפלאה [ב]חום רשפי אש גדול, וזה בא מכח ומקור כל הגבורות העליונים שני<sup data-n=\"3022\">126</sup> תולעת שני, וזה הי' ביריעות המשכן שהוא בבחי' מקיף לעורר כל בחי' העלאה [דרצוא כו'] באו\"פ בכלים שבמשכן [ו]בפרט בהעלאה בקרבנות כו' וד\"ל. וענין הארגמן הוא בחי' הת\"ת<sup data-n=\"3023\">127</sup>, להיות שהארגמן הוא מראה הכולל מכל הגוונים יחד, והיינו מדה\"ר שבבחי' המקיף דוקא, והיינו כמו שאנו רואים שמתעורר אדם בהתפעלות הרחמים על נפשו כו', שבזה יש התכללות מחו\"ג<sup data-n=\"3024\">128</sup> שמצד הרוממות<sup data-n=\"3025\">129</sup> והרוגז על ריחוקו מה' זהו מבחי' הגבורות, ומאשר<sup data-n=\"3026\">130</sup> שסיבת המרירות באה מצד האהבה וחשק שיש בלבו להתקרב לה' [אחד], ע\"כ יתמרמר נפשו מריחוקו ופירוד<sup data-n=\"3027\">131</sup> נמצא [הרחמים האלה] כלול מחו\"ג יחד והן כמה גווני' דאודם ולובן מעורבים יחד, ואמנם מקור הממשיך רחמים האלה נק' בחי' מקיף [דמדת הרחמים] והו\"ע הארגמ\"ן שביריעות המשכן שכל המראות הן בבחי' המקיפי' דנוק'<sup data-n=\"3028\">132</sup> וד\"ל. וזהו ודלת ראשך כארגמ\"ן<sup data-n=\"3029\">133</sup> שהן בחי' גבורות ממותקות דרחמים שהגם שיש ברחמים התפעלות חמימות רשפי אש שיש במרירות וצער אבל הוא בא מחמת האהבה כנ\"ל. ואמנם בחי' התפעלות רשפי אש דבחי' רצוא הנ\"ל נק' גבורות בעצם כו' שזהו מראה אודם לבד והן בחי' שערות אדומות, ומראה [התכלת בחי' אשא תכלא הנ\"ל הוא הוא מראה<sup data-n=\"3030\">134</sup> שחור<sup data-n=\"3031\">135</sup> והן כמו בחי' שערות שחורות, אבל הארגמן הוא בחי'] הממוצע הכלי<sup data-n=\"3032\">136</sup> מכל הגוונים והוא מדת הת\"ת שנק' קו האמצעי<sup data-n=\"3033\">137</sup> כידוע שכלול מב'<sup data-n=\"3034\">138</sup> הגוונין<sup data-n=\"3035\">139</sup> בבחי' או\"פ. וכך הוא בבחי' אור המקיף ביריעות המשכן הנ\"ל שבמרא[ות] וגווני' דיריעות הכל בבחי' המקיף בהעלם שלמעלה מהגבלת האור בכלים כו' וד\"ל.\n<b>וענין</b> שש משזר הוא הפשתן הלבן, וידוע דמראה הלבן שם פשתן<sup data-n=\"3036\">141</sup> ה[וא] מורה על עצם אור<sup data-n=\"3037\">142</sup> החסד<sup data-n=\"3038\">140</sup> הפשוט בתכלית, וגם צמיחת הפשתן שעולה יחידי בקנה<sup data-n=\"3039\">143</sup> א'<sup data-n=\"3040\">144</sup> בד בבד, וע\"כ נק' ב\"ד לשון בדד<sup data-n=\"3041\">145</sup> כמ\"ש כתונת בד קדש ילבש<sup data-n=\"3042\">146</sup> כו' הנ\"ל<sup data-n=\"3043\">147</sup> מורה על היותו בבחי' עצם פשוט בלתי מורכב ומתחבר בדבר זולתו, כמ\"ש במ\"א בענין בגדי כה\"ג ביוהכ\"פ<sup data-n=\"3044\">148</sup> לפני ולפנים שהוא עובד בבגדי לבן דוקא [מ]טעמים אלה,",[["3021","125","<b>והחיות רצוא</b>: יחזקאל א, יד."],["3022","126","<b>העליונים שני</b>: אד: עליונות והוא ש(ה)נק'."],["3023","127","<b>הארגמן. . הת\"ת</b>: ראה זהר תרומה קלט, א ובהגהות מהרח\"ו שם."],["3024","128","<b>הרחמים. . התכללות מחו\"ג</b>: ראה גם לעיל פ' וארא פה, ד. וש\"נ."],["3025","129","<b>הרוממות</b>: אד: המרירות."],["3026","130","<b>ומאשר</b>: א: ומאחר. ד: הניח מקום פנוי."],["3027","131","<b>ופירוד</b>: א: ופרידתו כו'. ד: ופחדו(!) כו'."],["3028","132","<b>דנוק'</b>: שם: דוקא."],["3029","133","<b>ודלת ראשך כארגמ\"ן</b>: שה\"ש ז, ו."],["3030","134","<b>הוא הוא מראה</b>: א: ומראה."],["3031","135","<b>התכלת. . הוא מראה שחור</b>: ראה גם עקידה ר\"פ שלח שער עז (מז, ב) שהוא הממוצע בין לבן ושחור."],["3032","136","<b>הכלי</b>: אד: הכלול."],["3033","137","<b>הת\"ת שנק' קו האמצעי</b>: ראה השמטות לזח\"א רנז, א. שערי אורה — לר\"י גיקטלייא — ש\"ה ע' סג ואילך."],["3034","138","<b>הת\"ת. . שכלול מב' הקווין</b>: נסמן לעיל פ' משפטים רפו, ד הערה 16."],["3035","139","<b>הגוונין</b>: אד: הקוין."],["3036","141","<b>שם פשתן</b>: שם: שבפשתן."],["3037","142","<b>עצם אור</b>: א: ליתא."],["3038","140","<b>דמראה הלבן. . החסד</b>: ראה פרדס (שער הגוונים) ש\"י, פ\"א."],["3039","143","<b>הפשתן שעולה יחידי בקנה א'</b>: ראה רש\"י ותוס' זבחים יח, ב."],["3040","144","<b>יחידי בקנה א'</b>: א: בפ\"ע."],["3041","145","<b>ב\"ד לשון בדד</b>: א: לשון ב\"ד. ד: בד. ראה מאמרי אדה\"א דברים ח\"ד ע' א'רלב. עט\"ר ע' כט."],["3042","146","<b>כתונת בד קדש ילבש</b>: אחרי טז, ד."],["3043","147","<b>הנ\"ל</b>: אד: ליתא:"],["3044","148","<b>בגדי כה\"ג ביוהכ\"פ</b>: ראה מאמרי אדה\"א דברים ח\"ד ע' א'רלב ואילך. ח\"ג ע' תתעח. וש\"נ."]]],[2300550375,"שבעצם גידול הפשתן מורה על היחיד[ו]ת הפשוט וכמראה הלבן שבו הוא מורה עצמיות ופשוטה בלתי מורכבת כלל וע\"כ הלבן נעלה מכל הגוונין כנ\"ל. ולכך הכה\"ג מתלבש בבגדי פשתן הלבן דוקא להורות על יחידו ש\"ע שהוא בבחי' אחדות [ה]פשוט[ה] בתכלית, ובחי' עצם החסד שבעצמותו ית' שהוא כמו מראה הלבן העצמי ופשוט כמו שהוא בעצמות אור א\"ס ב\"ה בלתי מורכבת בחכמה וטעם כלל וכלל, ולמטה בכ[נ]\"י היינו בחי' האהבה הטבעיות המ[ו]שרשת בכל ואף<sup data-n=\"3045\">149</sup> בבחי' עצמותו ממש שהוא בחי' עצם פשוט בתכלית בלתי מורכבת באיזה טעם ודעת כלל וכלל. וראי' ממס\"נ עקה\"ש [שבכאו\"א למעלה מן הטעם ודעת רק מצד ההתקשרות בעצם פשוט בתכלית הפשיטו' ולזאת נק' גם זה בל' בד] שעולה יחידי ליכלל ביחידו ש\"ע. <span data-k=\"pg\">תמז</span> ּ וזהו מצד [ש]שורש הנשמה במהות עצמיות א\"ס ב\"ה שישראל עלה במח'<sup data-n=\"3046\">150</sup> הפשוטה ע\"כ עליות הנשמה כמו טבעיות [ועצמיי' ממש] להתמשך [וליכלל] ביחידו ש\"ע כו', והוא כמו צמיחת הפשתן שעולה יחידי, וגם על המראה לבן שהוא מראה עצמיות כנ\"ל זהו ג\"כ אהבה זו הטבעיות ועצמיות שלמעלה הרבה מרשפי אש התלהבות בג' אופנים [הנ\"ל] בבחי' רצו[א] ויראה ורחמנות כו' וד\"ל. וזהו ענין שש משזר שהי' ביריעות המשכן בבחי' מקיף דאור חסד<sup data-n=\"3047\">151</sup> הפשוט ועצמי הנ\"ל וע\"כ נק' שש ששש בגוונין, גם נק' משזר שהי' כולל כל הנ\"ל<sup data-n=\"3048\">152</sup> גוונין דתכלת וארגמן ותולעת שני ע\"י שזירה שהיו שזורין יחד עם השש ולזה נק' שש משזר בלי יפרד זה מזה, אדרבה כ\"א מתערב ומתדבק עם זולתו כו' וד\"ל<sup data-n=\"3049\">153</sup>. והענין הוא להיותו בבחי' מקור החסדי' [ה]עליונים הפשוטים שכולל הכל והולך ונמשך עם כל המדריגות [ו]כמ\"ש בזהר ע\"פ יומם יצוה ה' חסדו<sup data-n=\"3050\">154</sup> דאזיל עם כולהו יומין כו', וכמו\"כ בבחי' אהבה רבה הטבעיות ועצמיות הנ\"ל כוללת כל התפעלות והתלבשות<sup data-n=\"3051\">155</sup> ורחמים כנ\"ל ונמשכת אב\"א<sup data-n=\"3052\">156</sup> כו' וד\"ל. וזהו עיקר ההפרש שבין יריעות עזים<sup data-n=\"3053\">157</sup> המקיפים של או\"פ<sup data-n=\"3054\">158</sup> שבכלים, שבמקיף ה\"ז<sup data-n=\"3055\">159</sup> בחי' הנ\"ל כלולים בהתכללות זע\"ז [בלי יתפרדו זמ\"ז אדרבה כ\"א מתערב ומתדבק עם זולתו כו'] והיו לאחדים ממש ביריעות, משא\"כ בא\"פ בכלים נפרדים זמ\"ז כמו השולחן בצפון ומנורה בדרום<sup data-n=\"3056\">160</sup> (כמשי\"ת).\n<b>והנה</b> לנגד ד' בחי' הנ\"ל תכלת וארגמן ותולעת שני ושש משזר במקיפים דיריעות הי' באותו אופן ממש ד' בחי'",[["3045","149","<b>בכל ואף</b>: א: בכ\"א. ד: בכאו\"א."],["3046","150","<b>שישראל עלה במח'</b>: ראה ב\"ר פ\"א, ד. הנסמן לעיל פ' שמות לב, ב."],["3047","151","<b>שש. . חסד</b>: ראה הגהות מהרח\"ו לזהר פקודי רכח, א."],["3048","152","<b>הנ\"ל</b>: אד: הג'."],["3049","153","<b>בלי יפרד. . וד\"ל</b>: שם: ליתא."],["3050","154","<b>יומם יצוה ה' חסדו</b>: תהלים מב, ט. ראה מאמרי אדה\"א דברים ח\"ג ע' א'לה. וש\"נ."],["3051","155","<b>והתלבשות</b>: אד: (ו)התלהבות."],["3052","156","<b>אב\"א</b>: שם: עם כ\"א."],["3053","157","<b>עזים</b>: שם: ליתא."],["3054","158","<b>של או\"פ</b>: שם: לאו\"פ."],["3055","159","<b>ה\"ז</b>: שם: הד'."],["3056","160","<b>השולחן בצפון ומנורה בדרום</b>: פקודי מ, כב. כד. יומא כא, ב."]]],[2300550394,"כלים שבמשכן, והן הארון ומנורה ושולחן ומזה\"פ כו', (מנורה ושולחן צפון ודרום ב' קוין דחו\"ג<sup data-n=\"3057\">161</sup> ומזבח הפנימי בחי' ת\"ת<sup data-n=\"3058\">162</sup> ממוצע ב[ין] שולחן ומנורה<sup data-n=\"3059\">163</sup> והארון בבחי' כתר<sup data-n=\"3060\">164</sup> כמשי\"ת). והנה השולחן הוא בצפון שהוא בחי' קו השמאל שהוא בבחי' הגבו' ע\"כ [נ]תפרש בכתוב כי<sup data-n=\"3061\">165</sup> כל כלים [ש]הי' [לו] הכל של זהב דוקא קערותיו וכפותיו כנ\"ל, כי מצפון זהב יאתה<sup data-n=\"3062\">166</sup> כו', והוא לנגד בחי' התכלת שביריעות שהוא בבחי' המל' שעיקר בנין המל' [מ]בחי' הגבורו'<sup data-n=\"3063\">167</sup> העליונ[ות] רק שהוא בבחי' מקיף בתכלת דיריעות כו' ובשולחן בא זה האור של הגבורות [ב]בחי' אור הפנימי בכלי' בבחי' השפעה ממש כנ\"ל. וביאור הדברים הנה ידוע דגם שהשולחן [הוא] בצפון שהוא בחי' קו השמאל בחי' הדין והצמצום, מ\"מ כל עיקר ומקור כל השפעה אלקי' מאצי' לבי\"ע הכל בא מן השולחן שבצפון דוקא כמ\"ש בזהר ע\"פ כי השולחן המלך<sup data-n=\"3064\">168</sup> תמיד הוא אוכל שלמעלה הוא בחי' השולחן שלפני ה' משכא<sup data-n=\"3065\">169</sup> עילאה שניתן בו וע\"י כל שפע אור אלקי לכל<sup data-n=\"3066\">170</sup> העולמות, וכידוע שלחם הפנים שבשולחן כו'<sup data-n=\"3067\">172</sup> הי' נמשך כל אור ושפע ומזון [ל]כל העולמות<sup data-n=\"3068\">171</sup> [ודוקא] מפני שהוא בבחי' הגבו' וחסדים<sup data-n=\"3069\">173</sup> העליונ[ות], שבגבורות יש כח וחיות גדול להשפיע כל שפע בהתחלקות לאין שיעור כידוע בענין גבורות גשמים שיורדים בגבורה<sup data-n=\"3070\">174</sup>. וזהו [ענין הברכה] דאתה גבור לעולם אדנ\"י [ו]ע\"כ מכלכל חיים בחסד ומחי' מתים כו', ו[ל]זה הטעם הי[ו] כלי השולחן כולם של זהב [דוקא] לפי שמצפון בא שורש השפע ומצפון זהב יאתה כו' וד\"ל.\n[ה] <b>והנה</b> מבואר למעלה בבחי' מקיף דתכלת [ש]הוא היראה שלמעלה מהכיל בכלי הלב והמוח מצד עוצם הרוממות וההתנשאות דמדת מל' שנק' אשא <span data-k=\"pg\">896</span> ּ תכלא כו', שזהו מבחי' גבורות עליונות שבבחי' מקיף דמל' שלא יוכלו המקבלים לקבל בתוכם, וזהו שעיקר ענין<sup data-n=\"3071\">175</sup> בנין המל' מה\"ג<sup data-n=\"3072\">176</sup>, אמנם בזה ד[ו]קא נמשך מקור לחיות העולמות כמ\"ש מלכותך מל' כל עולמים דמשמע שבמדת המלוכה וההתנשאו' שהוא עיקר סיבת מקור חיותן [ושפעם] כו', (ולכאורה איך [י]בא אור המקיף כזה שמרומם<sup data-n=\"3073\">177</sup> ביותר להיות מקור לחיות העולמות, הענין הוא כמ\"ש יראת ה' לחיים<sup data-n=\"3074\">178</sup> שהיראה האלקי' שנמשכת ממקיף דירא' הרוממות הנ\"ל בגילוי אור בכלי השג[ת] המלאכים",[["3057","161","<b>צפון ודרום ב' קוין דחו\"ג</b>: ראה זהר בראשית כט, ב ובאור החמה שם. מאמרי אדה\"א דברים ח\"ד ע' א'תמא. וש\"נ. נ\"ך ע' קכב. לקמן פ' ויקהל שפו, ד."],["3058","162","<b>ומזבח הפנימי בחי' ת\"ת</b>: ראה ע\"ח (שער ציור עולמות) שמ\"ג, פ\"א. לקמן פ' ויקהל שצ, ג."],["3059","163","<b>ומזבח הפנימי. . ב[ין] שולחן ומנורה</b>: יומא לג, ב."],["3060","164","<b>והארון בבחי' </b>[אד: בחי']<b> כתר</b>: ראה גם לקמן פ' ויקהל תיב, ב. תכז א. תמ, ג. פקודי תנט, ג. מאמרי אדה\"ז תקס\"ד כאן (בהביאור ע' עד). מאמרי אדה\"א שמות ח\"ב ע' תט."],["3061","165","<b>כי</b>: אד: ליתא."],["3062","166","<b>מצפון זהב יאתה</b>: איוב לז, כב."],["3063","167","<b>בנין המל' [מ]בחי' הגבורו'</b>: ראה גם לעיל פ' בשלח רמד, א. וש\"נ."],["3064","168","<b>כי השולחן </b>[אד: על שולחן]<b> המלך</b>: שמו\"ב ט, יג. ראה זהר תרומה קנג, א. קנו, ב. קנד, רע\"ב וברמ\"ז שם. לקמן פ' ויקהל שפז, א. מאמרי אדה\"ז תקס\"ד ע' סט. מאמרי אדה\"א שמות ח\"ב ע' תרעח. אוה\"ת כאן ע' ב'קפח וע' ב'רי."],["3065","169","<b>משכא</b>: אד: מלכא."],["3066","170","<b>לכל</b>: א: לג'."],["3067","172","<b>כו'</b>: אד: בו."],["3068","171","<b>שלחם הפנים. . ומזון [ל]כל העולמות</b>: ראה זהר תרומה קנה, א."],["3069","173","<b>וחסדים</b>: שם: ליתא."],["3070","174","<b>גבורות גשמים שיורדים בגבורה</b>: תענית ב, א. ראה גם סידור שחרית סד, א. מאמרי אדה\"א דברים ח\"ד ע' א'תכח ואילך."],["3071","175","<b>ענין</b>: אד: ליתא."],["3072","176","<b>מה\"ג</b>: שם: מהגבורו'."],["3073","177","<b>איך יבא. . שמרומם</b>: תוקן ע\"פ אד: ובתו\"ח כאן: עיקר באה. . שמרחם."],["3074","178","<b>יראת ה' לחיים</b>: משלי יט, כג. ראה סידור שער הק\"ש פב, סע\"ג בשם הה\"מ. לעיל פ' בא ק, א. וש\"נ."]]],[2300550411,"[ו]<b>נבראים</b> בזה המה חיים וקיימים ממש וכידוע הטעם שהמלאכים יותר נצחי' מן הנשמות שבגופי' מפני שיש במלאכים מבחי' היראה אלקי' מקרוב יותר, ובמדת היראה יש כח להחיות ולקיים הנברא כי זה נמשך במדת<sup data-n=\"3075\">179</sup> המל' שאימתו עליהם בבחי' מקיף והוא הבא בגילוי אפס קצהו להחיותם בקיום מדתו<sup data-n=\"3076\">180</sup> מאין ליש. וזהו ג\"כ ענין השולחן שבצפון שכל הכלים שלו של זהב דוקא דמה שבתכלת דיריעות הוא בבחי' מקיף כמו רקיע פרושה כמו ועל ראשי החיות רקיע כו', הרי בכלי השולחן הוא בא בבחי' או\"פ בכלי ממש להחיות כל העולמות באמרו שפע<sup data-n=\"3077\">181</sup> רב ממש וד\"ל.\n<b>והנה</b> המנורה הי' בדרום שהוא מבחי' קו הימין דחסד, ואמנם כמו ששולחן בצפון שם מקור [ה]חסד [ו]הברכה והשפעה כך להיפוך בקו הימין דמנורה כלול מבחי' הגבורות דוקא, והוא מה שעיקר ענין נרות המנורה הי' להדליק ברשפי אש שלהבת ענין<sup data-n=\"3078\">182</sup> שמן זית ופתיל[ה] והיתה כול[ה] של זהב דייקא כמ\"ש בפרטי מעשה המנורה וכל כליה הכל של זהב דוקא כו'. וידוע דנרות המנורה הן כללות נש\"י<sup data-n=\"3079\">183</sup>, וכתיב ובהעלות אהרן [את] הנרות<sup data-n=\"3080\">184</sup> כו', שזהו ל[ה]עלות נש\"י להאירם ולהדליקם ברשפי אש שלהבת י\"ה שבאור החכ' שמאיר בשמן ופתילו', וכמו כי אתה תאיר נרי<sup data-n=\"3081\">185</sup> בכל נש\"י<sup data-n=\"3082\">186</sup> בפרט, וכך הוא בכלל בהדלקת נרות המנורה להאיר לכלל נש\"י ע\"י אהרן ובניו ש[י]הי' בכ[נ]\"י אהבה בהתלהבות רשפי אש דוקא ובגילוי אור דחכ'<sup data-n=\"3083\">187</sup> שהוא השמן<sup data-n=\"3084\">188</sup> הדולק וכמ\"ש במ\"א. והוא ג\"כ ענין נר מצוה ותורה אור<sup data-n=\"3085\">189</sup> שעי\"ז דוקא יאיר גילוי אוא\"ס ב\"ה [בנש\"י] כידוע דאור החכ' שבתורה הוא בבחי' [ה]העלם, וזהו בחי' השמן, ובאה מן ההעלם לגילוי אור בכלי שהוא המצוה, וזהו שנק' נר מצוה שהוא הפתילה שהוא [ה]כלי לאור כן המצו[ת] הן כלים מכלים שונים לאור האלקי דתורה אור דחכ' עילאה שמאיר בהם בגילוי ע\"י הדלקה באש. והוא בחי' התלהבות דרשפי אש שלהבת י\"ה דכנס\"י באה\"ר שאז יאיר אור דתורה במצות שעושין להיות מזה דוקא בחי' גילוי אור א\"ס ב\"ה באור נשמתו ג\"כ מן ההעלם לגילוי, אבל בלא תו\"מ שהוא בלא אור וכלי אין התלהבות אה\"ר דנש\"י מועיל להם<sup data-n=\"3086\">190</sup> במקור חוצבם להתמשך<sup data-n=\"3087\">191</sup> משם גילוי אור, וכידוע שס\"ר נש\"י קשורות בס\"ר אותיות התו'<sup data-n=\"3088\">192</sup> דג' קשרים",[["3075","179","<b>במדת</b>: א: מבחי'. ד: ממדת."],["3076","180","<b>מדתו</b>: שם: תמידי."],["3077","181","<b>באמרו שפע</b>: שם: באור ושפע."],["3078","182","<b>ענין</b>: אד: ע\"י."],["3079","183","<b>דנרות המנורה. . נש\"י</b>: ראה לעיל פ' יתרו רסט, ב הערה 10."],["3080","184","<b>ובהעלות אהרן [את] הנרות</b>: תצוה ל, ח. ראה גם לקמן פ' תצוה שמו, א."],["3081","185","<b>כי אתה תאיר נרי</b>: תהלים יח, כט."],["3082","186","<b>נש\"י</b>: אד: נשמה."],["3083","187","<b>דחכ'</b>: א: דשמן דחכ'."],["3084","188","<b>דחכ' שהוא השמן</b>: ראה זהר יתרו פז, ב. הנסמן במאמרי אדה\"א קונטרסים ע' תקמה."],["3085","189","<b>נר מצוה ותורה אור</b>: משלי ו, כג."],["3086","190","<b>להם</b>: אד: להעלותם."],["3087","191","<b>להתמשך</b>: שם: ולהמשיך."],["3088","192","<b>שס\"ר נש\"י. . אותיות התו'</b>: ראה גם של\"ה מס' פסחים מצה עשירה קסג, ב. קסה, ב. לעיל פ' שמות ב, ד. וש\"נ."]]],[2300550428,"הן<sup data-n=\"3089\">193</sup> ישראל מתקשראן באורייתא ואוריי' בקוב\"ה, וע\"כ ממילא יבא גילוי אוא\"ס בנש\"י ע\"י הדלקת אורות דתורה במצו[ת] שהי' בהדלקת נרות המנורה בשמן ופתילה כנ\"ל. וגם נרות המנורה עצמה הם <span data-k=\"pg\">תמח</span> ּ כלל נש\"י כנ\"ל, והשמן הוא השרש [ש]להן בחכ\"ע והפתילות הוא נשמות שבגוף<sup data-n=\"3090\">194</sup> כידוע וד\"ל.\n<b>והנה</b> המדליק הנרות צריך שימשיך [מ]מקור הגבורות<sup data-n=\"3091\">195</sup> דחכ' שהוא מבחי' ההעלם והצמצום שיבא לגילוי כו', והוא מבחי' מקור הגבורות עליונות שבבחי' מקיף דוקא, והוא ענין ת\"ש<sup data-n=\"3092\">196</sup> שביריעות שמשם יאיר אור דחכמה<sup data-n=\"3093\">197</sup> מן ההעלם דמקיף להיות בגילוי אור בנרות המנורה, והוא בהדלקת רשפי אש אה\"ר בהתלהבו' דוקא כנ\"ל וד\"ל (וזהו שהמנורה הי' של זהב כמעלת הזהב על הכסף שהוא [מ]בחי' הגבורות שהוא בחי' ההעלם דחכ\"ע שבא בגילוי, וכמ\"ש פיה פתחה בחכ'<sup data-n=\"3094\">198</sup> בגילוי ותורת חסד כנ\"ל<sup data-n=\"3095\">199</sup>, והוא ענין התולעת שני כמו שהתולע אין כחו אלא בפה<sup data-n=\"3096\">200</sup> להרקיב ארז קשה, כך ע\"י הדיבור ודבור דתורה<sup data-n=\"3097\">201</sup> דוקא יורקב יניקת החיצוני', וזהו אל תירא[י] תולעת יעקב<sup data-n=\"3098\">202</sup> כמ\"ש במ\"א בענין תולעת שני שבפרה אדומה) (וזהו כחוט השני שפתותיך<sup data-n=\"3099\">203</sup> בדיבור בדברי תורה, אך זהו בבחי' מקיף, וע\"י התלהבות אה\"ר כמו בנרות המנורה באה לגילוי כנ\"ל<sup data-n=\"3100\">204</sup> ). ונמצא דמה שהי' ביריעות בבחי' מקיף והוא תולעת שני הי' זה בגילוי המנורה בהתלהבות רשפי אש דאה\"ר כו' וד\"ל.\n<b>ומעתה</b> יש להבין ענין הארון שהי' [עומד] בהיכל ק\"ק, והוא בבחי' אור הכת\"ר ע\"כ הפרוכת הסתירה וכמ\"ש והבדילה הפרוכת<sup data-n=\"3101\">205</sup> כו' שנק' ק\"ק והמנורה הי[א] בבחי' קו הימין והשולחן [הוא] בבחי' קו השמאל, ומזבח הפנימי שבין המנורה והשולחן הוא [בחי'] קו האמצעי והוא שעולה עד הכתר<sup data-n=\"3102\">206</sup> וכללות [ענין] ג' אלה הקוין הן חג\"ת כו' (רק שמצד התכללות דבר בהיפוכו דוקא<sup data-n=\"3103\">207</sup> מאיר אור הגבורות בכלי החסד שהוא במנורה שבדרום כו', ואור החסד מאיר בכלי הגבו' שהוא השולחן שבצפון וכמ\"ש במ\"א עד\"ז בב\"פ דק\"ש<sup data-n=\"3104\">208</sup> בשם מ\"ב ושם ע\"ב וד\"ל). והנה הארון הוא לנגד בחי' הבד שביריעות והוא השש שבפשתן הלבן שמורה על יחידו ש\"ע, והוא בחי' אה\"ר [העצמי' המסותרת] שהוא ב[חי'] פנימי' הכת\"ר. וכך הוא ענין הארון שבו היו הלוחות כתובים יו\"ד הדברות שהוא בבחי' פנימי' הכת\"ר והוא בחי' אנכי כו' וכדומה<sup data-n=\"3105\">209</sup> שזהו [מ]בחי' פנימי'",[["3089","193","<b>דג' קשרים הן</b>: ראה זהר אחרי עג, א. לעיל פ' שמות ב, ד. וש\"נ."],["3090","194","<b>והפתילות הוא נשמות שבגוף</b>: ראה תו\"א מקץ לג, ג."],["3091","195","<b>הגבורות</b>: אד: האור."],["3092","196","<b>ת\"ש</b>: שם: תולעת שני."],["3093","197","<b>דחכמה</b>: שם: ליתא."],["3094","198","<b>פיה פתחה בחכ'</b>: משלי לא, כו."],["3095","199","<b>כנ\"ל</b>: אד: כו'."],["3096","200","<b>שהתולע אין כחו אלא בפה</b>: ראה תנחומא בשלח ט. זהר וישלח קעח, א. תרומה קלט, א. מדרש שוחר טוב כב, ז."],["3097","201","<b>ודבור דתורה</b>: אד: בדברי תורה."],["3098","202","<b>אל תירא[י] תולעת יעקב</b>: ישעי' מא, יד. ראה מאמרי אדה\"ז תקס\"ה ח\"ב ע' תרעה. ע' תרפח. לקו\"ת חוקת נז, א-ב. נט, א-ב."],["3099","203","<b>כחוט השני שפתותיך</b>: שה\"ש ד, ג."],["3100","204","<b>כנ\"ל</b>: א: ליתא. ד: כו'."],["3101","205","<b>והבדילה הפרוכת</b>: תרומה כו, לג."],["3102","206","<b>קו האמצעי. . הכתר</b>: ראה שערי אורה — לר\"י גיקטלייא — שער ה (ע' סג). מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תרמה בשם הע\"ח."],["3103","207","<b>בהיפוכו דוקא</b>: א: והיפוכו."],["3104","208","<b>במ\"א עד\"ז בב\"פ דק\"ש</b>: ראה מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תשח ובהנסמן במ\"מ לשם. תו\"ח בראשית מ, ד ובהערה 51."],["3105","209","<b>וכדומה</b>: אד: וכידוע."]]],[2300550444,"ועצמו' אוא\"ס ב\"ה ממש שנק' יחיד שהוא ושמו פשוט בתכלית רק שבא האור ומתלבש בהעלם בבחי' מקיף בבגדי בד דוקא, בהיות הכה\"ג בהיכל ק\"ק לעבוד עבוד[ת ה]קטרת, וע\"כ הי' עבודתו שם בבגדי לבן דוקא כנ\"ל אבל בלוחות שבארון הרי הי' גילוי אור זה הנעלם במהות ועצמיות העליון<sup data-n=\"3106\">210</sup> ביו\"ד הדברות הכתובים באצבע האלקי' כו' וד\"ל. ונמצא שמה שהי' ביריעות בבחי' הבד דפשתן בהעלם ומקיף בא האור בכלי הארון בגילוי כו', ועכ\"ז מצד שעצם האור הגדול הזה בא ממהו\"ע דלית מח' תב\"כ, ע\"כ גם בהיות[ו] בא בבחי' כלי כמו הארון והלוחות הי' בבחי' ההסתר, והוא ע\"י הפרוכת שהי' מסתירו. אך בוקע האור דכתר דרך מסך דפרוכת לג' הקוין דמנורה ושלחן ומזה\"פ שהוא בבחי' הארה דבחי'<sup data-n=\"3107\">211</sup> העצמית הנ\"ל שהוא<sup data-n=\"3108\">212</sup> בפנימי' הכת\"ר כמו הארון שבעצמות א\"ס ב\"ה הוא ההארה<sup data-n=\"3109\">213</sup> העצמית, ונק' אהבה מסותרת ופשוטה בתכלית למעלה מהחכ' והוא לובן העליון דב\"ד שהוא הפשתן שעולה יחידי שהוא בחי' יחיד\"ה דכנס\"י, הנה במנורה בא אה\"ר עצמיות <span data-k=\"pg\">898</span> ּ או<sup data-n=\"3110\">214</sup> לגילוי אור ע\"פ שכל וחכמה דשמן ובהתלהבות רשפי אש שהוא ממש אותה האה\"ר העצמית שבפנימיות עצמיות א\"ס שבלוחות וארון שלפני הפרוכת כו', אך ע\"י שמן ואור מתגלה לחוץ בגילוי אור, וכן עד\"ז השולחן בצפון בקו השמאל בהמשכת אור ושפע כו' הכל בא מן הארון כו' כידוע שפנימי' הכתר נחלק לג' קוין<sup data-n=\"3111\">215</sup> וכן ברחמים דת\"ת שהוא הארגמן [כו', וגם במזבח החיצון שהוא בחי' המל' גם שם יאיר אור א\"ס שבארון כי בריח התיכון שנק' קו האמצעי דת\"י<sup data-n=\"3112\">216</sup> מבריח מן הקצה אל הקצה האחרון] דמל' דנעוץ כו' וד\"ל. וזהו פי' טובה תוכחת מגולה שהוא חג\"ת [ד]ג' [קוין] הנ\"ל שבא בגילוי מאהמ\"ס<sup data-n=\"3113\">217</sup> שהי' בהסתר ע\"י הפרוכת תחלה כנ\"ל וד\"ל.\n<b>והנה</b> [ענין] מזבח הפנימי שהוא לנגד הארגמן שביריעות שהוא בחי' הת\"ת שכולל כל הגווני' כנ\"ל הרי מה שהי' ביריעות בבחי' מקיף [דרחמים] שנק' מקור הר\"ר בא בגילוי אור בקטורת שבמזבח הפנימי שכלול מכל המדריגות דחו\"ג בגילוי אור כי בריח העולה מהקטורת הי' [ה]מתקת כל הדינין [עד] שנהפך מארור לברוך בי\"א סממני הקטורת שהן נגד י\"א ארורים<sup data-n=\"3114\">218</sup> דק\"נ, והוא מצד בחי' הס\"ר<sup data-n=\"3115\">219</sup> העליוני' שבאו בגילוי<sup data-n=\"3116\">220</sup> כמו סליחת העו[נו'] לבע\"ת שנהפך ממות לחיים כמ\"ש במ\"א, ומזה\"פ הוא פנימי' הלב שיש בו גם מבחי'<sup data-n=\"3117\">221</sup> אש דמזבח",[["3106","210","<b>העליון</b>: שם: ליתא."],["3107","211","<b>שהוא בבחי' הארה דבחי'</b>: שם: והוא בחי' אה\"ר."],["3108","212","<b>שהוא</b>: א: ניתוסף: בבחי' פנימי' שהוא. וראה גם לעיל שח, סע\"א שו\"ה הארון."],["3109","213","<b>הוא ההארה</b>: אד: היא האהבה."],["3110","214","<b>עצמיות או</b>: א: העצמי' זה. ד: זו עצמה."],["3111","215","<b>שפנימי' הכתר נחלק לג' קוין</b>: ראה תו\"ח לך פ, ד ובהערה 48."],["3112","216","<b>דת\"י</b>: א: דתורה."],["3113","217","<b>טובה תוכחת מגולה. . מאהמ\"ס </b>[אד: מאהבה מסותרת]: משלי כז, ה."],["3114","218","<b>בי\"א סממני הקטורת. . י\"א ארורים</b>: ראה ע\"ח (שער המלכים) שי\"א, פ\"י. הנסמן לעיל פ' שמות ח, ג."],["3115","219","<b>הס\"ר</b>: אד: הר\"ר."],["3116","220","<b>בגילוי</b>: א: ניתוסף: אור."],["3117","221","<b>מבחי'</b>: אד: מגחלי."]]],[2300550459,"החיצון (שהוא יחוד ת\"ת ומל'), וע\"כ הי' המזבח מכוון נגד הארון דוקא, לפי שבריח התיכון שהוא קו האמצעי דת\"ת שהוא הרחמים עליונים שבפנימי' הכתר ונק' נחלת יעקב נחלה בלי מצרים<sup data-n=\"3118\">222</sup> כידוע וד\"ל. והנה כל הג' קוין דמנורה ושולחן ומזה\"פ הנ\"ל בבחי' ציור דימין ושמאל ואמצע כו', אע\"פ שאין [ל]הם ערך כלל לגבי בחי' עצמיות אוא\"ס ב\"ה [הפשוט] בתכלית האחדות [ה]פשוט[ה] שבלוחות וארון, ואע\"פ שצמצם שכינתו בין ב' בדי הארון ובין הכרובים שעל הכפורת כו', ה\"ז בבחי' ההסתר והעלם ע\"י הפרוכת שנק' פרסא כו', עכ\"ז הרי האור בוקע ומאיר בג' קוין דמנורה ושולחן ומזה\"פ שנק' חג\"ת ע\"י ג' דברים היינו לחם הפנים שעל השולחן ושמן ואור שבמנורה וקטורת שבמזה\"פ כו', והקרבנות שבמזבח החיצון שהוא להעלות מ\"ן כו', ו[ל]ברר בירורי' דרפ\"ח כו', אע\"פ שזה[ו] סוף דבר<sup data-n=\"3119\">223</sup> כל המדריגות, הנה ידוע דנעוץ תחילתן בסופן<sup data-n=\"3120\">224</sup> דוקא וסוב\"ת וכמ\"ש סוף דבר כו' כי זה כל האדם<sup data-n=\"3121\">225</sup> [פי' בחי' הבירורי' דעה\"ד טו\"ר שבקרבנות שנק' סוף דבר כי זה כל האדם] בבחי' פנימי' המוחין דח\"ע בארון ולוחות, וע\"כ סדר היחודים במשכן הי' בתחלה במזבח החיצון בחצר אהל מועד להקריב קרבנות מן התמיד של שחר כו', ואח\"כ עבודת הקטורת במזבח הפנימי שהוא בחי' הפנימי' דקרבנות שהוא עולה עד פנימי' הכתר שבארון וד\"ל, וזהו שע\"י הקרבנות במזבח החיצון דוקא [בתמיד] של שחר וערב הי' גילוי אוא\"ס דשכינה בין בדי הארון כו' (וכך הוא עכשיו בתפלה שבמקום קרבן שעי\"ז ישכון גילוי אוא\"ס ב\"ה בד\"א של הלכה שבמקום היכל ק\"ק<sup data-n=\"3122\">226</sup> כו').\n[ו] <b>והנה</b> כתיב עת לכל חפץ<sup data-n=\"3123\">227</sup> תחת השמים, ויש להבין מ\"ש תחת השמים דוקא יש עת לכל חפץ כו', פי' הפשוט דעת לכל חפץ הוא מה שאנו רואים שינוי העתים בזמנים דטו\"ר בימים ושנים כו' וגם בעתים ורגעים וכמ\"ש בזהר דאית יומין ידועים לטב<sup data-n=\"3124\">228</sup> כו', וכמו למה אירא בימי רע<sup data-n=\"3125\">229</sup> ביומין דדינין שלטין כו', וכן בשעות ורגעים כמ\"ש לרגעים תבחננו<sup data-n=\"3126\">230</sup> כו' וכתיב [ו]אל זועם בכל יום<sup data-n=\"3127\">231</sup> וכמה זעמו רגע כמ\"ש כי רגע באפו<sup data-n=\"3128\">232</sup> חיים ברצונו. ויובן זה השינוי בהילוך המזלות כמ\"ש משנה עיתים ומחליף את הזמנים<sup data-n=\"3129\">233</sup> שכל אלו השינוים <span data-k=\"pg\">תמט</span> ּ בחסד ודין הכל הוא בשפע הרוחני' דשמים ומזלות שמשפיעים בארץ וכמ\"ש ומסדר [את] הכוכבים<sup data-n=\"3130\">234</sup> כו', וכמ\"ש אני אענה את",[["3118","222","<b>נחלת יעקב נחלה בלי מצרים</b>: ישעי' נח, יד. שבת קיח, סע\"א. ראה מאמרי אדה\"א במדבר ח\"ג ע' א'קח ואילך."],["3119","223","<b>דבר</b>: אד: ליתא."],["3120","224","<b>דנעוץ תחלתן בסופן</b>: ראה ס\"י פ\"א, מ\"ז."],["3121","225","<b>סוף דבר. . האדם</b>: קהלת יב, יג."],["3122","226","<b>בד\"א של הלכה. . ק\"ק</b>: ראה ברכות ח, א. תניא פנ\"ג. הנסמן לעיל פ' בא צד, א."],["3123","227","<b>עת לכל חפץ</b>: קהלת ג, א [ושם: ועת (וכ\"ה בסמוך בפנים על יד הערה 240) — ראה מאמרי אדה\"א דברים ח\"א ע' צז. שמות ח\"ב ע' תרעט]."],["3124","228","<b>דאית יומין ידועים </b>[אד: ידיען]<b> לטב</b>: ראה זהר מקץ רד, א. ביאוה\"ז שם לג, ג."],["3125","229","<b>למה אירא בימי רע</b>: תהלים מט, ו."],["3126","230","<b>לרגעים תבחננו</b>: איוב ז, יח."],["3127","231","<b>ואל זועם בכל יום</b>: תהלים ז, יב. ברכות ז, א."],["3128","232","<b>כי רגע באפו</b>: תהלים ל, ו."],["3129","233","<b>משנה עיתים ומחליף את הזמנים</b>: ברכת ק\"ש (של ערבית)."],["3130","234","<b>ומסדר [את] הכוכבים</b>: ברכת ק\"ש שם."]]],[2300550474,"השמים<sup data-n=\"3131\">235</sup> והם יענו את הארץ. ונמצא כדור הארץ<sup data-n=\"3132\">236</sup> מקבל כל שפע דחסד או דין כנ\"ל בכל עיתים בגילוי התחלקו' במקום וזמן בכל אלקו' בפרטו'<sup data-n=\"3133\">237</sup> כמו חלק[ה] א[חת] תמטר<sup data-n=\"3134\">238</sup> כנ\"ל, אבל בשמים הרוחני' כולל כל התחלקות השפע הבא[ה] למטה כא'<sup data-n=\"3135\">239</sup> בלי ניכר שם שום התחלקות כלל כו'. וזה[ו] פי' לכל זמן ועת לכל חפץ<sup data-n=\"3136\">240</sup> ורצון בין לחסד בין לדין, בא השפע בהתחלקות כלי מיוחד שהוא הזמן ו[ה]עת לטוב כמו בעת רצון עניתיך<sup data-n=\"3137\">241</sup> כו' וכה\"ג, או זמן ועת לחפץ היפוכ[ו] שהוא מדה\"ד, והכל הוא תחת השמים דוקא, אבל בשמים ממעל אין עת מיוחד לכל חפץ ורצון, אלא כולם כלולים כא' מצד שהשמים הוא בחי' העיגולים המקיפים שאין שם התחלקות כלי כו'<sup data-n=\"3138\">242</sup> כל עת בפ\"ע כו' וד\"ל.\n<b>והדוגמא</b> מכ\"ז יובן ג\"כ בדרך אחר באדם שנק' כלל ופרט שבבחי' הכלל כל התחלקות שבא אח\"כ בדרך פרט נזכרים<sup data-n=\"3139\">243</sup> וכלולים כא', ובפרט יוצא לגילוי בהתחלקות כ\"א בפ\"ע דוקא. וכמו\"כ בתורה<sup data-n=\"3140\">244</sup> התורה נדרשת בדרך כלל ובדרך פרט והעיקר הוא מה שבא בגילוי בדרך פרט שנק' שייפין<sup data-n=\"3141\">245</sup> ואברים כו' ונק' תור\"ת האד\"ם<sup data-n=\"3142\">246</sup>. והענין הוא גם באד\"ם שעיקר האדם הוא מה שבא בו בדרך פרט דוקא והם המדות שבלב, ואע\"פ שהמוחין שבראש הוא בא<sup data-n=\"3143\">247</sup> בבחי' הכלל שכוללים מכל<sup data-n=\"3144\">248</sup> חיות האברים אבל הוא בהעלם ובכח ולא בגילוי והעיקר הוא בחי' הגילוי אור הבא בגילוי<sup data-n=\"3145\">249</sup> בכלי מיוחד בפ\"ע בהתחלקות גמור. וזה[ו] עיקר האד\"ם דוקא<sup data-n=\"3146\">250</sup> שהן המדות שבלב שזה[ו] בחי' הפרט שבו, אע\"פ שהפרט הזה מקבל מן המוחין שהוא הכלל כי אין פרט אלא הבא מן הכלל, וכמו [ש]מבואר למעלה בענין ארץ שמקבל מן השמים שהארץ עיקר (שהוא בבחי' יושר ופרצוף אדם כמו עיני הארץ<sup data-n=\"3147\">252</sup> טבור הארץ<sup data-n=\"3148\">253</sup> כו', משא\"כ [ה]שמים בחי' עיגולים<sup data-n=\"3149\">251</sup> הכל [שוה] כא', ובארץ כל מקום מיוחד בפ\"ע כו'). וגם הרי עיקר בחי' פני אדם הוא המוחי' והפני', מ\"מ עיקר מהות האדם הוא הבא מן המוחין הכללי לידי פרט כמו בהתפעלו' המדות שבלב שכ\"א יש לו כלי מיוחד בפ\"ע כו', ולא יוכללו דבר [ו]היפוכו כו'<sup data-n=\"3150\">254</sup>, משא\"כ במוחין שיוכלל הכל כא' גם דבר [ו]היפוכו כא' כו'.\n<b>ויובן</b> זה במה שאנו רואים בהתפעלות השכל בהתבוננו' שבמוח כאשר עדיין לא נכנס ונגע בלבו ההתפעלות",[["3131","235","<b>אני אענה את השמים</b>: הושע ב, כג [בהוספת תיבת אני — ראה לעיל פ' וארא ס, ב. וש\"נ]."],["3132","236","<b>כדור הארץ</b>: נסמן לעיל פ' בשלח רמ, א."],["3133","237","<b>אלקו' בפרטו'</b>: אד: אקלים בפרט."],["3134","238","<b>חלק[ה] א[חת] תמטר</b>: עמוס ד, ז."],["3135","239","<b>כא'</b>: אד: בבת א'."],["3136","240","<b>לכל זמן ועת לכל חפץ</b>: קהלת ג, א."],["3137","241","<b>בעת רצון עניתיך</b>: ישעי' מט, ח."],["3138","242","<b>כלי כו'</b>: אד: כלים להיות."],["3139","243","<b>נזכרים</b>: שם: נסקרי'."],["3140","244","<b>בתורה</b>: שם: ליתא."],["3141","245","<b>התורה. . שייפין</b>: זהר תולדות קלד, ב."],["3142","246","<b>תור\"ת האד\"ם</b>: שמו\"ב ז, יט. ראה זהר (רע\"מ) משפטים קיז, ב. צו כט, ב."],["3143","247","<b>בא</b>: אד: ליתא."],["3144","248","<b>שכוללים מכל</b>: א: שכלולים מכל. ד: שכוללים כל."],["3145","249","<b>בגילוי</b>: שם: ליתא."],["3146","250","<b>דוקא</b>: א: ליתא."],["3147","252","<b>עיני </b>[אד: עין]<b> הארץ</b>: בא י, ה."],["3148","253","<b>טבור הארץ</b>: ס' שופטים ט, לז."],["3149","251","<b>שהארץ. . יושר. . [ה]שמים בחי' עיגולים</b>: ראה ע\"ח (הקדמה לשער ציור אבי\"ע) שמ\"ג בהקדמה. מאמרי אדה\"ז תקס\"ב ח\"א ע' קצח ואילך. ח\"ב ע' תלט. תקס\"ה ח\"א ע' רלב. דרך מצותיך קסב, ב."],["3150","254","<b>כו'</b>: אד: כלל."]]],[2300550489,"בלבו רק ההתפעלות הוא במוח לבדו, יוכל להיות כמה מיני התפעלו' [שוני' הפכי'] ביחד בתנועה וסקירה א' בלי התחלקות ופירוד ביניהם כלל כמו התפעלות החדוה עם התפעלו' המרירות מהתבוננו' א', וכמו בענין מו\"מ שבעומק מחשבתו יתפעל מן הטו\"ר בסקירה א' כו'. אבל מיד שנגע ההתפעלו' בלבו מתחלקים התפעלו' חדוה בלב בפ\"ע ולא יוכל להתפעל במרירות באותה רגע כלל, ולהיפוך כשמתפעל במרירות לא יש בלבו חדוה כלל. וכן באהוי\"ר שנק' רו\"ש לא יוכל להיות <span data-k=\"pg\">900</span> ּ אהבה ויראה כלל<sup data-n=\"3151\">255</sup> ביחד, או אהבה לבדה או יראה, וכן או רצוא ברשפי אש או שוב כו', משא\"כ במוח יוכל להיות התכללות גמורה בסקירה א' אהוי\"ר רו\"ש כאחד כו'. ואע\"פ שהתפעלות הלב נמשך מהתפעלות המוח בל\"ב חדרים שבו ש[ל]זה נק' לב<sup data-n=\"3152\">256</sup> מ\"מ [מפני] שהמוחין הן בבחי' מקיפים שנק' עגולים והן בחי' הכלל, ע\"כ כל מיני התפעלות הפכי' בהיות כללו'<sup data-n=\"3153\">257</sup> לפי שבמקיף אין התחלקות כלל מצד העדר הכלים שאין במקיף כלים מכלים שונים. אבל בבחי' או\"פ שבלב שיש שם כלים מכלים שונים לכך יפרד שם התפעלות לבוא בהתחלקות להיות שיש לכ\"א מדור בפ\"ע ולא יתחברו כו'<sup data-n=\"3154\">258</sup> ב' הפכים כלל, כמו אם נתפעל באהבה וחדוה לא יקבל מרירות או יראה כלל כנ\"ל. וזהו עת לכל חפץ תחת השמים דוקא דהיינו תחת בחי' המקיפים [ש]במוחין שהוא במדות שבלב יש עת מיוחד בפ\"ע דוקא מבלי התכללות זב\"ז כלל, משא\"כ במוחין שבראש שהן כמו השמים לגבי הארץ כנ\"ל אין עת מיוחד לכל חפץ כו', אלא הן כלולים זב\"ז<sup data-n=\"3155\">259</sup> גם דבר והיפוכו מטעם שבמקיפים אין התחלקות כלל כי אין שם כלים להגביל ולחלק האור [ו]זה[ו] כמו ענין הכלל ופרט הנ\"ל וד\"ל.\n<b>ובכ\"ז</b> יובן דוגמת כ\"ז במשכן ביריעות והכלים שבו דמה שהי' ביריעות המשכן בבחי' מקיפי' בכמה גווני' דתכלת וארגמן תולעת שני ושש משזר דהיינו שהי' הכל בבחי' ההתכללו' זע\"ז, וזהו ענין משזר שהיו החוטין שזורין, וגם שזורין ע[מו] כל חוטי דתכלת כו' לפי שבבחי' המקיפי' והעיגולי' דיריעות כמו השמים כמ\"ש נוטה שמים כיריעה<sup data-n=\"3156\">260</sup> אין שם התחלקות [כלל] גם לא בדבר והיפוכו כמו שיש<sup data-n=\"3157\">261</sup> לבן עם תולעת שני שזורים וכלולים יחד, וכן הארגמן ותכלת מתערבין הכל כא' כו' להיותו בבחי' הכלל. אבל מיד שבא בגילוי באו\"פ בכלי' שהן ד' כלים דארון ושולחן ומנורה ומזבח הפנימי הרי בא האור בבחי' התחלקות [כי ל]כ\"א יש כלי מיוחד בפ\"ע כמו המנורה בדרום והשולחן בצפון כו', ולא יוכל להיות דבר והיפוכו כא' מטעם הנ\"ל שבבחי' או\"פ א\"א שיתחבר ב' הפכים ואע\"פ שהאו\"פ מקבל מאו\"מ וד\"ל. ועכ\"ז יובן שרש הדברים",[["3151","255","<b>כלל</b>: שם: ליתא."],["3152","256","<b>בל\"ב חדרים. . לב</b>: ראה גם לעיל פ' בא קח, א. וש\"נ."],["3153","257","<b>בהיות כללו'</b>: אד: בהתכללות."],["3154","258","<b>כו'</b>: שם: ליתא."],["3155","259","<b>זב\"ז</b>: שם: זע\"ז."],["3156","260","<b>נוטה שמים כיריעה</b>: תהלים קד, ב."],["3157","261","<b>שיש</b>: אד: שש."]]],[2300550503,"הנ\"ל בענין וידעת היום והשבות אל לבבך כו' דלב האדם דוקא שם הוא בחי' היחוד דהוי' אלקי' וזהו והשבות אל לבבך כי הוי' הוא האלקים ולא בהשגה שבמוח בידיעה לבד כו', והנה באמת הרי אמר וידעת היום תחלה ואח\"כ והשבות אל לבבך, הרי הידיעה שבמוח צריך להיות תחלה ואח\"כ ההשבה אל הלב. לפי שצריך בהכרח להקדים הידיעה שבבחי' מקיף שהוא הכלל שהוא שם בבחי' ההתכללות ההתפשטו'<sup data-n=\"3158\">262</sup> שבמוח כנ\"ל כמו היריעות שבמשכן ואח\"כ והשבות אל לבבך שהוא התפשטו'<sup data-n=\"3159\">263</sup> המדות מהתבוננו' זאת דהוי' הוא [ה]אלקים, שזה בא בגילוי או\"כ<sup data-n=\"3160\">264</sup> הלב בדרך פרט דוקא שזהו מ\"ש עת לכל חפץ תחת השמים כנ\"ל, שהוא כדוגמת הכלים שבמשכן כנ\"ל. ולפי שעיקר האדם הוא במדות שבלב שבפרט, ע\"כ [כל] עיקר היחוד דהוי' אלקים <span data-k=\"pg\">תנ</span> ּ הוא בהתפעלות שבלב האדם דוקא כי יש בו [ל]גילוי כל אור כלי מיוחד לכל אור, והיינו<sup data-n=\"3161\">265</sup> ענין ב' שמות דהוי' ואלקי', דשם הוי' הוא האור ואלקים הוא הכלי<sup data-n=\"3162\">266</sup> כידוע. משא\"כ במקיפים שבמוח אין שם הוי' בגילוי אור בכלי מיוחד מצד העדר הכלים רק בהסתר ובכללות הכל בא<sup data-n=\"3163\">267</sup> דוקא, ועכ\"ז צריך להקדים לידיעה שבמוח המקפת וכוללת כל התחלקות התפעלות שבלב וכמ\"ש וידעת היום ואח\"כ והשבות כו', מטעם הנ\"ל וד\"ל.\n<b>והנה</b> אנו אומרים וייחד לבבינו כו', ומבואר למעלה בענין מזבח הפנימי ומזבח החיצון שיש ב' לבבות פנימי וחיצון, וכאשר נתנו גחלי אש ממזה\"ח לפנימי זהו יחוד ב' לבבות. אך מבואר למעלה שעיקר יחוד דהוי' אלקי' הוא ביחוד ב' לבבות דחיצון ופנימי דשם הוי' בלב הפנימי מתייחד בשם אלקי' שבלב החיצון והיו לאחדים ממש, וזהו עיקר האדם כנ\"ל דכתיב בו הוי' אלקים ולא בשאר הנבראים זולתו כו', ויש להקדים לזה ענין סדר התפלה להיות ידוע בכהאריז\"ל שיש ג' מדרגות בכלל בסדר התפלה, מב\"ש עד ק\"ש ועד בכלל עד אמת ויציב [ואמת ויציב] עד ש\"ע וש\"ע עצמה. וביאור הדברים דב\"ש ופסוד\"ז צ\"ל בקול רם<sup data-n=\"3164\">268</sup> ובהתפעלות מורגשת בלב ומוח כמו המלאכים שאומרי' שירה בקול רעש גדול ובהתפעלו' יתירה וגם בק\"ש בואהבת בכל לבבך ובכל נפשך<sup data-n=\"3165\">269</sup> כו'. והטעם הוא לפי שצריך לברר ולהפך חומריות הגוף דנפש המתאווה כל תאוה באש זרה אין זה מתברר רק בהתלהבות דלב בשר דוקא כמו לבי ובשרי ירננו אל אל חי כו', הנק' אש שלמטה והוא העבודה שבלב החיצוני. אך זהו ע\"י אש שלמעלה בהתפעלות הנשמה [ה]אלקית בבחי' שלהבת י\"ה ממש שיורד ומזכך ומאיר בהתלהבות דלב בשר ובזה דוקא עולה ומתברר כנ\"ל, והוא כמו אש שלמעלה שבקרבנות שירד במזבח החיצון כנ\"ל, וכידוע",[["3158","262","<b>ההתכללות ההתפשטו'</b>: א: התפעלות. ד: ההתכללות ההתפעלות."],["3159","263","<b>התפשטו'</b>: שם: התפעלות."],["3160","264","<b>או\"כ</b>: שם: אור בכלי."],["3161","265","<b>והיינו</b>: שם: והוא."],["3162","266","<b>דשם הוי' הוא האור ואלקים הוא הכלי</b>: ראה שער היחוה\"א פ\"ד ואילך. לעיל פ' בשלח רמא, ב. וש\"נ."],["3163","267","<b>בא</b>: אד: כא'."],["3164","268","<b>דב\"ש ופסוד\"ז צ\"ל בקול רם</b>: ראה גם ספר חסידים סי\"ח (קרוב לסופו). לקמן פ' פקודי תנח, ג. שע\"ת מג, ד."],["3165","269","<b>בקול רם. . בק\"ש בואהבת בכל. . נפשך</b>: ראה גם מאמרי אדה\"ז כאן ע' ע. ולהעיר ממאמרי אדה\"א נ\"ך ע' דש. תו\"ח נח נה, ב."]]],[2300550517,"שהנשמה עצמה אינה צריכה תיקון כמו<sup data-n=\"3166\">270</sup> ישראל עלה במחשבה ולא ירדה רק לתקן ולברר לנה\"ט<sup data-n=\"3167\">271</sup> שנק' בירורים דק\"נ, וצריכה להתלבש בלבוש המתברר<sup data-n=\"3168\">272</sup> והוא בחי' התפעלו' מהתלהבות לב בשר במורגש וברעש. אע\"פ שמצד עצם התפעלות הנשמה היא בבחי' שלהבת י\"ה שאינו במורגש גופני כלל, מ\"מ מתלבש בלבוש המתברר שהוא התלהבות החום הטבעי בלב בשר כו' (וכנראה בחוש שכל טועם טעם בהתפעלו' אלקי' שבנשמה בשלהבת י\"ה כנ\"ל שמרגיש התפעלות אלקי' זה עצמו בלב בשר במורגש ממש כמו לבי ובשרי ירננו כו', וניכר זה בקול הניגון בדביקות שבא במורגש בהבל הלב כו'). לפי שאין המתקת הדינים וגבו' ושורש<sup data-n=\"3169\">274</sup> דק\"נ המעורב טו\"ר רק בשרשן<sup data-n=\"3170\">273</sup> בגבורות עליונות דשלהבת י\"ה [ו]בזה יטהר בלב<sup data-n=\"3171\">275</sup> החומרי מכל אש זרה דתאוה החומרי', עד\"מ שמוציאים אש ע\"י [אש דק] יותר ובפרט בשלהבת י\"ה נדחה ונשרף שם כל אש זרה מפני [שנק'] אשא תכלא דאכיל ושצי<sup data-n=\"3172\">276</sup> כמ\"ש במ\"א. וזהו כי לי בנ\"י עבדים<sup data-n=\"3173\">277</sup> לעבוד עבודת הבירורי' דק\"נ בטרח[א] ויגיעת המוח בהתבוננו' ע\"י הנשמה האלקי' להפוך חשך לאור כו', וזהו כל ימי חיי הבל[ו]<sup data-n=\"3174\">278</sup> של אדם לעבוד עבודה תמה זו לטהר לבו לה' לבדו כו' וד\"ל.\n<b>והמדריגה</b> הב' הוא מאמת ויציב ואילך לעבוד<sup data-n=\"3175\">279</sup> עבודת הנשמה [ה]אלקי' לצורך עלי' עצמה ולא לתקן הגוף כלל כמ\"ש כהתי\"ה<sup data-n=\"3176\">280</sup> כי כל ירידתה בגוף [ל]צורך עלי' <span data-k=\"pg\">902</span> ּ עצמה<sup data-n=\"3177\">281</sup>, וזה שכר עבודתה שיהי' עליות הנשמה עצמה<sup data-n=\"3178\">282</sup> ואין העילוי שלה רק לפ\"ע טוב עבודתה כו' כעבד המקבל שכר כו'. וענין טוב עבודתה בתיקון לב הבשר החומרי' הוא ענין הבאת גחלי אש ממזבח החיצון לפנימי כאשר נ[א]כל בשר הלב ונעשה כמו גחלי אש<sup data-n=\"3179\">283</sup> לוחשות להיות מזה הבערת ריח הקטרת במזבח הפנימי שהוא פנימי' הלב כנ\"ל, והיינו טוב עבודתה שמזה תקבל שכרה בעליי' עצמה בריח הקטרת שבמזבח הפנימי כמו מיכאל מקריב נשמות כו' וד\"ל. וזהו ענין ט\"ו ווי\"ן דאמת ויציב שהוא בחי' ט\"ו המשכות עליונ[ות] מלמעלמ\"ט לקשר את הנשמות כמו בווין תתקטר<sup data-n=\"3180\">284</sup> כו', והמשכה זו באה מצדיק חי עלמין להעלות ולקשר כל הנשמות, והוא מבואר במ\"ש ויציב יציבא מלתא<sup data-n=\"3181\">285</sup> ומתוקן ומקובל כו' שזהו לאמת את האמת דאהבה דכל לבבך<sup data-n=\"3182\">286</sup> שבק\"ש כו' כמ\"ש במ\"א וד\"ל.",[["3166","270","<b>כמו</b>: אד: כי."],["3167","271","<b>לנה\"ט</b>: א: לנה\"ב."],["3168","272","<b>וצריכה להתלבש בלבוש המתברר</b>: ראה גם שע\"ת נ, סע\"ג ואילך ובהערה 63."],["3169","274","<b>ושורש</b>: אד: קשות."],["3170","273","<b>שאין המתקת הדינים. . רק בשרשן</b>: ראה פע\"ח (שער השופר) שכ\"ו, פ\"א. תניא עם מ\"מ הגהות והע\"ק פל\"א. מאמרי אדה\"א דברים ח\"ב ע' תרטו. וש\"נ תו\"ח וירא קח, ב ובהערה 11."],["3171","275","<b>בלב</b>: א: לב. ד: הלב."],["3172","276","<b>אשא תכלא דאכיל ושצי</b>: ראה זהר (רע\"מ) צו כט, ב. בראשית נא, א. ראה מאמרי אדה\"א נ\"ך ע' רב."],["3173","277","<b>כי לי בנ\"י עבדים</b>: בהר כה, נה."],["3174","278","<b>ימי חיי הבל[ו]</b>: קהלת ו, יב."],["3175","279","<b>לעבוד</b>: אד: ליתא."],["3176","280","<b>כהתי\"ה</b>: אד: כל הנשמה תהלל י\"ה — תהלים קנ, ו."],["3177","281","<b>עצמה</b>: א: ליתא."],["3178","282","<b>עליות הנשמה עצמה</b>: א: עלוי לעצמה. ד: עלי' לעצמה."],["3179","283","<b>גחלי אש</b>: שם: גחלים."],["3180","284","<b>בווין תתקטר</b>: זמירות ליל שבת [אזמר בשבחין]."],["3181","285","<b>ויציב יציבא מלתא</b>: דניאל ו, יג."],["3182","286","<b>ויציב. . לאמת. . דאהבה דכל לבבך</b>: ראה לקמן פ' תצוה שעט, ג. וש\"נ."]]],[2300550530,"<b>ומדרגה</b> הג' הוא תפילת ש\"ע עצמה<sup data-n=\"3183\">*287</sup> והן ח\"י ברכאן<sup data-n=\"3184\">287</sup> שכורע בברוך<sup data-n=\"3185\">288</sup> כו' שהוא [ב]בחי' ביטול במציאות בתכלית, וכידוע בענין ואחרי הרעש אש<sup data-n=\"3186\">289</sup> היינו אחרי הרעש דפסוד\"ז אש שלהבת י\"ה דק\"ש קול דממה דקה בש\"ע כמ\"ש וקולה לא ישמע<sup data-n=\"3187\">290</sup> [ב]צלותא בלחש כו' שזהו ענין עליות הנשמה והתכללותה בעצמות א\"ס ב\"ה ממש כמו לאשתאבא בגופא דמלכא ממש. וזהו כמו שמיכאל כה\"ר<sup data-n=\"3188\">291</sup> כבר [הקריב] הנשמות ועלו למעלה מעלה בעצמות המאציל והיינו ריח הקטרת שכבר עלה למעלה לחזק המוחין כמו בבחי' השבת הנפש שע\"י ריח הבושם שיותר גדול מריח דקרבנות כנ\"ל, אך ע\"י הקרבנות שבמזבח החיצון דוקא שהוא סוף הכל בזה נעוץ תחילת הכל והוא עבודת הקטרת במזבח הפנימי שעולה עד פנימי' הכתר להיותו בבחי' קו האמצעי כנ\"ל, וע\"כ סדר העבודה מתחיל מקרבנות תמיד של שחר במזבח החיצון, וכך הוא בסדר התפלה מברוך שאמר עד ש\"ע כנ\"ל וד\"ל. וזהו וייחד לבבינו לאוי\"ר, פי' לייחד ולחבר חיצוני' הלב שהוא בחי' עבודה דנה\"א עם פנימי' הלב שהוא שכר עבודתה שעי\"ז תעלה בעליי' עצמה עד מהו\"ע א\"ס שבפנימי' הכתר שהוא ענין הקטורת שע\"ג מזה\"פ שמכוון נגד הארון ששם גילוי פנימיות ועצמיות דאוא\"ס ב\"ה כנ\"ל וד\"ל (ומ\"ש וידעת תחילה הוא בהתבוננות בגדולת ה' בק\"ש בשמע ואח\"כ ואהבת כו').\n[ז] <b>והנה</b> בכל הנ\"ל יתורץ ענין אחד, והוא מה שיש להפליא על שינוי הסדר במעשה המשכן ד[ב]פ' תרומה סידר ציווי המעשה תחילה על מעשה הארון ועשו ארון עצי שטים<sup data-n=\"3189\">292</sup> כו', ועשית שולחן<sup data-n=\"3190\">293</sup> כו', ועשית מנורת זהב<sup data-n=\"3191\">294</sup> כו', ואח\"כ ציו[ה] [ו]את המשכן תעשה עשר יריעות<sup data-n=\"3192\">295</sup> שש משזר ותכלת כו' עד עשיית<sup data-n=\"3193\">296</sup> מכסה לאוהל עורות אילים מאדמים<sup data-n=\"3194\">297</sup> ויריעות עזים עשתי עשר אוהל למשכן<sup data-n=\"3195\">298</sup>. נמצא אוהל המשכן ג' דברים יריעות עזים ועורות אילים מאדמים ועורות תחשים מלמעלה כו', ואח\"כ ציוה על הקרשים<sup data-n=\"3196\">299</sup> ואח\"כ על הפרוכת<sup data-n=\"3197\">300</sup> ואח\"כ על מזבח החיצון<sup data-n=\"3198\">301</sup> וחצר אהל מועד<sup data-n=\"3199\">302</sup> (ומזבח הזהב לא הזכיר כאן כלל רק בסוף פ' תצוה ועשית מזבח קטרת<sup data-n=\"3200\">303</sup> כו'). והנה בפ' ויקהל בעשיית בצלאל וכל חכמי לב הקדים מעשה היריעות לכלים כמ\"ש ויעשו את המשכן<sup data-n=\"3201\">304</sup> עשר יריעות כו' ויעש יריעות עזים<sup data-n=\"3202\">305</sup> לאוהל על המשכן כו', ומכסה העורות אילים מאדמים",[["3183","*287","<b>עצמה</b>: א: ליתא."],["3184","287","<b>ח\"י ברכאן</b>: זהר בראשית כו, א."],["3185","288","<b>שכורע בברוך</b>: ברכות יב, סע\"א."],["3186","289","<b>ואחרי הרעש אש</b>: ראה מל\"א יט, יב. ראה גם מאמרי אדה\"א נ\"ך ע' טז. קונטרסים ע' שז. לקמן פ' תצוה שמט, א ואילך."],["3187","290","<b>וקולה לא ישמע</b>: שמו\"א א, יג."],["3188","291","<b>כה\"ר</b>: אד: כה\"ג."],["3189","292","<b>ועשו ארון עצי שטים</b>: תרומה כה, י."],["3190","293","<b>ועשית שולחן</b>: שם כה, כג."],["3191","294","<b>ועשית מנורת זהב</b>: תרומה שם, לא."],["3192","295","<b>[ו]את המשכן תעשה עשר יריעות</b>: תרומה כו, א."],["3193","296","<b>עשיית</b>: אד: ועשית."],["3194","297","<b>ועשית מכסה לאהל. . מאדמים</b>: תרומה כו, יד."],["3195","298","<b>ויריעות עזים. . למשכן</b>: ראה שם כו, ז."],["3196","299","<b>ציוה על הקרשים</b>: תרומה כו, טו."],["3197","300","<b>ציוה. . על הפרוכת</b>: תרומה שם, לא."],["3198","301","<b>ציוה. . על מזבח החיצון</b>: תרומה כז, א."],["3199","302","<b>וחצר אהל מועד</b>: תרומה שם, ט."],["3200","303","<b>ועשית מזבח קטרת</b>: תצוה ל, א."],["3201","304","<b>ויעשו את המשכן</b>: ויקהל לו, ח [בדילוג]."],["3202","305","<b>ויעש יריעות עזים</b>: ויקהל שם, יד."]]],[2300550543,"ומכסה [עורות] התחשים<sup data-n=\"3203\">306</sup> ואח\"כ ויעש את הקרשים<sup data-n=\"3204\">307</sup> כו' ואח\"כ ויעש בצלאל את הארון<sup data-n=\"3205\">308</sup> כו' ויעש את השולחן<sup data-n=\"3206\">309</sup> כו' ויעש את המנורה<sup data-n=\"3207\">310</sup> ויעש את מזבח הקטורת<sup data-n=\"3208\">311</sup> ויעש את <span data-k=\"pg\">תנא</span> ּ מזבח העולה<sup data-n=\"3209\">312</sup> ויעש את הכיור<sup data-n=\"3210\">313</sup> ויעש את החצר<sup data-n=\"3211\">314</sup> כו', והי' לו לעשות כפי שנצטוה מפי משה מפי ה' שהוא לעשות הארון תעשה מנורה<sup data-n=\"3212\">315</sup> ושולחן<sup data-n=\"3213\">316</sup> ואח\"כ ציווי<sup data-n=\"3214\">317</sup> היריעות כו'. והנה ידוע מארז\"ל שזה הי' מחולק בצלאל עם משה<sup data-n=\"3215\">318</sup> כשאמר לו לעשות הארון והכלים [תחלה] כפי שנצטווה כסדרן [כמ\"ש] בפ' תרומה ואח\"כ משכן אמר לו בצלאל וכי דרך בנ\"א לעשות כלי[ם] ואח\"כ אוהל ובית אלא עושין משכן ואהל תחלה ואח\"כ מכניסים הכלים לתוכו כו', ואמר לו משה בצלאל בצ\"ל א\"ל היית וידעת כו', והיינו שאמר משה ראו קרא ה' בשם בצלאל<sup data-n=\"3216\">319</sup> כי בצלא\"ל זה ע\"ש חכמתו נק' בצ\"ל א\"ל כו'.\n<b>ולהבין</b> זה למה בציווי המעשה בפ' תרומה הקדים לצוות על הכלים קודם למשכן ובסדר המעשה בפ\"מ עשה בצלאל המשכן תחלה, ואע\"פ שהודה משה לבצלאל שיפה כיוון להיות עושה משכן תחלה, אבל בציווי המעשה כמו שנאמר למשה הקדים לצוות על הכלים תחלה, ומשמע דגם זה אמת הוא, כי הלא ע\"פ ה' נצטווה משה ואיך יכול להיות שניהם אמת, דלכאו' הודאת משה לבצלאל היפך כדת<sup data-n=\"3217\">320</sup> הציווי כו'. אך הנה יובן בהקדים תחלה<sup data-n=\"3218\">321</sup> ענין הידוע במחלוקת אם שמים קדמו<sup data-n=\"3219\">322</sup> לארץ, או ארץ קדמה לשמים, ושניהם אמת דכפי סדר ההשתל' דאבי\"ע באו\"כ או\"מ ואו\"פ הרי ודאי אור המקיף שהוא השמים הסובב לארץ קדמה בבריאה וכמ\"ש בראשית ברא את השמים<sup data-n=\"3220\">323</sup> ואח\"כ הארץ כמו המח' שקדמה לדיבור, ואם אין מח' אין דבור<sup data-n=\"3221\">324</sup> כלל כמ\"ש במ\"א. אבל מטעם דסוף מעשה עלה במח' תחלה<sup data-n=\"3222\">325</sup> ארץ קדמה לשמים וכמ\"ש ביום עשות הוי' אלקי' ארץ ושמים<sup data-n=\"3223\">326</sup> מאחר דכל עיקר הכוונה בשפע העליונה הוא בשביל הארץ א\"כ שרש הארץ קדמה לשמים. ולזה כל עיקר סיבת המשכות עליונות אינו בא רק מצד אתעדל\"ת דוקא וכמ\"ש אל יתהלל חכם<sup data-n=\"3224\">327</sup> כו' כ\"א לעשות חסד ומשפט וצדקה בארץ<sup data-n=\"3225\">328</sup> דוקא, מפני שסוף מעשה עבמ\"ת וד\"ל. וגם כאן יובן במחלוקת משה ובצלאל דשניהם אמת, דכפי סדר ההשתל' דאבי\"ע שצריך לבוא מלמעלמ\"ט מעילה לעילה עד התהוות כל הברואים מאין ליש בארץ וכל אשר בה, ודאי צ\"ל אור [ה]מקי[פי'] קודם שהוא כמו בחי' הכלל שבמוח ואח\"כ יוצא בדרך פרט בגילוי או\"כ כמו ענין וידעת היום בידיעה כללית שבמוח תחלה, ואח\"כ והשבות",[["3203","306","<b>ומכסה העורות </b>[אד: עורות]<b>. . התחשים</b>: ראה ויקהל שם, יט."],["3204","307","<b>ויעש את הקרשים</b>: ויקהל שם, כ."],["3205","308","<b>ויעש בצלאל את הארו</b>: ויקהל לז, א."],["3206","309","<b>ויעש את השולחן</b>: שם לז, י."],["3207","310","<b>ויעש את המנורה</b>: שם שם, יז."],["3208","311","<b>ויעש את מזבח הקטורת</b>: ויקהל לז, כה."],["3209","312","<b>ויעש את מזבח העולה</b>: ויקהל לח, א."],["3210","313","<b>ויעש את הכיור</b>: ויקהל שם, ח."],["3211","314","<b>ויעש את החצר</b>: שם שם, ט."],["3212","315","<b>תעשה מנורה</b>: אד: תחלה ומנורה."],["3213","316","<b>ומנורה ושולחן</b>: ראה הערות 293-4."],["3214","317","<b>ציווי</b>: אד: ליתא."],["3215","318","<b>מחולק בצלאל עם משה</b>: ראה ברכות נה, א."],["3216","319","<b>ראו קרא ה' בשם בצלאל</b>: ויקהל לה, ל."],["3217","320","<b>כדת</b>: אד: סדר."],["3218","321","<b>תחלה</b>: שם: ליתא."],["3219","322","<b>אם שמים קדמו</b>: חגיגה יב, א."],["3220","323","<b>בראשית ברא את </b>[אד: ליתא]<b> השמים</b>: בראשית א, א [בדילוג]."],["3221","324","<b>ואם אין מח' אין דיבור</b>: ראה אגה\"ק סו\"ס יט. ביאוה\"ז ויצא יח, ד. שע\"ת קו, ד ואילך. מאמרי אדה\"א הנחות תקע\"ז ר\"ע לה וע' רסג."],["3222","325","<b>דסוף מעשה עלה במח' תחלה</b>: ע\"פ פיוט לכה דודי."],["3223","326","<b>ביום עשות. . ושמים</b>: בראשית ב, ד."],["3224","327","<b>אל יתהלל חכם</b>: ירמי' ט, כב."],["3225","328","<b>כ\"א לעשות. . בארץ</b>: שם: כג [בדילוג — ושם עושה. ראה הנסמן לעיל פ' בשלח קלח, ד]."]]],[2300550556,"אל לבבך בגילוי או\"כ בדרך התחלקות בפרט. וזה הי' דעת בצלאל בסדר המעשה לעשות היריעות דמשכן תחלה שהן בחי' המקיפי' כנ\"ל ואח\"כ עשה הארון והכלים כמ\"ש בפ' ויקהל כו'. וזה שאמר למשה וכי דרך בני אדם לעשות כלים תחלה כו', וכן הוא דעת האומר שמים קדמו, וכמ\"ש נוטה שמים כיריעה כו'. אמנם בציווי המעשה בפ' תרומה למשה בא הציווי לעשות הארון והכלים תחלה, וגם זה אמת לפי ש[ה]עיקר הוא הארון והשולחן ומנורה ומזבח כו' ששם גילוי שכינה ע\"י הקרבנות והעבודות שנק' העלאת מ\"ן [ו]המשכות מ\"ד כו'. וכמו שמבואר למעלה באורך בענין גחלי אש הניתן ממזבח החיצון על מזבח הפנימי בשביל קטורת וכהדלקת נרות המנורה כו' שמחמת זה יהי' ממילא המשכות אורות המקיפי' העליוני' מלמעלמ\"ט משום דסו\"מ עלה במח\"ת כמ\"ש ארץ קדמה לשמים<sup data-n=\"3226\">329</sup> וד\"ל. <span data-k=\"pg\">904</span> ּ וזהו שבאופן סדר המעשה בפו\"מ הודה משה לבצלאל [שצריך] לעשות היריעות דמשכן תחלה, וזהו שא' לבצלאל<sup data-n=\"3227\">330</sup> בצ\"ל א\"ל היית כו', פי' צ\"ל א\"ל הוא בחי' מקיף שנק' צ\"ל כמ\"ש ה' צלך<sup data-n=\"3228\">331</sup> כו', והוא בחי' צ\"ל חסד עליון דבחי' המקיף הכללי שנק' חפץ חסד<sup data-n=\"3229\">332</sup> שמצד עצמו בלתי התעוררות מלמטה כלל, וע\"כ קדם המקיף הזה לאו\"פ הבא בגילוי או\"כ אח\"כ כנ\"ל וד\"ל. אבל בציווי המעשה הכלים קודמים, שזהו כדי לעורר [את] המקיף דחפץ חסד הנ\"ל באתעדל\"ת ע\"י השראות אלקי' בכלים דארון ושולחן יומשך אור המקיפים ממילא וא\"כ הציווי למעשה ע\"י משה<sup data-n=\"3230\">333</sup> הוא כשנתעורר עי\"ז בחי' [ה]מקיפים. וזהו שאמר ועשו ארון כגוזר ואומר שיעשו ע\"י אתעדל\"ת דוקא, אבל לאחר שכבר נתעורר המקיף וא\"צ רק לירד למטה בפו\"מ ודאי המקיף קודם לאו\"כ<sup data-n=\"3231\">334</sup>. וזהו שאמר במעשה דבצלאל ויעש מפני שכבר נעשה אתעדל\"ע<sup data-n=\"3232\">335</sup> ע\"י ציווי המעשה לכלים תחלה וא\"צ רק עשי' בפו\"מ ע\"כ א' ויעש כו', ובציווי למשה נאמר ועשית שיעש[ה] ע\"י העלאת מ\"ן באתעדל\"ת שכדי לעורר המקיפים צריך לעשות הכלים תחלה, ואז יוכל בצלאל לעשות כפי [ה]סדר מלמעלמ\"ט היריעות קודם לכלים, [ו]נמצא דשניהם אמת והא בהא תליא דוקא וד\"ל.\n<b>ובכ\"ז</b> יובן ג\"כ בסדר התפלה מברוך שאמר עד ק\"ש שהוא השיר והשבח בגדולת ה' שזהו הידיעה וההשגה במוח דוקא ואח\"כ בואהבת יוצא לגילוי בלב באו\"כ מיוחד כו', וזהו כמ\"ש וידעת היום תחילה ואח\"כ והשבות כו' שזהו לפי סדר ההשתל' מלמעלה למטה, אבל מאמת ויציב עד ש\"ע וש\"ע ה\"ז",[["3226","329","<b>לשמים</b>: אד: ליתא."],["3227","330","<b>לבצלאל</b>: שם: לו. ראה גם לקמן פ' ויקהל שפז, א. תלא, ב."],["3228","331","<b>ה' צלך</b>: תהלים קכא, ה."],["3229","332","<b>חפץ חסד</b>: מיכה ז, יח."],["3230","333","<b>למעשה ע\"י משה</b>: אד: למשה ע\"י מעשה."],["3231","334","<b>לאו\"כ</b>: א: לאור וכלי. ד: לאו\"פ."],["3232","335","<b>אתעדל\"ע</b>: א: אתעדל\"ת."]]],[2300550569,"כמו שהי'<sup data-n=\"3233\">336</sup> אתעדל\"ת באו\"כ<sup data-n=\"3234\">337</sup> לעורר לבחי' המקיפים, והוא כמו קרבן הקטורת במזבח הפנימי, כך עליית הנשמה בט\"ו ווי\"ן דאמת ויציב אחר שניתן גחלים ממזבח החיצון, שזהו ענין וייחד לבבינו [לב] הפנימי עם לב החיצון, ואח\"כ בסמיכת גאולה לתפלה זהו כמו הק[י]רוב להיכל ק\"ק כו', והתפלה עצמה הוא לאשתאבא בגופא דמלכא כו' שעי\"ז נמשך ממילא מבחי' סובב הכללי מקור כל המקיפים כו', וכמ\"ש דוד המלך<sup data-n=\"3235\">338</sup> אחת שאלתי<sup data-n=\"3236\">339</sup> כו', שבתי בבית ה' שהן בחי' הכלים שבמשכן, ואז ממילא יבא כל המקיפים להודות<sup data-n=\"3237\">340</sup> בנועם ה' ולבקר בהיכלו יצפנני יסתירני<sup data-n=\"3238\">341</sup> כו' [ו]כמ\"ש במ\"א באריכות וד\"ל.\n<b>והנה</b> ביריעות המשכן היו ד' מדרגות, הא' מקיפים דיריעות המשכן במספר עשר כנגד י\"ס דאצי'<sup data-n=\"3239\">342</sup> שבבחי' המקיפי' שה[ם] תכלת וארגמן כו', והב' יריעות האוהל למשכן שהן יריעות עזים עשתי עשר<sup data-n=\"3240\">343</sup>, והג' מכסה לאוהל מעורות אילים מאדמים<sup data-n=\"3241\">344</sup>, והד' מכסה עורות תחשים<sup data-n=\"3242\">345</sup> מלמעלה כו'. ומבואר בספרי הקבלה דמספר יריעות עשר דתכלת וארגמן כו' הן בבחי' האצי' כנ\"ל, אבל יריעות עזים ועורות אילים ועורות תחשים הן ג' מדריגות דנוגה דבי\"ע שנבררו מסט\"א ונעשים בבחי' אוהל למשכן ויריעות עזים הן לאוהל והן עשתי עשר כמ\"ש בזהר הטעם<sup data-n=\"3243\">346</sup>, וגם בעודף המספר שלהם באורך שלשים באמה<sup data-n=\"3244\">347</sup> [הן] יותר מאורך היריעה דתכלת שהוא כ\"ח באמה<sup data-n=\"3245\">348</sup> כו', ועורות אילים למכסה האוהל הן יותר גסים ועורות תחשים מלמעלה הוא יותר גס. והוא סדר המדריגות דבחי' נוג\"ה דבריאה שרוב[ו] טוב ומיעוטו רע הן יריעות עזים שהן שעירות<sup data-n=\"3246\">350</sup> כמ\"ש ועשו איש שעי\"ר<sup data-n=\"3247\">351</sup> כו', וכאשר מתבררים עולים להיות <span data-k=\"pg\">תנב</span> ּ לאוהל על המשכן, ועורות אילים מאדמים הוא בחי' נוגה דיצי' דחציו טוב וחציו רע כו', ועורות תחשים הוא בחי' נוגה דעשי'<sup data-n=\"3248\">349</sup> שרובו רע ומיעוטו טוב וגם הוא מתברר ונעשה מכסה שני מלמעלה.\n[ח] <b>ולהבין</b> ביאור כ\"ז, הנה יש להבין<sup data-n=\"3249\">352</sup> תחלה דשרש הלבושים בבחי' המקיפים דהיינו בחי' מקיף שלא יוכל לבוא באו\"כ מאיר הוא על הלבושים, וראי' לזה ממה שמצינו דפושט ב' לבושים כא'<sup data-n=\"3250\">353</sup> קשה לשכחה כו', משום דכח",[["3233","336","<b>שהי'</b>: א: שהוא. ד: ליתא."],["3234","337","<b>באו\"כ</b>: א: באו\"מ."],["3235","338","<b>המלך</b>: אד: ליתא."],["3236","339","<b>אחת שאלתי</b>: תהלים כז, ד. ראה גם לעיל פ' שמות מח, ד. וש\"נ."],["3237","340","<b>להודות</b>: אד: לחזות."],["3238","341","<b>יצפנני יסתירני</b>: תהלים שם, ה."],["3239","342","<b>דיריעות המשכן במספר עשר כנגד י\"ס דאצי'</b>: ראה מקדש מלך לזהר תרומה קסד, ב. אור התורה תרומה ע' א'תצז."],["3240","343","<b>יריעות עזים עשתי עשר</b>: תרומה כו, ז."],["3241","344","<b>מכסה לאוהל מעורות אילים מאדמים</b>: שם כו, יד."],["3242","345","<b>מכסה עורות תחשים</b>: תרומה שם."],["3243","346","<b>עשתי עשר כמ\"ש בזהר הטעם</b>: ראה זהר תרומה קסד, ב."],["3244","347","<b>המספר. . שלשים באמה</b>: תרומה כו, ח."],["3245","348","<b>היריעה דתכלת שהוא כ\"ח באמה</b>: שם כו, ב."],["3246","350","<b>שעירות</b>: ד: שעירי\"ם."],["3247","351","<b>ועשו איש שעי\"ר</b>: תולדות כז, יא [ושם: הן עשו אחי איש שעיר — ראה גם הנסמן במאמרי אדה\"א שמות ח\"א ע' קעב]."],["3248","349","<b>נוג\"ה דבריאה. . דיצי'. . דעשי'</b>: נסמן לעיל פ' משפטים רצד, א."],["3249","352","<b>להבין</b>: אד: להקדים."],["3250","353","<b>דפושט ב' לבושים כא'</b>: ראה מנחת אהרן לר\"י פרדו כלל כב, סי\"ב. מאמרי אדה\"א דברים ח\"א ע' קיד. וש\"נ. ח\"ד ע' א'רלד."]]],[2300550580,"הזכרון הוא מבחי' מקיף ושורה על הלבושים כו', וגם ממה שהלבוש מייפה לאדם יותר מכפי המדה דאו\"כ כו'. והנה ידוע ג\"כ בענין ג' מדרגות דאור וכלי ולבוש שאין מקום יניקה ואחיזה לחיצונים באו\"כ כלל וכלל אפי' בחיצוני' הכלים דע\"ס דעשי', לפי שידוע דלמ\"ד כלים דז\"א דאצי' נעשה נר\"נ בבי\"ע<sup data-n=\"3251\">354</sup> ומאיר גם בכלים דע\"ס דבי\"ע עד גם שכלים החיצונים דנפש דעשי' יש שם מאור האצי' (וכמו גם נפש דישראל שמבחי' כלי החיצון דמל' דעשי' כו' כידוע בענין אתה בראת יצרת נפחת בי ואתה משמרה בקרבי<sup data-n=\"3252\">355</sup> לבלתי ידח ממנו נדח<sup data-n=\"3253\">356</sup> כו'), וע\"כ א\"א להיות יניקת החיצונים גם בתערובות טו\"ר בכלים דבי\"ע כלל. ואפי' בכלים דמל' [דמל'] דעשי' היותר אחרון וכמ\"ש וכבוד\"י לאח\"ר לא את\"ן<sup data-n=\"3254\">357</sup> שהוא בחי' גילוי אור אלקי ממש<sup data-n=\"3255\">358</sup> שבא בירידת ההשתל' באורות וכלים עד כלים החיצונים כו' (כידוע דג' כלים הם פנימי ואמצעי וחיצון כמו ג' אותיות דמודו\"מ<sup data-n=\"3256\">359</sup>, וכמ\"ש אתה סת\"ר לי ראש תוך סוף<sup data-n=\"3257\">360</sup> כו' כמ\"ש במ\"א). אך ורק בבחי' הלבושים שנפרדי' מן העצם דאו\"כ שם יוכל להיות תערובות טו\"ר שיוכלו החיצונים לקבל משם יניקה ג\"כ, וראי' לזה ממה שאמרו הני מאני דרבנן דבלו<sup data-n=\"3258\">361</sup> מחופייהו דידהו הרי יכולים החיצונים לשלוט בלבושים דרבנן לבלותם, וזהו השבח שאמר שמלתך לא בלתה<sup data-n=\"3259\">362</sup> כו' וכמ\"ש במ\"א, והיינו בחי' לבושים דנוגה דבי\"ע שיש שם תערובות טו\"ר בכל עולם לפ\"ע וכמ\"ש בע\"ח דנוגה דבריאה רובו טוב כו', והיינו בבחי' לבושים דנוגה אבל לא בכלים אפי' בחיצונים כנ\"ל וד\"ל.\n<b>ובזה</b> יובן ענין הד' מדרגות ביריעות המשכן הנ\"ל, הא' מקיפים דיריעות דתכלת ושש משזר כו', היינו כמו שהוא בבחי' עולם [ה]אצי' עצמו ממש שאין שם גם מקור להסתעפות תערובות טו\"ר, וכמ\"ש לא יגורך רע<sup data-n=\"3260\">363</sup> כלל אפי' בלבושים. וזהו ענין היריעות דתכלת כו' שגם שהן לבושים [ש]מתלבש בהן אורות המקיפים הן בתכלית הקדושה האלקי' [דמקיפי' דע\"ס] דאצי' ממש כו'. אבל יריעות העזים שנעש[ים] לאוהל על המשכן דעשר יריעות כו' שהוא מבחי' לבושים דנוגה דבריאה שיש בזה תערובות טו\"ר גם<sup data-n=\"3261\">364</sup> שרובו רע<sup data-n=\"3262\">365</sup> כו', ומתברר ועולה להיות בבחי' אהל על המשכן שהוא בא בהגשמת אור המקיף מאחר שנתגשם ונתלבש ביריעות עזים דק\"נ כמו",[["3251","354","<b>דלמ\"ד כלים. . נר\"נ בבי\"ע</b>: נסמן לעיל פ' יתרו רנח, ד."],["3252","355","<b>אתה בראת. . משמרה בקרבי</b>: ע\"פ ברכות השחר (ברכות ס, ב). ראה גם מאמרי אדה\"א הנחות תקע\"ז ע' רב. וש\"נ."],["3253","356","<b>לבלתי ידח ממנו נדח</b>: שמו\"ב יד, יד."],["3254","357","<b>וכבוד\"י לאח\"ר לא את\"ן</b>: ישעי' מב, ח. מח, יא."],["3255","358","<b>אלקי ממש</b>: א: הכלי."],["3256","359","<b>דג' כלים. . אותיות דמודו\"מ</b>: ראה גם לעיל פ' בא קכט, סע\"ד ואילך."],["3257","360","<b>אתה סת\"ר. . סוף</b>: ראה עמק המלך (שער גופו של אריך ושל עתיק יומייא) שי\"ב, פ\"ד (סט, א). סידור שחרית נז, ג. מאמרי אדה\"ז על מארז\"ל ע' קצב וע' קצט. לקו\"ת שלח מא, ד. מאמרי אדה\"א דברים ח\"ג ע' תשצב. וש\"נ. שע\"ת צט, ד ובהערה 22."],["3258","361","<b>הני מאני דרבנן דבלו</b>: ראה ברכות ו, א."],["3259","362","<b>שמלתך לא בלתה</b>: עקב ח, ד. ראה גם מאמרי אדה\"א דברים ח\"א ע' קיד. וש\"נ."],["3260","363","<b>[ה]אצי'. . לא יגורך רע</b>: תהלים ה, ה. ראה מאמרי אדה\"א קונטרסים ע' רפט. וש\"נ."],["3261","364","<b>גם</b>: אד: רק."],["3262","365","<b>רע</b>: שם: טוב."]]],[2300550591,"בהיפוך הרע לטוב ע\"י תשובה מעומקא דלבא, שעכ\"ז מן הטומאה בא רק שנהפך מטמא לטהור כו', וכמ\"ש מי יתן טהור מטמא<sup data-n=\"3263\">366</sup> לא אחד כו', משא\"כ קדושה האלקית בעצם כעשר יריעות דתכלת כו'. ולזה יריעות עזים הן י\"א נגד י\"א ארורים<sup data-n=\"3264\">367</sup> <span data-k=\"pg\">906</span> ּ דק\"נ שנהפך לקדושה ובי\"א סממני הקטורת כו' כידוע וד\"ל. ואמנם זהו הוראה גדולה על מעלת אורות המקיפים שיוכלו לירד למטה ולהתלבש בלבושי' דנוגה שהן יריעות עזים אחר הבירור וכמ\"ש במ\"א בענין ענני [ה]כבוד כו' שירדו אורות מקיפים עליונים ונתלבשו בהגשמת עננים גשמיים והיו לשומר לבנ\"י לקבל החיצים<sup data-n=\"3265\">368</sup> כו', כך היריעות עזים נעשה לאוהל כו' וד\"ל.\n<b>והנה</b> מאחר שכלל גדול הוא שכל הגבוה<sup data-n=\"3266\">369</sup> גבוה יותר [יותר] יוכל להשפיל א\"ע גם בדברים השפלים ביותר כמו ועברתי<sup data-n=\"3267\">370</sup> כו', הרי יובן מזה בענין מכסה לאוהל המשכן שהוא עורות אילים מאדמים כו', שזהו בדבר השפל ביותר [ו]הוא בחי' לבוש דנוגה דיצי' שחציו טוב וחציו רע, וכאשר נתברר ונהפך הרע לטוב נעשה בחי' מכסה לאוהל דיריעות עזים כו', שזהו ירידה גדולה יותר שאחיזת החיצוני' שולטת שם יותר, ונהפך לקדושה להיות שומר יותר רק שהוא גס יותר, והוא מה שנעשה מכסה האוהל כו'. וענין עורות תחשים שהוא מכסה השני על העורות אילים מאדמים הוא בחי' נוגה דעשי' שרובו רע ומיעוטו טוב, ויש שם יניקת החיצונים בתערובות טו\"ר ברע יותר. ועכ\"ז לאחר הבירור כמו ענין התשוקה מרע גמור כו', נעשה מכסה מלמעלה על [ה]עורות [אלים] מאדמים כו', ומפני שביותר אחרון בגסות דק\"נ שם ירד מאור המקיף העליון יותר, עכ\"ז<sup data-n=\"3268\">371</sup> יש יתרון המעלה בעורות תחשים מכולם. וכמו ויעש ה' לאדם<sup data-n=\"3269\">372</sup> כתנו\"ת עו\"ר וילבישם שנק' בגדי עשו החמודו\"ת<sup data-n=\"3270\">373</sup> שאמר ע\"ז וירח ריח בגדיו<sup data-n=\"3271\">374</sup> כו', ובתורתו של ר\"מ הי' כתוב כתנו\"ת או\"ר באל\"ף<sup data-n=\"3272\">375</sup> שהוא לבוש זך ובהיר שנק' זהירו<sup data-n=\"3273\">376</sup> עילאה<sup data-n=\"3274\">377</sup> כו' שזהו לאחר הבירור דעה\"ד טו\"ר כו' לגמרי<sup data-n=\"3275\">378</sup> נעשה מכתנות עור<sup data-n=\"3276\">379</sup> החשמ\"ל אור צח בבחי' מקיף ולבוש קדוש ונורא כו' (וזהו שבפ' נשא<sup data-n=\"3277\">380</sup> ציוה ה' ליתן הכלי הקדש<sup data-n=\"3278\">381</sup> ארון [ושולחן] ומנורה ומזבח",[["3263","366","<b>מי יתן טהור מטמא</b>: איוב יד, ד."],["3264","367","<b>יריעות עזים הן י\"א נגד י\"א ארורים</b>: ראה ע\"ח (שער המלכים) שי\"א, פ\"י."],["3265","368","<b>ענני [ה]כבוד. . לקבל החיצים</b>: ראה גם לעיל פ' בא קכא, ב ובהנסמן שם."],["3266","369","<b>שכלל גדול הוא שכל הגבוה</b>: ראה לעיל פ' שמות כא, ב הערה 863."],["3267","370","<b>ועברתי</b>: בא יב, יב."],["3268","371","<b>עכ\"ז</b>: אד: ע\"כ."],["3269","372","<b>ויעש ה' לאדם</b>: בראשית ג, כא [ושם ה\"א — ראה לקמן פ' ויקהל תכ, ב. שעה\"י קמ, א הערה 9 — ולאשתו]."],["3270","373","<b>בגדי עשו החמודו\"ת</b>: ראה גם לעיל פ' משפטים רפז, ב. וש\"נ."],["3271","374","<b>וירח ריח בגדיו</b>: תולדות כז, כז [בדילוג]. ראה גם לעיל ח, ב. וש\"נ."],["3272","375","<b>ובתורתו של ר\"מ. . באל\"ף</b>: נסמן לעיל פ' משפטים רפז, ב."],["3273","376","<b>זהירו</b>: אד: זיהר\"א."],["3274","377","<b>זיהר\"א עילאה</b>: ראה זהר בראשית לו, ב. הנסמן לעיל פ' שמות ח, ב."],["3275","378","<b>לגמרי</b>: א: ליתא."],["3276","379","<b>מכתנות עור</b>: א: כתנות אור ונעשה מכתנות עור. ד: מכתנות אור."],["3277","380","<b>שבפ' נשא</b>: כנראה הכוונה על הפ' [לאחרי הקדמה וידבר ה'] נשא את ראש בני קהת — במדבר ד, ב ואילך."],["3278","381","<b>הכלי הקדש</b>: א: הכלים כתי' קודם."]]],[2300550602,"הזהב בבגד תכלת ופרשו עליהם עו\"ר תח\"ש<sup data-n=\"3279\">382</sup> דוקא כי עור תחש הוא הבירור היותר אחרון, וזהו שתרגומו ששגוונ\"א<sup data-n=\"3280\">383</sup> ששש בגוונים שלו כמ\"ש במ\"א [בפ' נשא]<sup data-n=\"3281\">384</sup>. וזהו מרבדים עשתה לה<sup data-n=\"3282\">385</sup> שש וארגמן לבושה זה קאי במל' דאצי' שרש כנס\"י אחר תשלום הבירור דעה\"ד כו' ע\"י מצות מעשיות, דכמו שנעשה לבוש דנשמות ישראל<sup data-n=\"3283\">386</sup> פרטי' בג\"ע ממעשה המצות שעשה האדם בכל ימיו שהוא בירורי' דק\"נ שבדברים גשמיי' נעשה המצות כו', כך לכללות נש\"י נעשה בחי' לבוש[י'] מכל המצות שעשו כללות נש\"י בכל הגליות. והוא הנק' ארגמן שכלול מכמה גוונים<sup data-n=\"3284\">387</sup>, והוא בגד העליון, והבגד שמלביש לגוף הוא השש שהוא הפשתן הלבן, שזהו בחי' אה\"ר הטבעיות ופשוטה בלתי מורכבת שהוא כח ושרש לכל מעשה המצות. וזהו שש וארגמן לבושה (ומרבדים עשתה לה מעורות תחשים) כו' וד\"ל.",[["3279","382","<b>ארון. . בבגד תכלת. . תח\"ש</b>: במדבר ד, ה. ו. וכפי' הראב\"ע ורמב\"ן שם."],["3280","383","<b>שתרגומו ששגוונ\"א </b>[ד: ססגונא]: ת\"א לתרומה כה, ה. כו, יד. ועוד. שבת כח, א."],["3281","384","<b>ששש בגוונים שלו. . (בפ' נשא)</b>: ראה מאמרי אדה\"א במדבר ח\"א ע' קעב וע' קפ."],["3282","385","<b>מרבדים עשתה לה</b>: משלי לא, כב."],["3283","386","<b>דנשמות ישראל</b>: אד: לנשמה."],["3284","387","<b>ארגמן שכלול מכמה גוונים</b>: ראה זהר תרומה קלט, א."]]],[2300550055,"<b>בע\"ה פ' תרומה תקפ\"ו לפ\"ק</b>\n<span data-k=\"pg\">תנג</span> ּ<b>ועשית</b> שנים כרובים<sup data-n=\"3285\">1</sup> זהב מקשה תעשה אותם<sup data-n=\"3286\">2</sup> כו' ועשה כרוב אחד מקצה מזה וכרוב אחד מקצה מזה מן הכפורת תעשה את הכרובים על שני קצותיו<sup data-n=\"3287\">3</sup>, והיו הכרובים פורשי כנפים [למעלה] סוככים בכנפיהם על הכפורת ופניהם איש אל אחיו<sup data-n=\"3288\">4</sup> כו', ונתת את הכפורת<sup data-n=\"3289\">5</sup> על הארון כו', עד ונועדתי לך שם ודברתי אתך מעל הכפורת מבין שני הכרובי' אשר על ארון העדות את כל אשר אצווך אל בנ\"י<sup data-n=\"3290\">6</sup>.\n<b>והנה</b> כמו\"כ כתיב (בס\"פ נשא) בחנוכת המזבח, ובבוא משה אל אוהל מועד לדבר אתו וישמע את הקול מדבר אליו מעל הכפורת אשר על ארון העדות מבין שני הכרובי' וידבר אליו. הרי כל [ה]קול ו[ה]דבור שדיבר ה[קב\"ה] עם משה הי' שומע [משה] מעל הכפורת כו' ומבין שני הכרובים דוקא, דמשמע דאותו הקול שהי' שומע יוצא מעל הכפורת הוא שעבר ונכנס",[["3285","1","<b>ועשית שנים כרובים</b>: מיוסד על מאמר ד\"ה מי יתנך תקע\"א ונמצא לפנינו בג' נוסחאות. א) מאמרי אדה\"ז תקע\"א ע' צג (והיא הנחת כ\"ק אדה\"א). ב) הנחה נוספת נדפסה שם ע' עז (מגוכי\"ק אדמו\"ר הצ\"צ). ג) תו\"א ר\"פ תרומה (עט, ג). הגהות וכו' מכ\"ק אדמו\"ר הצ\"צ שנדפסו באוה\"ת תרומה ע' א'תנה ואילך הם על גוכי\"ק הנ\"ל. בדרוש מי יתנך תקע\"א הנ\"ל ישנו א) המשך נוסף שלא נתבאר כאן. ב) ביאור. ראה עוד ע\"ד המאמר לקמן ברשימת הכת\"י [ושם ג\"כ מפורט סימני האותיות הבאות להלן בהמראי מקומות]."],["3286","2","<b>ועשית שנים כרובים. . אותם</b>: תרומה כה, יח."],["3287","3","<b>ועשה כרוב אחד. . קצותיו</b>: תרומה שם יט."],["3288","4","<b>והיו הכרובים. . אל אחיו</b>: שם כה, כ."],["3289","5","<b>ונתת את הכפורת</b>: תרומה שם כא."],["3290","6","<b>ונועדתי לך. . אצווך אל בנ\"י</b>: שם שם כב [ושם: אצוה אותך. וראה לקמן שיז, א על יד הערה 342]."]]],[2300550087,"בין ב' הכרובים [דוקא] והי' שומע הקול מבין ב' הכרובים, א\"כ משמע מזה עכ\"פ דכל התורה כולה ניתנה למשה רק מבין ב' הכרובים הללו דוקא וד\"ל. [ו]יש להבין לכאורה מה שייכות יש לב' כרובים הללו ומבין שניהם יחד דוקא שמשם יומשך התו\"מ דוקא, והיינו בכל התנאים הללו שהכרובים יהיו פניהם איש אל אחיו דוקא ויהיו פורשי כנפיים למעלה כו' (ודוקא כאשר הב' כרובים מבין<sup data-n=\"3291\">7</sup> קצות הכפורת ומן הכפורת עצמו יעשה אותם כמבואר בפ' וכמ\"ש בסוף אל הכפורת יהיו פני הכרובים<sup data-n=\"3292\">8</sup> דהיינו לאחר ש[י]הי' פניהם איש אל אחיו יתכללו להיות פניהם אל הכפורת).\n<b>והנה</b> יש להקדים מ\"ש למען אחיי ורעיי<sup data-n=\"3293\">9</sup> אדברה נא שלום בך דמשמע מזה דכנס\"י נק' אחים ורעים ממש להקב\"ה, וזה פלא דהלא אין ערוך אליו כלל ואיך יהי' ערך נש\"י להיות נק' אחים ורעים ממש כו'. ועוד יש להבין מה שמסיים בזה למען בית ה' אלקינו אבקשה טוב לך<sup data-n=\"3294\">10</sup>, הרי חלק לב' דברים הללו דהיינו שלום וטוב, בחי' שלום יהי' למען אחיי ורעיי דוקא אדברה נא שלום בך, ובחי' הטוב יהי' למען בית ה' אלקינו דוקא, וז\"ש למען בית ה' אבקשה כו', ולכאורה הי' ראוי שיכלל ג'<sup data-n=\"3295\">*11</sup> הדברים כא[חד] דלמען אחיי ורעיי יהי' שלום וגם טוב או למען בית ה' יהי' ג\"כ שלום ולמה חלקם לשתים דוקא כו'. ואמנם באמת פסוק זה מדבר בענין א' והוא מה שאמר למען אחיי כו' דאימתי נק' ישראל אחים ורעים להקב\"ה רק דוקא כאשר בית ה' אלקינו קיים שאז יבקש טוב לך אז ידבר שלום למען אחיי כו', אבל בזמן הגלות שאין בית ה' אלקינו קיים אז אין ישראל נק' אחים ורעים כלל להקב\"ה, וז\"ש למען אחיי ורעיי למען בית ה' כו' דמשמע דהא בהא תליא דוקא דאימתי למען אחיי כאשר בית ה' כו' וד\"ל. וזהו שכנס\"י בזמן הגלות דוקא מבקשת מי יתנך כאח לי<sup data-n=\"3296\">11</sup> כו', פי' מי יתנך כמו שהי' בזמן בהמ\"ק שהיו כנס\"י נק' אחים וריעים משום דבזמן הגלות לא נק' אחים וריעים, וע\"כ בקשה מי יתנך כאח לי וד\"ל. אך א\"כ האיך מבקשת כנס\"י דבר שא\"א להיות כ\"א בזמן <span data-k=\"pg\">908</span> ּ בהמ\"ק כנ\"ל, אלא מוכרח לומר דבקשה זו היינו מה שיוכל להיות שיהי' כאח לי גם בזמן הגלות כמו בזמן בהמ\"ק, והוא ע\"י מצות ת\"ת דוקא שהן ד\"א של הלכה שהוא במקום היכל ק\"ק<sup data-n=\"3297\">12</sup> ממש כמבואר בדרז\"ל דמשחרב בהמ\"ק אין להקב\"ה בעולמו אלא ד\"א של הלכה<sup data-n=\"3298\">13</sup> במקום היכל ק\"ק כו' (כמשי\"ת). ולפ\"ז יתורץ גם הקושיא הא'",[["3291","7","<b>מבין</b>: אב: מב'."],["3292","8","<b>אל הכפורת יהיו פני הכרובים</b>: המשך הכתוב והיו הכרובים פורשי כנפים."],["3293","9","<b>למען אחיי ורעיי</b>: תהלים קכב, ח. ראה גם מאמרי אדה\"ז על מארז\"ל ע' רצא."],["3294","10","<b>למען בית ה' אלקינו אבקשה טוב לך</b>: תהלים שם, ט."],["3295","*11","<b>ג'</b>: אב: ב'."],["3296","11","<b>מי יתנך כאח לי</b>: שה\"ש ח, א."],["3297","12","<b>ד\"א של הלכה שהוא במקום היכל ק\"ק</b>: ראה ברכות ח, א. תניא פנ\"ג. הנסמן לעיל פ' בא צד, א."],["3298","13","<b>דמשחרב בהמ\"ק אין להקב\"ה בעולמו אלא ד\"א של הלכה</b>: ראה ברכות שם. הנסמן לעיל פ' וארא ע, ג."]]],[2300550119,"דלעיל דאינו תולה מ\"ש למען אחיי כו' דוקא [בזמן] שבהמ\"ק קיים שז\"ש למען בית כו', דא\"כ למה חלק שלום וטוב לשנים. ועוד דהל\"ל למען בית ה' תחלה ואח\"כ למען אחיי כו' מאחר שאינו נק' אחים רק כאשר בית ה' אלקינו קיים כנ\"ל. אלא הכוונה בזה שאמר למען אחיי כנ\"ל גם בזמן הגלות דוקא שהוא ד' אמות של הלכה במקום היכל ק\"ק ממש שנק' אחים ומזה יומשך כח<sup data-n=\"3299\">14</sup> שלום דוקא כמ\"ש או יחזיק במעוזי<sup data-n=\"3300\">15</sup> יעשה שלום לי כנ\"ל<sup data-n=\"3301\">16</sup>, והן ב' שלימות בפמשמ\"ע ובפמשמ\"ט כידוע והכל ע\"י ת\"ח שא' בהן ורב שלום בניך<sup data-n=\"3302\">17</sup> כו' (כמ\"ש במ\"א). ואח\"כ אמר למען בית ה' כו', שזהו כמו בזמן בהמ\"ק<sup data-n=\"3303\">18</sup> שהיו הכרובים פניהם איש אל אחיו הי' יחוד פב\"פ להמשיך בחי' טוב העליון, שהוא בחי' צ\"ע<sup data-n=\"3304\">19</sup> ביחוד עליון דקודב\"ה וכנס\"י שזהו יחוד קודב\"ה ושכינתי' בחי' יחו\"ת, ואמנם יחו\"ע<sup data-n=\"3305\">20</sup> דאו\"א בא דוקא במצות ת\"ת, וזהו שהקדים לומר למען אחיי כו' שהן כמו או\"א שנק' תרין ריעין<sup data-n=\"3306\">21</sup> כו' וד\"ל.\n<b>והנה</b> תחלה יש להבין מהו ענין הכרובים, ומה שהי' כרוב אחד מקצה מזה כו' ופניהם איש אל אחיו דוקא כו' ומ\"ש שהי' מדבר אליו מבין ב' הכרובים דוקא כו', דהנה ידוע בפי' כרובים לשון רביא כלומר כרביא<sup data-n=\"3307\">22</sup> לפי שהיו הכרובים בציור אדם קטן בשנים שנק' נער ותרגומו רביא<sup data-n=\"3308\">23</sup>, והוא בחי' פני אדם שבמרכבה כמ\"ש ופני אדם לארבעתן<sup data-n=\"3309\">24</sup>, וכן ודמות פניהם פני אדם<sup data-n=\"3310\">25</sup> וזהו כמו פני אדם קטן שנק' רביא, והוא בחי' אנפי זוטרי כמ\"ש בזהר<sup data-n=\"3311\">26</sup> ויש ב' מיני פנים א' בחי' נפש<sup data-n=\"3312\">27</sup> אנפי רברבי שנק' אדם הגדול, והב' בחי' אנפי זוטרי שהוא אדם קטן ואע\"פ שהוא קטן ציורו כמו ציור אדם הגדול כו'. וביאור הדברים הנה ההפרש הזה בין אדם הגדול לאדם הקטן ואיך שיוכלו להתכלל כא', זהו כמשל האב שגדול בחכמה ובשנים שמדבר עם בנו הקטן ורך בשנים שנק' נער ורביא כמו כי נער ישראל ואוהבהו<sup data-n=\"3313\">28</sup> כו', וכמו במ\"ת שהי' הקב\"ה מדבר עם ישראל פב\"פ<sup data-n=\"3314\">29</sup> כידוע, והרי בחי' החכמה דאוא\"ס עצמו מאיר בבחי' הפנים העליונים כמו חכמת אדם תאיר פניו<sup data-n=\"3315\">30</sup> כשאמר אנכי ה'<sup data-n=\"3316\">31</sup> כו', זהו בחי' אנפי רברבי שנק' אדם הגדול (כמשי\"ת). וישראל שעמדו בהר סיני כאיש א'<sup data-n=\"3317\">32</sup> הרי היו ס\"ר<sup data-n=\"3318\">33</sup> נשמות בגופים שהשגתם ומדות שלהם מצומצם מאד כערך הקטן ששכלו ומדותיו קטנים מאד אע\"פ שנק' ג\"כ אדם כי בצלם אלקים עשה<sup data-n=\"3319\">34</sup> כו', אבל אין ערך כלל ביניהם, ועכ\"ז דיבר ה'",[["3299","14","<b>כח</b>: אב: בחי'."],["3300","15","<b>או יחזיק במעוזי</b>: נסמן לעיל פ' יתרו רנג, ג."],["3301","16","<b>כנ\"ל אב</b>: כו'."],["3302","17","<b>ורב שלום בניך</b>: ישעי' נד, יג."],["3303","18","<b>בזמן בהמ\"ק</b>: ראה ב\"ב צט, א. מאמרי אדה\"א קונטרסים ע' שסב."],["3304","19","<b>צ\"ע</b>: אב: כנ\"י."],["3305","20","<b>יחו\"ת. . יחו\"ע</b>: זהר בהקדמה יב, א."],["3306","21","<b>או\"א שנק' תרין ריעין</b>: ראה זהר בשלח נו, א. ויקרא ד, א. לעיל פ' בא קכ, א. וש\"נ."],["3307","22","<b>כרובים. . כרביא</b>: ראה סוכה ה, ב. חגיגה יג, ב."],["3308","23","<b>נער ותרגומו רביא</b>: ראה ת\"א וירא כא, יז-כ."],["3309","24","<b>ופני אדם לארבעתן</b>: ראה יחזקאל א, י. לעיל פ' שמות כח, א. וש\"נ."],["3310","25","<b>ודמות פניהם פני אדם</b>: יחזקאל א, י."],["3311","26","<b>אנפי זוטרי כמ\"ש בזהר</b>: ראה זהר פינחס ריז, ב. הנסמן לעיל פ' משפטים רפז, ג."],["3312","27","<b>נפש</b>: א: ליתא. ב: חסר."],["3313","28","<b>כי נער ישראל ואוהבהו</b>: הושע יא, א."],["3314","29","<b>במ\"ת. . פב\"פ</b>: ואתחנן ה, ד."],["3315","30","<b>חכמת אדם תאיר פניו</b>: קהלת ח, א."],["3316","31","<b>אנכי ה'</b>: יתרו כ, ב."],["3317","32","<b>וישראל שעמדו בהר סיני כאיש א'</b>: ראה רש\"י יתרו יט, ב."],["3318","33","<b>וישראל. . בהר סיני. . ס\"ר</b>: ראה בא יב, לז. מכילתא יתרו יט, יא. ב\"ר פ\"ע, ט. שבת פח, א."],["3319","34","<b>כי בצלם אלקים עשה</b>: נח ט, ו."]]],[2300550151,"עמהם פב\"פ ממש ואמר אנכי ה' אלקיך ממש, וכמו שאמר באור פניך ממש נתת לנו<sup data-n=\"3320\">35</sup> כו' וד\"ל.\n<b>וכמו\"כ</b> יובן בענין <span data-k=\"pg\">תנד</span> ּ כמים הפנים אל פנים<sup data-n=\"3321\">36</sup> כן לב האדם לאדם שזהו בחי' אנפי זוטרי שנק' אדם תתאה עם בחי' אנפי רברבי שנק' אדה\"ע שכמים הפנים אל פנים ממש כך לב האדה\"ע לאדם התחתון<sup data-n=\"3322\">37</sup> כו', שהן נש\"י באתעדל\"ת שלהם באוי\"ר בקבלת עומ\"ש במצות שעי\"ז יתעוררו כמים הפנים אל פנים לפ\"ע ממש בחי' אתעדל\"ע<sup data-n=\"3323\">38</sup> מלב האדם העליון לאדם התחתון. וזה פלא לכאורה אחר שזה בתכלית הגדלות וזה בתכלית הקטנות איך יתפעל על<sup data-n=\"3324\">39</sup> הגדול מן הקטן כאדם גדול שיתפעל מתינוק קטן, אך עדיין יכול להיות זה באב עם בנו מצד אה\"ר העצמית שנפש הבן נמשך מהאב ונפשו קשורה בנפשו<sup data-n=\"3325\">40</sup> ממש, וכמו ילד שעשועים כמו הבן יקיר לי אפרים<sup data-n=\"3326\">41</sup> כו', וכתיב בנים אתם<sup data-n=\"3327\">42</sup> כו' שיכול להיות אתעדל\"ע מצד אתעדל\"ת שלהם, אע\"פ שהן בבחי' הקטנות בתכלית וכמ\"ש כי נער ישראל [ואוהבהו] כו'. אבל בענין המרכבה דד' חיות שיש בחי' פני אדם בכ\"א כמ\"ש [ו]פני אדם לארבעתן שהוא אנפי זוטרי כנ\"ל שבודאי אין ערוך להם כלל וכלל לגבי בחי' אדם שעל הכסא שנק' אדם הגדול בחי' אנפי רברבי (שזהו בחי' ז\"א דאצי' כידוע), ואיך יכול להיות שיהי' המרכבה הזאת נושאות לכסא בבחי' ההעלאת מ\"ן לאדה\"ע כו' (אחר שאין ערוך כלל לנברא<sup data-n=\"3328\">43</sup> בע\"ג עם הבורא שהוא בלתי בע\"ג כידוע). אך הנה באמת יש להבין איך יתכן תואר אדם למעלה, [ו]אע\"פ שאמר דמות כמראה אדם<sup data-n=\"3329\">44</sup> ולא אדם ממש הלא הוא או' כי לא ראיתם כל תמונה<sup data-n=\"3330\">45</sup>, וכמ\"ש שאין לו גוף<sup data-n=\"3331\">46</sup> ולא דמות הגוף ח\"ו, וגם כתיב וגם נצח ישראל<sup data-n=\"3332\">47</sup> כו', כי לא אדם הוא כו'. אך הנה אנו מוצאים בכתוב כמה תוארי אדם באלקות כמו וירא ה'<sup data-n=\"3333\">48</sup> וישמע [ה']<sup data-n=\"3334\">49</sup> וישב ה'<sup data-n=\"3335\">50</sup> ויתעצב אל לבו [וינחם]<sup data-n=\"3336\">51</sup> כו', שכ\"ז הוא תוארי אדם דוקא כידוע. ואמנם הנה יש להקדים בשורש ענין<sup data-n=\"3337\">52</sup> התורה שנק' ג\"כ [ב]בחי' אדם וכמ\"ש וזאת תורת האדם<sup data-n=\"3338\">53</sup> כו' כמו שהאדם כלול מחכ' ומדות ורמ\"ח אברים<sup data-n=\"3339\">54</sup> חיצונים כו', ואדם גימט' מ\"ה<sup data-n=\"3340\">55</sup> דחכמה, כך הוא בחי' החכ' דתורה שהוא בחי' שם מ\"ה דאדם דאורייתא מח\"ע נפקת<sup data-n=\"3341\">56</sup>, ויש בחכ' שבתורה בחי' המדות [כמו] כשר פסול טמא טהור כו', חייב זכאי כו', שזהו",[["3320","35","<b>באור פניך. . נתת לנו</b>: סיום שמו\"ע."],["3321","36","<b>כמים הפנים אל פנים</b>: משלי כז, יט [ושם לפנים (וכ\"ה בא). ראה לעיל קב, ב. וש\"נ]."],["3322","37","<b>שכמים הפנים. . לב האדה\"ע לאדם התחתון</b>: נסמן לעיל רצ, ב."],["3323","38","<b>באתעדל\"ת. . אתעדל\"ע</b>: נסמן לעיל פ' יתרו רנט, ב."],["3324","39","<b>על</b>: אב: ליתא."],["3325","40","<b>ונפשו קשורה בנפשו</b>: לשון הכתוב ויגש מד, ל."],["3326","41","<b>הבן יקיר לי אפרים</b>: ירמי' לא, יט."],["3327","42","<b>בנים אתם</b>: פ' ראה יד, א."],["3328","43","<b>שאין ערוך כלל לנברא</b>: ראה גם לעיל קעא, ב. וש\"נ."],["3329","44","<b>דמות כמראה אדם</b>: יחזקאל א, כו."],["3330","45","<b>כי לא ראיתם כל תמונה</b>: ואתחנן ד, טו."],["3331","46","<b>שאין לו גוף</b>: ע\"פ פיוט יגדל."],["3332","47","<b>וגם נצח ישראל</b>: שמו\"א טו, כט."],["3333","48","<b>וירא ה'</b>: בראשית ו, ה."],["3334","49","<b>וישמע [ה']</b>: בהעלותך יא, ו."],["3335","50","<b>וישב ה'</b>: תהלים כט, י."],["3336","51","<b>ויתעצב אל לבו </b>[וינחם]: בראשית ו, ו [בהיפך הסדר. בדילוג]."],["3337","52","<b>ענין</b>: א: בחי' ענין. ב: ענין בחי'."],["3338","53","<b>וזאת תורת האדם</b>: שמו\"ב ז, יט. ראה זהר (רע\"מ) משפטים קיז, ב. צו כט, ב."],["3339","54","<b>שהאדם. . ורמ\"ח אברים</b>: אהלות פ\"א, מ\"ח."],["3340","55","<b>ואדם גימט' מ\"ה</b>: נסמן לעיל פ' משפטים רפא, ד."],["3341","56","<b>דאורייתא מח\"ע נפקת</b>: נסמן לעיל פ' יתרו רסח, ד."]]],[2300550183,"בחי' אדם פנימי וגם בציור אדם חיצוני<sup data-n=\"3342\">57</sup> ברמ\"ח אברים שהם רמ\"ח מ\"ע<sup data-n=\"3343\">58</sup> כידוע שכלולים בתורה וד\"ל.\n<b>ולהבין</b> ביאור הדברים הנה יש להבין תחלה בענין יחוד עליון בע\"ס דאצי' שנק' ג\"כ בשם אדם אדמה לעליון<sup data-n=\"3344\">59</sup> ממש, שהוא יחוד דע\"ס בעצמות אוא\"ס ממש שהוא רם ונשא הגבה למעלה מכל ההשתל' דע\"ס דאצי' וגם למעלה מן הרצון וחכמה דהיינו שגם בחי' החכ' דאצי' נק' בחי' עשיי' גשמי'<sup data-n=\"3345\">60</sup> שנמשך כמו בכח הפעולה ע\"י אותיות ושמות (כמשי\"ת), וע\"כ א\"א לומר שיוכלו להשיג באמיתית אוא\"ס ב\"ה ע\"י בחי' החכ', כמו שא\"א לומר [שישיג] למשש אור השכל<sup data-n=\"3346\">61</sup> הרוחני ביד כו' כמו ערך הגשם לגבי הרוחני והרבה יותר מזה כערך הדומם לגבי השכל אין ערך לחכמה לגבי עצמות המאציל, עד שא\"א לומר <span data-k=\"pg\">910</span> ּ שבחכמה או בינה יושג אוא\"ס וכמאמר לית מח' תפיסא בי' כלל<sup data-n=\"3347\">62</sup>. וכתיב החקר אלוה תמצא<sup data-n=\"3348\">63</sup> כו' מאחר שגם מקור החכ' נאצל מן עצמות המאציל רק בבחי' עשי' בפועל לבד כמ\"ש והחכ' מאין תמצא<sup data-n=\"3349\">64</sup>, פי' מאין תמצא במציאות חכ' כי לא נודע מקור התהוות מציאות מאין תמצא זהו פי' הפשוט, וע\"ד הקבלה היינו מאין והעלם דאור הכת\"ר<sup data-n=\"3350\">65</sup>, דחכמה תמצא בבחי' י\"ש כי גם החכמה נאצל מאין ליש.\n<b>והענין</b> הוא כידוע דחכ' כולל ב' פירושים<sup data-n=\"3351\">66</sup> [הפכים] א' בחי' מ\"ה לשון מה פשפשת<sup data-n=\"3352\">67</sup>, והב' לשון מהות דוקא, כי זה ההפרש בין בחי' אין דחכמה כמו שהוא בהעלם עדיין דהיינו עד\"מ כמו בכח השכל שבאדם שמשכיל כל שכל שבאדם<sup data-n=\"3353\">68</sup> שזהו בחי' הנביעה מן מעיין החכמה כמו מעיין הנובע מהעלם לגילוי ועדיין לא בא לגילוי שכל וסברא, רק כאשר בא לגילוי כברק מבריק<sup data-n=\"3354\">69</sup> שנק' התחכמות [ו]המצא' שכל חדש, וזהו כגילוי נביעת המעיין [לנהר] טיפין טיפין כנודע שזהו מאין תמצא במציאות יש ומתפשט מבחי'<sup data-n=\"3355\">70</sup> שנק' נהר<sup data-n=\"3356\">71</sup> ונק' תרדל\"מ כידוע. אך כאשר נאצל אור החכ' ממקורא דכולא<sup data-n=\"3357\">72</sup> שהוא עצמות המאציל דהיינו ממש כמו שהחכ' מאין [ליש] מהעלם לגילוי תמצא, כך גם מקור החכמה שמשפיע וממשיך כל מציא[ו]ת [שכל ו]חכמה בגילוי גם הוא נאצל מאין ליש דהיינו מהעלם העצמ[י] שהוא בבחי' אין האמיתי כו', דהיינו רק ע\"י בחי' אותיות ושמות שהוא<sup data-n=\"3358\">73</sup> כמ\"ש",[["3342","57","<b>אדם פנימי. . אדם חיצוני</b>: ראה גם לעיל פ' בשלח קנט, ב."],["3343","58","<b>ברמ\"ח אברים שהם רמ\"ח מ\"ע</b>: ראה ת\"ז ת\"ל (עד, סע\"א). שע\"ת עב, ג הערה 17."],["3344","59","<b>אדם אדמה לעליון</b>: נסמן לעיל רסב, א."],["3345","60","<b>החכ' דאצי'. . עשיי' גשמי'</b>: ראה גם לעיל קלה, א."],["3346","61","<b>שא\"א לומר [שישיג] למשש אור השכל</b>: ראה שער היחוד והאמונה פ\"ט."],["3347","62","<b>לית מח' תפיסא בי' כלל</b>: ראה ת\"ז בהקדמה (יז, א)."],["3348","63","<b>החקר אלוה תמצא</b>: איוב יא, ז."],["3349","64","<b>והחכמה מאין תמצא</b>: איוב כח, יב."],["3350","65","<b>מאין והעלם דאור הכת\"ר</b>: ראה גם לעיל פ' בא קא, ג. וש\"נ."],["3351","66","<b>דחכ' כולל ב' פירושים</b>: ראה מאמרי אדה\"א בראשית ע' ח. וש\"נ. הנחות תקע\"ז ע' כח. תו\"ח בראשית א, ג ובהנסמן במ\"מ לשם."],["3352","67","<b>מה פשפשת</b>: זהר בהקדמה א, ב."],["3353","68","<b>שבאדם</b>: אב: וחכ'."],["3354","69","<b>כברק מבריק</b>: ראה גם לעיל פ' בשלח קצז, ב. וש\"נ."],["3355","70","<b>מבחי'</b>: א: לבחי' בינה. ב: לבחי' תבונה."],["3356","71","<b>בינה שנק' נהר</b>: ראה זהר (אדרא דמשכנא) משפטים קכג, ב."],["3357","72","<b>ממקורא דכולא</b>: זהר בראשית לג, א."],["3358","73","<b>שהוא</b>: אב: ליתא."]]],[2300550215,"בזהר ובע\"ח ששם ע\"ב [שהוא שם] הוי' במילוי יודי\"ן<sup data-n=\"3359\">74</sup> על ידו נאצל אור מקור החכ', וכן שם ס\"ג<sup data-n=\"3360\">75</sup> במילוי ההי\"ן<sup data-n=\"3361\">76</sup> נאצל בחי' בינה<sup data-n=\"3362\">77</sup>. וכך כללות הע\"ס נק' רק בשם [ו]אותיות והוא רק רזא דשמא קדישא<sup data-n=\"3363\">78</sup> שהוא שם הוי', כי [כל] אור [וספי'] א\"א להיות נאצל מן העצמ[י] רק ע\"י ד' אותיות הללו דיו\"ד וה\"א צמצום והתפשטות וי\"ו ה\"א<sup data-n=\"3364\">79</sup> וי\"ו המשכה והתפשטות [ד]ה' אחרונה הוא שנעשה מציאות אור הנאצל באו\"כ [ממש] כידוע. שזהו כמשל שמו של אדם שאינו שייך כלל למהו\"ע רק שיהי' נפנה לקורא[י]ו שע\"י השם הוא נתפס להיות יכול[ים] לקרותו בשם זה לזולתו, אבל כמו שהוא לעצמו א\"צ שם כלל (וזהו רק כמו בית יד אל הכלי שנק' כלי חיצוני להתפס על ידו לבד. ואין שם זה כמו שם התואר שמורה על העצם דוקא שא\"א להיות [לו] שם אחר כלל כקריא' שם האותיות אל\"ף בי\"ת כו', וכקריאת שמות לשור ואריה וכל הבע\"ח דמ\"ש ויקרא<sup data-n=\"3365\">80</sup> אדם<sup data-n=\"3366\">81</sup> כו', שזהו כמו<sup data-n=\"3367\">82</sup> העצמי שאו\"כ<sup data-n=\"3368\">83</sup> היו אורות ונאצלים<sup data-n=\"3369\">84</sup> בבחי' יחוס וערך לגבי אור העצמ[י], מאחר שנק' בשם [ה]תואר עכ\"פ המורי' על העצמות ממש. אבל בענין השמות דע\"ב ס\"ג כו' הרי אמר בזהר עביד מאנא וקרא בי' גרמי' חכים<sup data-n=\"3370\">85</sup> [כו' שזהו בחי' הכלי החיצוני' דנק' מאנא רברבא שהוא שם ע\"ב כו', ובשם זה קרי גרמי' חכים ש]הוא אור החכ' דאצי' שנאצל מאין ליש כו'<sup data-n=\"3371\">86</sup>, והיינו רק<sup data-n=\"3372\">87</sup> להיות מקור להעולמות בגילוי אור והשפע למקבלים לבד כמו להיות בריאת העולמות בחכ' דוקא כמ\"ש כולם בחכ' <span data-k=\"pg\">תנה</span> ּ עשית<sup data-n=\"3373\">88</sup> ובראשית בחוכמתא<sup data-n=\"3374\">89</sup> כו', וגם החכ' דבראשית נמי מאמר הוא<sup data-n=\"3375\">90</sup> שנמצא מאין ליש כנ\"ל. וכך הוא בכל השמות דע\"ס בכלל שנק' שמא קדישא שאינו שייך לעצמו כלל, רק שע\"י בחי' השמות הללו הוא שנגלה אור א\"ס בעולמות, וכמ\"ש חכים ולא בחכ' ידיעא<sup data-n=\"3376\">91</sup> באורות וכלים כו', וכן מבין ולא בבינה ידיעא שהוא למעלה מבחי' השמות דע\"ב ס\"ג דחו\"ב דאצי'. וכן בשאר הספירות והמדות וכמו שמסיים לאו דאית לך צדק ידיעא דאיהו דין ולא כו', עד ולאו מכא\"מ כלל, וכמ\"ש בס\"י ע\"ס בלי מ\"ה בלי מהות<sup data-n=\"3377\">92</sup> כלל רק לאחזאה לאתנהגא בהון עלמין<sup data-n=\"3378\">93</sup> כו', שהן כמו מדות חג\"ת שמנהיגים העולמות ע\"פ מקורם המולידים אורות דחו\"ב שהן שמים<sup data-n=\"3379\">94</sup> דע\"ב ס\"ג כו'. וא\"כ לפי\"ז הרי אין ערוך כלל וכלל לאורות דע\"ס דאצי' שמיוחדים בשמות דע\"ב ס\"ג כו' לגבי עצמות המאציל מאחר שאינן נקראים בשם התואר",[["3359","74","<b>ששם ע\"ב. . יודי\"ן</b>: ראה לעיל פ' וארא פד, ד והערות 805. 809. פה, ג הערה 837."],["3360","75","<b>שם ס\"ג</b>: ראה זהר (רע\"מ) פינחס רמו, ב."],["3361","76","<b>ס\"ג במילוי ההי\"ן</b>: ראה גם תו\"ח וירא צז, ד ובהערה 48. שעה\"י קכח, ב הערה 44."],["3362","77","<b>ס\"ג. . בינה</b>: ראה ע\"ח שער הכללים פ\"ח. הנסמן לעיל פ' וארא פד, ד."],["3363","78","<b>הע\"ס. . רזא דשמא קדישא</b>: נסמן לעיל פ' יתרו רנז, ד."],["3364","79","<b>דיו\"ד וה\"א. . וי\"ו ה\"א</b>: ראה אגה\"ת פ\"ד."],["3365","80","<b>ויקרא אדם</b>: בראשית ב, כ [ושם: האדם — ראה גם מאמרי אדה\"א ויקרא ח\"ב ע' תשסו]."],["3366","81","<b>ויקרא אדם</b>: ראה גם לעיל פ' בא קיג, ג. יתרו רנב, ד. מאמרי אדה\"א דברים ח\"ד ע' א'רסח ואילך."],["3367","82","<b>כמו</b>: אב: שמו."],["3368","83","<b>שאו\"כ</b>: שם: שא\"כ."],["3369","84","<b>ונאצלים</b>: שם: הנאצלים."],["3370","85","<b>עביד מאנא. . חכים</b>: ראה זהר (רע\"מ) בא מב, ב."],["3371","86","<b>כו'</b>: א: כנ\"ל. ב: הנ\"ל."],["3372","87","<b>רק</b>: בתו\"ח כאן נכפל עה\"פ התיבות: והיינו ע\"ב כו'. . והיינו רק."],["3373","88","<b>כולם בחכ' עשית</b>: תהלים קד, כד."],["3374","89","<b>ובראשית בחוכמתא</b>: ראה תרגום ירושלמי בראשית א, א."],["3375","90","<b>דבראשית נמי מאמר הוא</b>: ר\"ה לב, א."],["3376","91","<b>חכים ולא בחכ' ידיעא</b>: ת\"ז בהקדמה (יז, ב)."],["3377","92","<b>ע\"ס בלי מ\"ה בלי מהות</b>: ראה ס\"י פ\"א, מ\"ב ובמפרשים שם."],["3378","93","<b>לאחזאה לאתנהגא בהון עלמין</b>: ראה ת\"ז שם."],["3379","94","<b>שמים</b>: אב: שמות."]]],[2300550247,"אלא זהו רק כמו שם הכינוי לבד שהוא ע\"ש הפעולה ע\"ש שהוא בחי' ההתפשטות<sup data-n=\"3380\">95</sup> חוץ מעצמות[ו] כמו שם חכ' ע\"ש התפשטות אור החכמה לעולמות כנ\"ל, כמו כי אמרתי עולם חסד יבנה<sup data-n=\"3381\">96</sup>, וכן אור החסד ואור הגבורה והת\"ת כו'<sup data-n=\"3382\">97</sup> ע\"ש פעולתן להנהגת העולמות, כך הן נק' בשמות אלו, וזהו דומה מעט לשם האדם שנתפס ע\"י לזולתו שנק' כלים החיצונים שפועלים כל פעולה והמשכה בלבד ואין להם שייכות וערך לגבי העצמות כו' וד\"ל.\n<b>אבל</b> באמת אין הענין כן כמ\"ש במ\"א (בפ' בא<sup data-n=\"3383\">98</sup> ) בענין ז' שמות שאינן נמחקים<sup data-n=\"3384\">99</sup> שהן הוי' אל אלקי' ושדי [ו]צבאות, וגם בהוי' דחו\"ב כמו ע\"ב ס\"ג כו' ה\"ז מיוחדים בעצמות המאציל ממש, כמ\"ש דאיהו וחיוהי שהן בחי' האורות דע\"ס וגם גרמוהי שהן בחי' כלים החיצוני' הנ\"ל (שנק' שם חכים) חד<sup data-n=\"3385\">100</sup> ממש, ולכך גם שנק' שמות אינן נמחקים, א\"כ מזה מוכרח לומר דגם בחי' שמות עליונים [הללו] דע\"ב ס\"ג כו' שכלולים בשם הוי' אינן נבדלים ונפרדים מן העצמות דא\"ס ויש להם ערך ויחוס להתייחד עמו באחדות פשוט ממש. ואע\"פ שאמר ולאו מכא\"מ כלל דמשמע [מזה] שמובדל ומושלל לגמרי מתוארי המדות אלה להיותו בחי' אח\"פ ממש כמ\"ש אנת הוא חד ולא בחושבן<sup data-n=\"3386\">101</sup> פי' ולא בחושבן י\"ס כלל דלפני אחד מה אתה סופר<sup data-n=\"3387\">102</sup> כו', גם זה ודאי אמת הוא, אבל מצד שצמצם א\"ע וקרא גרמי' חכים ומבין בב'<sup data-n=\"3388\">103</sup> שמות הללו, ה\"ז כמו שם התואר שמתייחדים במהותו ועצמותו ממש כמ\"ש דאיהו וחיוהי וגרמוהי חד ממש (אמנם זהו דוקא בשמות דהוי' ואלקים וכה\"ג הנז' בתושב\"כ ובנביאים וכתובים שהן משמותיו העצמיים ממש כמו שאמר כל הקורא כו' קורא בשמותיו<sup data-n=\"3389\">104</sup> כו', וגם [מע\"ב] שנתהוו מאין ליש ממש משם אלקים וגם משם הוי' כמו בראשית ברא אלקים<sup data-n=\"3390\">105</sup> ביום עשות הוי' אלקים<sup data-n=\"3391\">106</sup> כו', נחשב משמותיו העצמיים, מאחר שנז' בתושב\"כ דוקא (כמשי\"ת). והוא ענין ז' שמות שאינן נמחקין אפי' בחי' שם הכינוי כשם אדנ\"י ושם אלקים מצד פעולותיו מטעם הנ\"ל וד\"ל.\n<span data-k=\"pg\">912</span> ּ<b>והנה</b> ידוע דאורייתא מח\"ע נפקת דהיינו בחי' חכ' עילאה הקדומה שנק' חכ' העצמי' דלתבונתו אין מספר<sup data-n=\"3392\">107</sup> כלל ונק' חכים ולא בחכ' ידיעא כו', ואמנם ירד אור זה דח\"ע",[["3380","95","<b>ההתפשטות</b>: שם: ההתפעלות."],["3381","96","<b>כי אמרתי עולם חסד יבנה</b>: תהלים פט, ג."],["3382","97","<b>כו'</b>: בתו\"ח כאן מוסיף עוה\"פ התיבות: וכן אור החסד ואור הגבו'."],["3383","98","<b>בפ' בא</b>: נדפס לעיל פ' בא קיב, א ואילך."],["3384","99","<b>ז' שמות שאינן נמחקים</b>: נמנו לעיל שם. וש\"נ."],["3385","100","<b>דאיהו וחיוהי. . גרמוהי. . חד</b>: נסמן לעיל פ' יתרו עדר, א."],["3386","101","<b>אנת הוא חד ולא בחושבן</b>: ת\"ז בהקדמה (יז, א)."],["3387","102","<b>דלפני אחד מה אתה סופר</b>: ראה ס\"י פ\"א, מ\"ז. מאמרי אדה\"ז תקס\"ג ח\"ב ע' תשכב. מאמרי אדה\"א דברים ח\"ב ע' תקסג. לקמן פ' פקודי תנג, ד."],["3388","103","<b>בב'</b>: אד: בבחי'."],["3389","104","<b>כל. . קורא בשמותיו</b>: ראה פתיחת הרמב\"ן עה\"ת. הנסמן במאמרי אדה\"א דברים ח\"א ע' קלט. תו\"ח ח\"ש קלד, ב ובהערה 10."],["3390","105","<b>בראשית ברא אלקים</b>: בראשית א, א."],["3391","106","<b>ביום עשות הוי' אלקים</b>: בראשית ב, ד."],["3392","107","<b>דלתבונתו אין מספר</b>: תהלים קמז, ה."]]],[2300550278,"הקדומה בבחי' אותיות דווקא. והוא בחי' חכ'<sup data-n=\"3393\">108</sup> הקדומה שאמר ואהי' אצלו אמון<sup data-n=\"3394\">109</sup> כו', וכתיב אז ראה ויספרה בבחי' ספר<sup data-n=\"3395\">110</sup> וכמ\"ש בס\"י בג' דברים<sup data-n=\"3396\">111</sup> כו' בספר וסופר כו' וכמ\"ש זה ספר תולדות אדם<sup data-n=\"3397\">112</sup> ונק' תורת האדם כנ\"ל. דאע\"פ שמצד עצמות הא\"ס הוא למעלה מעלה מבחי' האדם כמ\"ש כי לא אדם הוא<sup data-n=\"3398\">113</sup> כו', והיינו למעלה גם מבחי' החכ' הקדומה [כו', עכ\"ז הרי נתצמצמה ונתלבשה כל בחי' פנימיות עצמותו ממש כמו שהוא באמירתו<sup data-n=\"3399\">114</sup> ממש באותיות התו' הקדומה] שנק' ספר החיים<sup data-n=\"3400\">115</sup> כו'. והיינו שהן בחי' שמות העצמיים שלו כמאמר כל הקורא בתורה קורא בשמותיו ממש, וכמ\"ש קרוב ה' לכל אשר יקראוהו באמת דתורה<sup data-n=\"3401\">116</sup> שנק' שמותיו ממש הוא אשר יקראוהו לאמיתית עצמותו ממש כו', וכמו בביטול ת\"ת אמר אין קורא בשמך<sup data-n=\"3402\">117</sup> כו' (וזהו כשם התואר שמורה על עצמותו ממש, ויותר מזה דבתואר אינו רק ציור [ו]דוגמא להורות על אמיתת[ו] ובאותיות התורה הרי נתפס מהו\"ע ית' ממש דאע\"ג דלית מח' תב\"כ, אבל מח' וחכ' דתורה נתפס בה ממש דאורייתא וקודב\"ה כולא חד<sup data-n=\"3403\">118</sup>, ונק' ג\"כ היכלא עילאה דקודב\"ה<sup data-n=\"3404\">119</sup>, וכמארז\"ל דד\"א של הלכה עכשיו במקום היכל ק\"ק ממש. ולזאת הגם שגם חכמה דתורה מאין תמצא דאיהו וחיוהי וגם גרמוהי חד ממש דהיינו גם האורות דע\"ס דאצי' שנק' בשמות כמו באותיות<sup data-n=\"3405\">120</sup> דהוי' אלקי' שנז' זה<sup data-n=\"3406\">121</sup> בתורה אע\"פ שלא נאצלו רק בבחי' אותיות ושמות (כשם ע\"ב ס\"ג ומ\"ה וב\"ן) דשם ע\"ב<sup data-n=\"3407\">122</sup> במילוי אלפי\"ן הוא לשם הוי'<sup data-n=\"3408\">123</sup> שבתורה, וכן שם ב\"ן במילוי ההי\"ן הוא בבחי' שם אלקים<sup data-n=\"3409\">124</sup> וכה\"ג) (והיינו ענין ז' שמות שאינן נמחקים כנ\"ל שהוא שם שדי צבאות שנז[כר] בתורה דהכל א' ממש). וז\"ש בס\"י דע\"ס הן כשלהבת הקשורה בגחלת<sup data-n=\"3410\">125</sup> שהוא בבחי' יחוד גמור וכך הוא בחי' התלבשות עצמות אוא\"ס ב\"ה דאצי' ביחוד גמור בהעלם ובגילוי (כשם התואר וכינוי כנ\"ל) שנק' או\"כ בכלל כידוע משום דאיהו וחיוהי חד ממש, אע\"פ שנק' שמות בלבד (דלא כדלעיל), וכ\"ז הוא שנק' בבחי' אדם כנ\"ל, כמ\"ש וזאת תורת האדם אדמה לעליון ממש לפי שכולל כל השמות וצירופי' דע\"ס דאצי' שהוא בחי' שם מ\"ה מלגאו<sup data-n=\"3411\">126</sup> דאיהו אורח כל האצי' [ו]מייחד לון ומקשר לון כו' (כמשי\"ת).\n<b>והנה</b> להבין בתוספת ביאור ענין היחוד האמיתי בחיבור וקשר ליחוד העצמות א\"ס ב\"ה בע\"ס דאצי', הנה ידוע שזהו",[["3393","108","<b>חכ'</b>: אב: תורה."],["3394","109","<b>ואהי' אצלו אמון</b>: משלי ח, ל."],["3395","110","<b>אז ראה ויספרה. . ספר</b>: איוב כח, כז. ראה גם לקמן פ' ויקהל תיח, א."],["3396","111","<b>בס\"י בג' דברים</b>: ראה שם פ\"א, מ\"א."],["3397","112","<b>זה ספר תולדות אדם</b>: בראשית ה, א."],["3398","113","<b>כי לא אדם הוא</b>: שמו\"א טו, כט."],["3399","114","<b>באמירתו</b>: א: באמיתתה."],["3400","115","<b>התו' הקדומה] שנק' ספר החיים</b>: ראה גם לעיל פ' שמות יב, ד. וש\"נ."],["3401","116","<b>קרוב. . באמת דתורה</b>: תהלים קמה, יח. ראה ירושלמי ר\"ה פ\"ג, ה\"ח. לעיל פ' שמות יא, ג הערה 513."],["3402","117","<b>אין קורא בשמך</b>: ישעי' סד, ו [ושם: ואין — ראה גם לעיל פ' בא קכה, ג. וש\"נ]."],["3403","118","<b>דאורייתא וקודב\"ה כולא חד</b>: נסמן לעיל פ' משפטים רצ, ג."],["3404","119","<b>דאורייתא. . היכלא עילאה דקודב\"ה</b>: ראה זהר ויקהל ר, ע\"א. מאמרי אדה\"א דברים ח\"ב ע' תיג."],["3405","120","<b>באותיות</b>: אב: (כ) בשמות."],["3406","121","<b>זה</b>: שם: ליתא."],["3407","122","<b>ע\"ב</b>: א: מ\"ה. ב: זה."],["3408","123","<b>מ\"ה במילוי אלפי\"ן. . הוי'</b>: ראה ע\"ח (שער לאה ורחל) של\"ח, פ\"א. פ\"ב. מאמרי אדה\"א שמות ח\"ב ע' תמה. וש\"נ."],["3409","124","<b>ב\"ן במילוי ההי\"ן. . אלקים</b>: ראה גם לעיל פ' שמות יט, ג. וש\"נ."],["3410","125","<b>כשלהבת הקשורה בגחלת</b>: ס\"י פ\"א, מ\"ז."],["3411","126","<b>שם מ\"ה מלגאו</b>: ראה ת\"ז בהקדמה (יז, א). הנסמן לעיל פ' שמות יג, ד."]]],[2300550306,"בחי'<sup data-n=\"3412\">127</sup> דמיון וקשר וחיבור הנפש בגוף בציור אדם שהרי אמר חכמה מוחא חסד דרועא ימינא<sup data-n=\"3413\">128</sup> כו' וכה\"ג שזהו בציור אדם בהתלבשות אור החכ' ומדות בכלים דוקא, וכמ\"ש אי אנת תסתלק מנייהו<sup data-n=\"3414\">129</sup> אשתארו כגופא בלא נשמתא כו', שהן בחי' הכלים בלא אורות שנק' גופא בלא נשמתא כו' (וכולל דנר\"ן דאדם הוא בחי' שם מ\"ה מלגיו כו' כנ\"ל). דהנה אנו רואים בחיבור הנפש החיוני<sup data-n=\"3415\">130</sup> בחומר גוף גשמי דבר פלא ביותר דאיך יחובר[ו] ב' הפכים כאלה רוחני בגשמי מאחר שבחי' הרוחני מושלל <span data-k=\"pg\">תנו</span> ּ בתכלית מכל בחי' תואר גשמי, וא\"כ ודאי שחיות אור הרוחני שבנפש עצמה כמו שהיא טרם בואה בגוף מושללת לגמרי מכל תואר חיות גשמי שמלובשת ומורכב בד\"י גשמי' כמו בדם ובשר הגשמי ואין ביניהם דמיון וערך כלל וכלל. כי חיות הגשמי נק' חיי בשר ודם גשמי שמחי' לגוף גשמי ואיך יהי' לה חיבור וקשר עם אור וחיות הרוחניות שבנפש עצמה עד שנאמר שהנפש עצמה ממש מלובשת בחומר גוף וכמו ואתה נפחת בי<sup data-n=\"3416\">131</sup> כו' (שהרי הנפש מתפעלת ממקרי הגוף<sup data-n=\"3417\">*132</sup> ממש שהכאב הגשמי<sup data-n=\"3418\">132</sup> בקלקול אבר ירגיש אותו ברוחניות שבנפש עצמה, וכן בהיפוך בתענוג גשמי שישמן הבשר עצמו ותתענג<sup data-n=\"3419\">133</sup> הנפש עצמה, ובצער הגוף תצטער הנפש כמו שנראה פנים ריעותא בקילותא<sup data-n=\"3420\">134</sup> בדמי' גשמיי' מצער ויגון הנפש (וכמו הלב גשמי יודע ומרגיש מרת נפשו<sup data-n=\"3421\">135</sup> ). וכן פנים צהובים ומאירים בדמים מבשורה טובה תשמח הנפש כידוע, שמזה נראה לעין שיש קשר וחיבור ממש לנפש עצמה בגוף. אע\"פ שמצד הנפש עצמה שמושללת מכל תואר חיי בשר גשמי כנ\"ל לא הי' מהראוי כלל שתתפעל ממקרי הגוף בין בטוב בין ברע כמו שהיתה קודם בואה לגוף, שא\"א לומר שהיתה מתפעלת ממקרי' גשמיי' בצער ועונג הגשמי (רק יסורים רוחניים כיסורי הגיהנם וכעונג רוחני בג\"ע כו') מאחר שמובדלת בערך מכל תוארי הגשם לגמרי). אך הנה באמת שני ההפכי' יש בנפש [בגוף] א' שמתקשרת בגוף כמו בהתקשרות עצמ[י'] להתפעל ממקרי הגוף כנ\"ל, וגם זה אמת שאינה מקושרת [כלל] בגוף בערך ויחוס ואינה מתפעלת בעצמה כלל מן מקרי הגוף. וראיה מן הגלגולים שנפש א' תתלבש בכמה מיני גופים<sup data-n=\"3422\">136</sup> שונים ומחולקים בטבעם מן הקצה לקצה כו' עד שתוכל להתגלגל גם באבן ועץ<sup data-n=\"3423\">137</sup> או בחי' ובהמה כידוע, ואין בה שינוי מהות כלל כו'.",[["3412","127","<b>בחי'</b>: אב: כמו."],["3413","128","<b>חכמה מוחא חסד דרועא ימינא</b>: ראה ת\"ז בהקדמה (יז, א)."],["3414","129","<b>אי אנת תסתלק מנייהו</b>: ראה ת\"ז שם (יז, ב)."],["3415","130","<b>החיוני</b>: אב: הרוחני."],["3416","131","<b>ואתה נפחת בי</b>: ברכת אלקי נשמה. ראה גם לעיל פ' וארא עג, ד. וש\"נ."],["3417","*132","<b>הנפש מתפעלת ממקרי הגוף</b>: ראה גם לקמן פ' תצוה שכו, ב. וש\"נ."],["3418","132","<b>שהכאב הגשמי</b>: א: שהגוף גשמי. ב: שאם הגוף גשמי."],["3419","133","<b>עצמו ותתענג</b>: שם: מתענוג."],["3420","134","<b>ריעותא בקילותא</b>: שם: רעים בלקותו."],["3421","135","<b>הלב. . יודע. . מרת נפשו</b>: משלי יד, י."],["3422","136","<b>שנפש א' תתלבש בכמה מיני גופים</b>: ראה גם שו\"ע אדה\"ז הל' ת\"ת פ\"א, ה\"ד. וש\"נ. מאמרי אדה\"א הנחות תקע\"ז ע' קפד. וש\"נ. תו\"ח נח סח, ב ובהערה 8. שע\"ת כט, א ובהערה 5. תורת מנחם — מנחם ציון ח\"ב ע' 387 ואילך. וש\"נ."],["3423","137","<b>שנפש. . להתגלגל גם באבן ועץ</b>: ראה גם לעיל פ' שמות כח, ב. וש\"נ."]]],[2300550331,"<b>ושרש</b> הענין הוא כידוע דמה שבאה הנפש בהתחברות בכלי הגוף עד שחיות<sup data-n=\"3424\">138</sup> הגוף מקבל חיותו ושפעו רק מאור וחיות [הנפש] הרוחניות והיו לאחדים ממש כנ\"ל אין זה בחי' מהותה ועצמותה של הנפש הרוחני' ממש, אלא הוא רק בחי' הארה דהארה ממנה (שנק' צלם הנפש כמ\"ש במ\"א כמ\"ש אך בצלם יתהלך איש<sup data-n=\"3425\">139</sup> כו'), שהוא רק הארתה והתפשטותה החיצוני מאד שנק' רק גילוי הארה מהארה, כמו הגילוי של התנועה בפעולה שאין זה עצם החיות שביד אלא רק גילוי הארה נבדלת בעלמא (וכמו כח הצומח הרוחני שמצמיח עשב שזהו ג\"כ התהוות גשם כמו שיש ברוחניות<sup data-n=\"3426\">140</sup> דכח הצומח ממש, שבודאי אין זה הצומח דעשב הגשמי רק בחי' הארה דהארה נבדלת מעצם הרוחניות דכח הצומח, וכמ\"ש במ\"א שזהו בחי' הממוצע שבתו'<sup data-n=\"3427\">141</sup> גשמי' שברוחניות דכח הצומח<sup data-n=\"3428\">142</sup> יעשה בחי' רוחניות הצומח בעץ<sup data-n=\"3429\">143</sup> הגשמי עד שבא בשינוי המהות לגמרי מן הרוחני' אל הגשמי כו' (וזהו שמפליא לעשות לקשר רוחניות בגשמיות<sup data-n=\"3430\">144</sup> כמ\"ש במ\"א). וכך הוא ג\"כ בחיבור וקשר אור רוחניות הנפש בחי[י] בשר בדם הוא הנפש שזהו <span data-k=\"pg\">914</span> ּ אדם, שבחי' גשמיות שברוחניות הנפש הוא שנמשך להיות בבחי' הרוחניות לחיות הגשמי שבדם שנק' ג\"כ נפש ממש כמ\"ש כי הדם הוא הנפש<sup data-n=\"3431\">145</sup> ממש עד שיש קישור וחיבור עצמי ביניהם כנ\"ל, כמו בחי' ההרגשה להתפעל בנפש עצמה מכל מקרי הגוף כנ\"ל. ובאמת אין זה קשר וחיבור אמיתי כי אין מהות הרוחני' דנפש עצמה בגוף רק בחי' אורה החיצוני' לבד שממנו מתהוה בחי' חיי בשר כמו ברביעית דם שהנפש תלוי בו<sup data-n=\"3432\">146</sup> ממש כנ\"ל<sup data-n=\"3433\">147</sup>, ע\"כ הוא בא בדילוג גדול ממהות למהות מן הרוחניות אל הגשמיות ממש וד\"ל.\n<b>והנה</b> הדוגמא מכ\"ז יובן למעלה בבחי' חיבור וקשר עצמות אוא\"ס בנאצלים כנ\"ל שזהו כמו חיבור הנפש בגוף מחיי הרוחניי' לחיי בשר בדילוג הערך [מאד] כנ\"ל, שאין שינוי כלל בעצם אוא\"ס כלל כמ\"ש אני הוי' לא שניתי<sup data-n=\"3434\">148</sup> כו' עד שאינם נתפסים במציאות כלל, ונק' ע\"ס בלי מה בלי מהות כלל, וכמ\"ש ולאו מכא\"מ כלל. שזהו כמו עצמיות הנפש שמושללת מכל תואר אור וחיות גשמי ולא תתפעל כלל ממקרי הגוף כנ\"ל, כי אין מהו\"ע אוא\"ס ב\"ה מלובש בהם רק בחי' הארה דהארה לבד שהן בחי' אותיות ושמות בע\"ב ס\"ג כו' כנ\"ל (וזהו אם צדקת מה תתן לו<sup data-n=\"3435\">149</sup> כו' וכן ולו נתכנו עלילות<sup data-n=\"3436\">150</sup> כו' כמ\"ש כי לא ראיתם כל תמונה שמובדל [מ]בחי' אדם [כ]נ\"ל). ועכ\"ז גם זה אמת הוא",[["3424","138","<b>שחיות</b>: אב: שכלי."],["3425","139","<b>אך בצלם יתהלך איש</b>: תהלים לט, ז. ראה גם לעיל פ' בשלח רו, ב. וש\"נ."],["3426","140","<b>כמו שיש ברוחניות</b>: אב: במישוש מרוחניות."],["3427","141","<b>שבתו'</b>: שם: דבחי'."],["3428","142","<b>גשמי' שברוחניות דכח הצומח</b>: ראה גם לעיל פ' בשלח קסו, א. וש\"נ."],["3429","143","<b>בעץ</b>: אב: בעשב."],["3430","144","<b>שמפליא לעשות לקשר רוחניות בגשמיות</b>: ראה רמ\"א שו\"ע או\"ח ס\"ו, ס\"א. וראה גם מאמרי אדה\"א דברים ח\"ב ע' תנו."],["3431","145","<b>כי הדם הוא הנפש</b>: פ' ראה יב, כג. ראה גם לעיל פ' בא קד, ב. וש\"נ."],["3432","146","<b>ברביעית דם שהנפש תלוי בו</b>: ראה שבת לא, סע\"ב. מאמרי אדה\"א הנחות תקע\"ז ע' ע. וש\"נ."],["3433","147","<b>כנ\"ל</b>: כ\"ה גם באב."],["3434","148","<b>אני הוי' לא שניתי</b>: מלאכי ג, ו."],["3435","149","<b>אם צדקת מה תתן לו</b>: איוב לה, ז."],["3436","150","<b>ולו נתכנו עלילות</b>: שמו\"א ב, ג."]]],[2300550356,"שיש קשר וחיבור לאוא\"ס בע\"ס דאצי' כנשמה בגוף כמ\"ש אי אנת כו', שזהו כמו חיבור אור הנפש בחיי הגוף בדילוג הערך ע\"י ממוצע כנ\"ל כקשר הרוחני' בגילוי<sup data-n=\"3437\">151</sup> כנ\"ל, מאחר שאמר חכמה מוחא חסד דרועא כו' וע\"כ אמר דאיהו וחיוהי וגרמוהי חד (דכמו שיש<sup data-n=\"3438\">152</sup> כחות הכלולים בנפש מתאחדים ביחוד עצמי עכ\"פ כך ע\"ס הגנוזות בעצמות המאציל כשלהבת הקשורה בגחלת כנ\"ל, אע\"פ דלאו מכא\"מ כלל אפי' בהעלם, אעפ\"כ נק' ע\"ס הגנוזות בעצמות כו'. כך הוא גם בהארות [האורות] הגנוזות מן ההעלם לגילוי בבחי' או\"כ שנק' גרמוהי ג\"כ חד ביחוד העצמי (כנראה לעין בקשר עצם הכחות של הנפש בעצמה כעונג וצער בעצם הרוחני' יש בנפש<sup data-n=\"3439\">153</sup> שנתפעל[ת], כמו\"כ<sup data-n=\"3440\">154</sup> ממש בפנים לרע ולטוב וכה\"ג) פי'<sup data-n=\"3441\">155</sup> חיוהי וגרמוהי או\"כ שהן שמות התואר שנק' חיוהי ושמות הכינוי והפעולה שנק' גרמוהי כנ\"ל וד\"ל). ואמנם הנה בחי' יחוד וחיבור הנה אע\"פ שאין ערוך כלל ביניהם כנ\"ל מ\"מ נק' יחוד אמיתי אף באצי' בבי\"ע (שהן אותיות דמל' דאצי' בבי\"ע) כמ\"ש כגוונא דאינון מתייחדין לעילא<sup data-n=\"3442\">156</sup> בע\"ס דאצי' אוף הכי ממש כו'. והוא לפי שגם זה עצמו הוא שנתצמצם בעצמו להיות לאח\"פ קשר וחיבור באו\"כ דבחי' אדם דוקא כמו להיות חכים ומבין באו\"כ דוקא כמו חכמה מוחא כו' שהוא בפרצוף אדם מנר\"ן [ב]ג' כלים כמוח[א] ולבא וכבדא<sup data-n=\"3443\">157</sup> בכלל כידוע. ועז\"א אי אנת תסתלק כו' ואנת ממלא כל שמהן מלבר כל ספי' ומלגיו כו' ואנת הוא דמייחד לון ומקשר לון כו', שזהו כמו בחי' התכללות שיש באדם לכל ח\"י<sup data-n=\"3444\">158</sup> אברים שלו מראש לרגל ומרגל לראש עד<sup data-n=\"3445\">159</sup> מבלי שימצא ראש וסוף<sup data-n=\"3446\">160</sup>, <span data-k=\"pg\">תנז</span> ּ להיותו בהתכללות זו דומה לעצמות המאציל שלמעלה מבחי' אדם [כמו אד\"ם] אדמה לעליון ממש שהוא עצמות המאציל שמן<sup data-n=\"3447\">161</sup> שלימותא דכולא<sup data-n=\"3448\">162</sup> ואין דבר מה שלימותו<sup data-n=\"3449\">163</sup> כו' וכמשל הרגשה כללית דנפש בכל האברים בשוה כו' (וזהו שם מ\"ה מלגיו דאיהו אורח כל האצי' שכוללם יחד ממש אעפ\"י שמצומצם<sup data-n=\"3450\">164</sup> בחי' אדם במוחא ולבא כו', יש בחי' ראש תוך סוף וימין ושמאל ואמצע אבל מתכללים ראש וסוף כא' ממש וד\"ל<sup data-n=\"3451\">165</sup>.\n<b>והנה</b> ידוע בדרך כלל שבחי' ראשית גילוי אור וחיות הנפש בגוף להתלבש בגוף בציור אדם ברמ\"ח אברים היינו בבחי' אור החכ' שבכלי המוח דוקא, שזהו עיקר נפש אדם שכולל כל מה שנמשך ממנו ומתחלק דרך גידים הדקים בכל האברים דהיינו מן המוח נמשך ללב ומן הלב לכל האברים, וא\"כ החכ' שבמוח הוא א' דאד\"ם שכולל הכל והלב נחשב פרט, ועכ\"ז",[["3437","151","<b>בגילוי</b>: אב: בגשמי'."],["3438","152","<b>שיש</b>: שם: שי'."],["3439","153","<b>יש בנפש</b>: שם: שבנפש."],["3440","154","<b>כמו\"כ</b>: ו: בע\"כ."],["3441","155","<b>פי'</b>: שם: בין."],["3442","156","<b>כגוונא דאינון מתייחדין לעילא</b>: זהר תרומה קלה, סע\"א [בדילוג]."],["3443","157","<b>מנר\"ן. . כמוח[א] ולבא וכבדא</b>: ראה אבן עזרא משפטים כג, כה. הנסמן לעיל פ' בשלח קמה, א."],["3444","158","<b>ח\"י</b>: אב: חיות."],["3445","159","<b>עד</b>: שם: ליתא."],["3446","160","<b>מבלי שימצא ראש וסוף</b>: ע\"פ קהלת ג, יא."],["3447","161","<b>שמן</b>: אב: שנק'."],["3448","162","<b>שלימותא דכולא</b>: ראה ת\"ז בהקדמה (יז, ב). עבודת הקדש ח\"א רפ\"ח."],["3449","163","<b>מה שלימותו</b>: אב: משלים אותו."],["3450","164","<b>שמצומצם</b>: שם: שמצד."],["3451","165","<b>ממש וד\"ל</b>: כנצ\"ל: ממש) וד\"ל ממש וד\"ל)."]]],[2300550376,"נק' הלב כלל לגבי האברים דפליג לכל שייפין<sup data-n=\"3452\">166</sup> כידוע. וכך יובן למעלה בראשית גילוי [ד]אור א\"ס [ב\"ה] בע\"ס דאצי' שזהו [מבחי'] החכ' [ו]למטה כמו שאמר חכ' מוחא כו', ואע\"פ שנק' חכים ולא בחכ' ידיעא כלל, עכ\"ז אף שאין ערוך כלל<sup data-n=\"3453\">167</sup> לאצי' כלל עם עצמות המאציל<sup data-n=\"3454\">168</sup> רק במקום גדולתו שם<sup data-n=\"3455\">169</sup> כו', שמצמצם א\"ע להיות נק' חכים באו\"כ דוקא כמ\"ש עביד מאנא רברבא וקרא בה גרמי' חכים כו' רק שזהו בדילוג הערך מאד לפ\"ע<sup data-n=\"3456\">170</sup>. ו[א]עפ\"כ אמר דאיהו וחיוהי וגרמוהי חד כדמיון קשר וחיבור אור וחיות הנפש בראשית [ו]כללות החיות במוח החכמה שבראש, ומשם מתפשט לכל אברי הגוף כנ\"ל שזהו שנק' [בחי'] נפש אדם כנ\"ל וד\"ל. אבל כ\"ז אינו אלא דוקא בבחי' כח<sup data-n=\"3457\">171</sup> דתורה שנק' תורת האדם העליון כנ\"ל, לפי שמדתו הוא<sup data-n=\"3458\">172</sup> פנימי' ועצמ[י]ו' כח חכמתו שמתצמצם כל עצמותו ב\"ה (כמו כח השכל בנפש שכל [ה]נפש נק' ע\"ש השכל נפש השכלית<sup data-n=\"3459\">173</sup> כו'). וע\"כ הגם שבתורה אמר והחכ' מאין תמצא במציאות אותיות וספר שנק'<sup data-n=\"3460\">174</sup> שמותיו העצמיים ממש דאורייתא וקודב\"ה כולא חד ממש, וכמ\"ש דג' קשרים הן<sup data-n=\"3461\">175</sup> כו' ישראל מתקשראן באורייתא ואוריי' בקודב\"ה פי' מתקשראן כמו בהתקשרות עצמ[י]ות כמו הנפש שמתקשר במוח החכ' להיות בבחי' נפש אדם ברמ\"ח אברים כו' עד דאיהו וחיוהי חד ממש (וע\"כ שמות שבתורה אינם נמחקים כו' כנ\"ל, וכך הוא למעלה בשמות דע\"ס דאצי' שנק' אדה\"ע כידוע).\n<b>והנה</b> זה האור הראשון ד[בחי'] ח\"ע שבמוח החכמה דהיינו בחי' החכ' שבתו' כמו שהיתה בעצמות א\"ס ב\"ה וירדה למטה להיות בבחי' חכ' מוחא כו', וזהו שנק' אדם הגדול<sup data-n=\"3462\">176</sup> דוקא, ובל' הזהר נק' אדם קדמאה<sup data-n=\"3463\">177</sup> והוא שנק' אדם הראשון<sup data-n=\"3464\">178</sup> דאדם גימט' מ\"ה, וכתיב מה שמו ומה שם בנו<sup data-n=\"3465\">179</sup> דיש אדם בתראה שהוא שם מ\"ה דבנו דא\"ק שזהו בחי' ח\"ת שנק' אדם הקטן אנפי זוטרי (כמשי\"ת). ופי' אדם הגדול לפי שהחכ' שנק' אדם גימ' מ\"ה דחכמה הוא בבחי' גידול ביותר כמו החכם הגדול שעומק חכמתו <span data-k=\"pg\">916</span> ּ מתפשט למעלה עד אין שיעור ולמטה עד אין תכלית כמו חכמת שלמה דכתיב וידבר ג' אלפים משל<sup data-n=\"3466\">180</sup>, וידבר",[["3452","166","<b>הלב. . דפליג לכל שייפין</b>: ראה זהר שלח קסא, ב. (רע\"מ) פינחס רכא, ב. אגה\"ק סל\"א. תו\"א בראשית ז, ד. לקו\"ת שה\"ש כט, ב. לא, א."],["3453","167","<b>כלל</b>: אב: ליתא."],["3454","168","<b>שאין ערוך לאצי'. . עצמות המאציל</b>: ראה גם ש\"א ט, א ובהערה 9."],["3455","169","<b>במקום גדולתו שם</b>: נסמן לעיל פ' יתרו רנט, ב."],["3456","170","<b>לפ\"ע</b>: אב: ליתא."],["3457","171","<b>כח</b>: שם: חכ'."],["3458","172","<b>שמדתו הוא</b>: שם: שהתורה היא."],["3459","173","<b>נפש השכלית</b>: ראה גם לעיל פ' בא קא, ג. וש\"נ."],["3460","174","<b>שנק'</b>: אב: אבל נק'."],["3461","175","<b>דג' קשרים הן</b>: ראה זהר אחרי עג, א. לעיל פ' שמות ב, ד. וש\"נ."],["3462","176","<b>אדם הגדול</b>: ראה יהושע יד, טו. הנסמן לעיל פ' בשלח קלח, ד."],["3463","177","<b>אדם קדמאה</b>: ת\"ז ת\"ע (קכ, א). זהר בראשית לא, ב. לד, א."],["3464","178","<b>אדם הראשון</b>: סנהדרין לז, סע\"א (במשנה). ברכות לא, א."],["3465","179","<b>מה שמו ומה שם בנו</b>: משלי ל, ד."],["3466","180","<b>וידבר ג' אלפים משל</b>: מל\"א ה, יב."]]],[2300550395,"על העצים<sup data-n=\"3467\">181</sup> [כו']. וכך הוא בבחי' החכ' דתורה בשרשה שנק' תורת האדם העליון שאין לה שיעור למעלה ולמטה בהתפשטותה כמ\"ש ארוכה מארץ מדה<sup data-n=\"3468\">182</sup> ורחבה מני ים ונק' משל הקדמוני<sup data-n=\"3469\">183</sup> כו', וע\"כ נק' אדם הגדול (וכמו במ\"ת שדיבר ה' בחכמתו העצמית שהאיר בפני מלך כענין חכמת אדם תאיר פניו באמ' אנכי כו', שזהו בבחי' [פנימי'] חכ' דא\"ס שנתצמצם באותיות הללו ונק' אדם הגדול וכנס\"י שקיבלו אור זה נק' רביא כנ\"ל). ועיקר הטעם לקריאת שם אדם הגדול הוא לפי שבחי' החכ' דבריאה<sup data-n=\"3470\">184</sup> כולל כל חיות האברים לפי שממנו מתפשט אור וחיות רוחני לכל האברים כנ\"ל, ע\"כ כל בחי' פרצוף ציור אדם החיצוני ברמ\"ח אברים נק' ע\"ש בחי' החכ' שבראש דוקא. וראי' מן [ה]הרגשה כללי' שמרגיש במוח דוקא לכל האברים בשוה (והוא שאמר בע\"ח דאור אבא הוא שורש כל האצי'<sup data-n=\"3471\">185</sup> ולמעלה יותר הוא בחי' חכמה דא\"ק שעקבו דא\"ק מסתיים בסוף העשי'<sup data-n=\"3472\">186</sup> כמו אדה\"ר שהוא<sup data-n=\"3473\">187</sup> קודם החטא ראשו בעולם הבריאה<sup data-n=\"3474\">188</sup> ורגליו בעשי' כו', והיינו שא' וכל קומה<sup data-n=\"3475\">189</sup> כו') ותורת אדם הגדול הזה דבחי' א\"ק הוא בחי' חכמה הקדומה [דתוה\"ק] כנ\"ל וד\"ל (וידוע שיש ג' מיני אדם<sup data-n=\"3476\">190</sup>, אדם פנימי במוחין דחב\"ד ואדם האמצעי בחג\"ת שהן המדות שהן ג\"כ בבחי' הגדולה<sup data-n=\"3477\">191</sup> מאד כמ\"ש לפי שכלו יהולל איש<sup data-n=\"3478\">192</sup> דשפע<sup data-n=\"3479\">193</sup> השכל והמוחין בגדולה<sup data-n=\"3480\">194</sup>, כך ערך גדולתו<sup data-n=\"3481\">195</sup> של המדות. וכך הוא במדות דח\"ע דתורה של מעלה דבחי' אדם הגדול הנ\"ל, ואדם חיצוני הוא בנה\"י שזהו אורות בכלים החיצונים שהן כמו רמ\"ח אברים דאדם שהן רמ\"ח מ\"ע כידוע. והיינו ציור אדם דכנס\"י שנק' ג\"כ אדם כמ\"ש אדם אתם<sup data-n=\"3482\">196</sup>, אתם קרוים אדם<sup data-n=\"3483\">197</sup> כו', והוא ע\"י המצות מעשיות בפו\"מ שעושים כמ\"ש ועשיתם אותם כאלו אתם עשאוני<sup data-n=\"3484\">198</sup> ברמ\"ח כו', וכתי' אלה המצות אשר יעשה אותם האדם יעשה בפ\"מ שזה כל האדם לפי שנעוץ תחלתן בסופן<sup data-n=\"3485\">200</sup> דוקא שעולה למעלה מאדם הפנימי דמוחין דחב\"ד כו', וזהו וחי בהם<sup data-n=\"3486\">199</sup> מעצמות א\"ס ב\"ה שלמעלה מבחי' אדם כו', וכמ\"ש סוף דבר כו' כי זה כל האדם<sup data-n=\"3487\">201</sup>. וכידוע במ\"ש כל הנקרא בשמי שהוא שם מ\"ה לכבודי<sup data-n=\"3488\">202</sup> בראתיו כו' אף עשיתיו לרבותא<sup data-n=\"3489\">203</sup> דסוף מעשה עלה במח' תחלה<sup data-n=\"3490\">204</sup> כידוע שהרי ע\"י שאמרו ישראל נעשה<sup data-n=\"3491\">205</sup> הי' ענין",[["3467","181","<b>וידבר על העצים</b>: מל\"א שם, יג."],["3468","182","<b>ארוכה מארץ מדה</b>: איוב יא, ט. ראה גם לעיל פ' בשלח קעג, ב. וש\"נ."],["3469","183","<b>משל הקדמוני</b>: נסמן לעיל פ' יתרו רנט, ד."],["3470","184","<b>דבריאה</b>: אב: שבראש."],["3471","185","<b>דאור אבא. . כל האצי'</b>: ראה ע\"ח (שער סדר אבי\"ע) שמ\"ז, פ\"ב."],["3472","186","<b>שעקבו דא\"ק. . העשי'</b>: ראה אגה\"ק ס\"כ (קלא, ב). הנסמן במאמרי אדה\"א ויקרא ח\"א ע' טו."],["3473","187","<b>שהוא</b>: אב: שהי'."],["3474","188","<b>ראשו בעולם הבריאה</b>: ראה ספר הגלגולים פי\"ח. לעיל פ' שמות מ, ב. וש\"נ."],["3475","189","<b>וכל קומה </b>[א: ניתוסף: לפניך]: ראה גם לעיל פ' בשלח קמו, ב."],["3476","190","<b>ג' מיני אדם</b>: ראה גם בענין אדם פנימי אמצעי וחיצון לעיל ריג, ג. וש\"נ."],["3477","191","<b>הגדולה</b>: אב: הגדלות."],["3478","192","<b>לפי שכלו יהולל איש</b>: משלי יב, ח. ראה גם לעיל פ' בשלח רמא, א."],["3479","193","<b>דשפע</b>: אב: לפ\"ע."],["3480","194","<b>בגדולה</b>: שם: בגדלות."],["3481","195","<b>גדולתו</b>: שם: גדלות."],["3482","196","<b>אדם אתם</b>: יחזקאל לד, לא."],["3483","197","<b>אתם קרוים אדם</b>: יבמות סא, א. ראה גם לעיל פ' יתרו רסב, א. וש\"נ."],["3484","198","<b>ועשיתם אותם כאלו אתם עשאוני</b>: ראה הנסמן לעיל רנט, ד."],["3485","200","<b>שנעוץ תחלתן בסופן</b>: ראה ס\"י פ\"א, מ\"ז."],["3486","199","<b>אלה המצות אשר יעשה אותם האדם. . וחי בהם</b>: חיבור ב' כתובים בחוקותי כז, לד. אחרי יח, ה. ראה גם הנסמן לעיל פ' בשלח קעה, ד."],["3487","201","<b>סוף דבר. . כל האדם</b>: קהלת יב, יג."],["3488","202","<b>כל הנקרא בשמי. . לכבודי</b>: ישעי' מג, ז [ושם: ולכבודי — ראה גם מאמרי אדה\"א דברים ח\"א ע' שיח. וש\"נ]."],["3489","203","<b>אף עשיתיו לרבותא</b>: נסמן לעיל פ' יתרו רנב, ד."],["3490","204","<b>דסוף מעשה עלה במח' תחלה</b>: ע\"פ פיוט לכה דודי."],["3491","205","<b>ע\"י שאמרו ישראל נעשה</b>: ראה שבת פח, א."]]],[2300550412,"סיבת הירידה שירד ה' עליהם<sup data-n=\"3492\">206</sup> כו' והיינו ענין הג' קשרים דישראל ואורייתא וקודב\"ה כידוע וד\"ל).\n<b>והנה</b> כ\"ז הוא בחי' אדם הגדול שנק' אנפי רברבי (והוא בחי' ח\"ס דא\"א שנק' אריכא דאנפין שמשם מקור גילוי אור החכ' דתורה מאין ליש [ב]חכ' דאצי' ומדות באו\"כ בציור אדם) (גם בז\"א דאצי' שהן מדות דחג\"ת ונה\"י כו' משום <span data-k=\"pg\">תנח</span> ּ דאיהו וחיוהי וגרמוהי חד באצי' מפני שהכל מתייחדים שם באור א\"ס המאיר בקו\"ח שעובר כל האצי') וזהו שנק' תורת האדה\"ע שהוא בחי' אדם הגדול הנ\"ל. אבל יש עוד בחי' אדם שנק' אדם תתאה בחי' אנפי זוטרי כאדם קטן בשנים כרביא כנ\"ל, דאע\"פ שגם הוא נק' אדם ממש, אבל אין לו ערך כלל לגבי בחי' אדם הגדול הנ\"ל. ועז\"א מ\"ה שמו מ\"ה שם בנו [כבן] הקטן ששכלו ומדותיו מצומצמים ביותר מתחילת הבריאה בתכלית הקטנות, ואין לו ערך כלל לגבי אדם הגדול שחכמתו ומדותיו גדולים בתכלית הגדלות במקור החכ' למעלה מעלה כזקן שקנה חכמה<sup data-n=\"3493\">207</sup> כו'. שבודאי כאשר צריך האדם<sup data-n=\"3494\">208</sup> הגדול שנק' אדם הגדול לדבר עם הנער ורביא שנק' אדם קטן שצריך להשפיל יותר<sup data-n=\"3495\">209</sup> ולצמצם א\"ע ביותר מכפי מדת הצמצום מחכם גדול לחכם קטן היינו כרב לתלמידו וכה\"ג כו', דהשפעת הרב לתלמיד [י]ש ערך ויחוס ביניהם בעצם החכ' שגם התלמיד מבין בחכמה זו רק שהרב מבין וחכם גדול ממנו להאיר עינו במה שלא יוכל להבין מדעתו. אבל הנער הקטן הרי שכלו קטן מאד בעצם מצד התולדה שא\"א לו להשיג כלל בשכל וחכ' רק כפי ערכו המצומצם בלבד, וכמו\"כ מדותיו הם בקטנות מאד בעצם לפ\"ע קטנות המוחין בעצם. וא\"כ אור ושפע החכ' והשכל וגם המדות שהן בבחי' גדלות החכמה אי[ך] יוכל הנער הקטן בשנים לקבל אף מבחי' דיבור של הרב שמצמצם השכל שבמוח החכ' בגילוי אותיות הדבור שאין זה [מ]ערכו כלל, אלא צריך האב החכם לצמצם אור שכלו ומדותיו לגמרי אף בדבור רק כפי ערך השכל ומדות [של] התינוק לבד, שצמצום זה הוא בא בשינוי המהות לגמרי הרבה יותר מצמצום אור השפע[ת] השכל לתלמיד שבא בגילוי בדבור שיש לו ערך כנ\"ל.\n<b>ולפי\"ז</b> יש להבין בנמשל מכ\"ז למעלה בבחי' אדם הגדול העליון דאצי' בבחי' מקור החכ' ומדות בגדלות המוחין ומדות שיורד עד בחי' מל' דאצי' שהוא בחי' ה'",[["3492","206","<b>עליהם</b>: אב: על ה\"ס."],["3493","207","<b>כזקן שקנה חכמה</b>: נסמן לעיל פ' משפטים ש, ב."],["3494","208","<b>האדם</b>: אב: החכם."],["3495","209","<b>יותר</b>: שם: ליתא."]]],[2300550429,"אחרונה<sup data-n=\"3496\">210</sup> דשם הוי' בה\"א ברא\"ם<sup data-n=\"3497\">211</sup> כו' מאין ליש באות יו\"ד<sup data-n=\"3498\">212</sup> הדבור העליון, וכמ\"ש בס\"י וקבען בפה<sup data-n=\"3499\">213</sup> כו' שהוא בחי' הגילוי מן ההעלם דע\"ס דאצי' בכלל, ובפרט זהו בתורה<sup data-n=\"3500\">214</sup> שנק' ח\"ת חכמה בסוף שזהו הארת אור השכל וחכ' ומדות שבאים בגילוי באותיות הדבור דיו\"ד מאמרות כמו במאמר יהי אור<sup data-n=\"3501\">215</sup> יהי רקיע<sup data-n=\"3502\">216</sup> כמ\"ש<sup data-n=\"3503\">217</sup> בדבר ה' שמים נעשו<sup data-n=\"3504\">218</sup> כו'. ולפ\"ז התהוות בע\"ג דעולם הבריאה כשרפים וחיות הקדש שנתהווה מרוח פיו ית' מהבל הדבור שכללותו בחי' שנק' יח\"ת<sup data-n=\"3505\">219</sup> שהוא חכ' שבדיבור (והוא בחי' אדם תתאה, שזהו כמשל התלמיד שמקבל מאור אבא<sup data-n=\"3506\">220</sup> מחכ' שבדבור [שלו] כנ\"ל), ואיך יוכל להיות התהוות בע\"ג מכח אלקי הבלתי בע\"ג אף בחכמה שבדבור, מאחר דאמר דאיהו וחיוהי חד כו'. והגם שנק' גם זה האור [דחכ'] שבדיבור בבחי' אנפי זוטרי לגבי בחי' גדלות החכ' שבראש שנק' אנפי רברבי כנ\"ל, עכ\"ז מתייחסים ומתאחדי' כא' אף בהארת ח\"ת בעולמות הנפרדים כמ\"ש בזהר ע\"פ חכמות בחוץ תרונה דח\"ע אתמשך בח\"ת<sup data-n=\"3507\">221</sup> והיו לאחדים ממש, אוף הכי אתייחדת<sup data-n=\"3508\">222</sup> כו'. ובחי' פני אדם שבמרכבה <span data-k=\"pg\">918</span> ּ הוא בחי' תכלית הקטנות במוחין ומדות בעצם כנ\"ל, וכתיב על הכסא דמות כמראה אדם<sup data-n=\"3509\">223</sup> שהוא בחי' אנפי רברבי לגבי העולמות והמרכבה העליונה אף שאינו רק בחי' אנפי זוטרי לגבי בחי' החכ' שבראש, מ\"מ יש יחוס וערך ביניהם כנ\"ל שהרי אותו השכל שבמוח החכמה שמשכיל לעצמו ישפיע אותה בכלי הדבור למקבל באותיות ואין בו רק שינוי המהות דרך הצירופים שבדבור, אבל הן מתאחדי' ממש כנ\"ל, משא\"כ מחכ' שבדיבור לגבי הנבראים בע\"ג<sup data-n=\"3510\">224</sup> כמו מרכבה דפני שור כו', אע\"פ שפני אדם לארבעתן אין לזה ערך כלל וכלל לגבי בחי' דמות כמראה אדם שעל הכסא כנ\"ל וד\"ל, וא\"כ איך יש ערך ויחוס להיות חיות הקדש נושאות את הכסא<sup data-n=\"3511\">225</sup>, וכמ\"ש אד' בם<sup data-n=\"3512\">226</sup> ממש כו' וד\"ל. וצריך לומר שבודאי יש בחי' צמצום גדול [בין] האור האלקי דבחי' אותיות הדבור דמל' דאצי' בין העולמות [וה]נבראים, וכידוע בע\"ח שיש מסך מפסיק בין האצי' לבריאה<sup data-n=\"3513\">227</sup> ודרך בקיעת המסך הוא שנעשה מקור לעולמות שזהו בחי' הארה דהארה לבד (כנ\"ל במשל חיות הגוף מן הנפש כו' שע\"ז א[מר] ג\"כ מסט' דשכי[נתא] לא ראיתם כל תמונה<sup data-n=\"3514\">228</sup> כו'), והוא בחי' אדם שעל הכסא [ד]עולם הבריאה כו' שממנו נמשך השפעה לבחי' ו\"ק דבריאה שהוא בחי' נער מט\"ט<sup data-n=\"3515\">229</sup> שנק' שרו ש\"ע<sup data-n=\"3516\">230</sup> בכלל[ות] כמ\"ש בזהר ע\"פ אנוש כחציר<sup data-n=\"3517\">231</sup> כו'. ובדרז\"ל ע\"פ נער הייתי גם זקנתי<sup data-n=\"3518\">232</sup>",[["3496","210","<b>מל'. . ה' אחרונה</b>: ראה זהר ויקרא יז, א. תו\"ח ויצא קסז, ג הערה 38."],["3497","211","<b>בה\"א ברא\"ם</b>: ראה מנחות כט, ב. ב\"ר פי\"ב, ב."],["3498","212","<b>באות יו\"ד</b>: אב: באותיות."],["3499","213","<b>וכמ\"ש בס\"י וקבען בפה</b>: ראה שם פ\"ב, מ\"ג."],["3500","214","<b>בתורה</b>: אב: בחי'."],["3501","215","<b>יהי אור</b>: בראשית א, ג."],["3502","216","<b>יהי רקיע</b>: שם א, ו."],["3503","217","<b>יהי רקיע כמ\"ש</b>: אב: וכה\"ג וכמ\"ש."],["3504","218","<b>בדבר ה' שמים נעשו</b>: תהלים לג, ו."],["3505","219","<b>שכללותו. . יח\"ת</b>: אב: שכללות נק' בחי' ח\"ת."],["3506","220","<b>מאור אבא</b>: שם: מרבו."],["3507","221","<b>חכמות בחוץ. . בח\"ת</b>: משלי א, כ. ראה זהר תולדות קמא, ב. מאמרי אדה\"א בראשית ע' קכג. וש\"נ."],["3508","222","<b>אוף הכי אתייחדת</b>: ראה זהר תרומה קלה סע\"א."],["3509","223","<b>על הכסא דמות כמראה אדם</b>: יחזקאל א, כו [ושם: ועל דמות — ראה גם לעיל פ' שמות כח, ג. וש\"נ]."],["3510","224","<b>בע\"ג</b>: אב: ליתא."],["3511","225","<b>חיות הקדש נושאות את הכסא</b>: ראה בחיי תרומה כה, י בשם הפדר\"א ספ\"ד. הנסמן במאמרי אדה\"א בראשית ע' שעג."],["3512","226","<b>אד' בם</b>: תהלים סח, יח."],["3513","227","<b>מסך מפסיק בין האצי' לבריאה</b>: ראה ע\"ח (שער דרושי אבי\"ע) שמ\"ב, פ\"ד. מאמרי אדה\"א דברים ח\"ג ע' תתפא. וש\"נ."],["3514","228","<b>מסט' דשכי[נתא]. . תמונה</b>: ראה גם לעיל פ' יתרו רסה, א. וש\"נ."],["3515","229","<b>דבריאה. . מט\"ט</b>: ראה גם לעיל פ' בא קכב, ג. וש\"נ."],["3516","230","<b>מט\"ט שנק' שרו ש\"ע</b>: נסמן בהערה 232."],["3517","231","<b>בזהר ע\"פ אנוש כחציר</b>: נסמן לעיל פ' משפטים רצב, ג הערה 318."],["3518","232","<b>נער הייתי גם זקנתי</b>: תהלים לז, כה. ראה יבמות טז, ב ובתוס' שם. לעיל פ' בשלח רא, ד. וש\"נ."]]],[2300550445,"[זהו] <b>שרו</b> ש\"ע אמרו ונק' נער בחי' רביא אנפי זוטרי לגבי בחי' אדם שעל הכסא כו' שהוא מבחי' הארת מל' דאצי' בבריאה, וכמו שרמזו רז\"ל קוב\"ה בלילה מאי עביד רוכב<sup data-n=\"3519\">233</sup> על כרוב קל [שלו] ושט בח\"י אלף עולמות דזה בחי' נער מט\"ט שנק' כרוב<sup data-n=\"3520\">234</sup> קל כרביא כלומר אדם קטן כו'), והוא בלילה היינו בבחי' הצמצום והסתר דמל' במדת לילה שאז בחי' עלי' דמדת המל' באצי' ע\"י הכרוב קל שהוא בחי' מדות דבריאה שהוא באותיות המחשבה שצמצם האורות דמדות שבלב ומעלה למעלה ברצון העצמי שנק' כתר שלמעלה מן החכמה כו'.\n<b>(וביאור</b> הדברים שזה הוא<sup data-n=\"3521\">235</sup> מ\"ש בזהר דאתוון אתגליפו<sup data-n=\"3522\">*236</sup> כו' כחקיקה לחקיקה, כמו אותיות הכתב שמצ[ו]ייר בצורת שנים ומצורף<sup data-n=\"3523\">236</sup> שני' לשלישית כו'), ולזאת יוכל להיות שיקבלו המרכבה דפני ארי' ושור כו' מבחי' אדם שעל הכסא (ע\"י בחי' נער מט\"ט (כמו בא[ד]ה\"ר שקיבלו ממנו כל החיות ובהמות להיות כולל כולם וממנו מסתעפי'), ומ\"ש וברוח פיו כל צבאם<sup data-n=\"3524\">237</sup> היינו שמתהוים רק מהבל הדיבור דאדם שעל הכסא שבא בדילוג הערך מן מגליפו' הנ\"ל<sup data-n=\"3525\">238</sup> האותיות כנ\"ל). אך הנה אע\"פ שבהשתלשלו' העולמות כמו מאצי' לבריאה ויצי' כו', והוצרך להיות ע\"י צמצום המסך כנ\"ל (וגם ע\"י צמצום דקטנות המדות דנער מט\"ט דברי' כנ\"ל), אבל בירידה והשתל' דתורה מעצמות אור א\"ס באבי\"ע עד תורה הנגלית לנו בעוה\"ז באותיות הכתב ובאותיות הדבור אין בזה שום שינוי המהות ובלא צמצום והעלם והסתר כלל וכלל. ואף לא בצמצום השכל שבמוח שמתצמצם בדיבור <span data-k=\"pg\">תנט</span> ּ לתלמיד כנ\"ל, אלא כמו שהוא במשפיע במקור החכ' שבראש כך הוא במקבלי' ממש בלי שום שינוי כלל וכלל, ואף ש[ה]מקבל הוא כנער קטן בשנים שאין לו ערך כלל וכלל לגבי אדם הגדול. וראי' ממ\"ת שהי' האור והשפע דבחי' פנימי' ח\"ע דתורה הקדומה שבבחי' אדם הגדול כנ\"ל יורד ונמשך לבנ\"י המקבלים ביו\"ד הדברות דאנכי כו' ששמעו מפי הגבורה<sup data-n=\"3526\">239</sup> בלי שום צמצום והעלם והסתר כלל וכלל עד שעל כל דיבור<sup data-n=\"3527\">240</sup> כו' כמ\"ש קול אלקים אתם שומעים<sup data-n=\"3528\">241</sup> כו'. ואע\"פ שכנ\"י במוחין ומדות שלהם היו בתכלית הקטנות מאד כערך נער ורביא בחי' אנפי זוטרי, ומ\"מ מתקבל בהן אור דתורה גם לדורות הבאים כידוע. לפי דצמצם הקב\"ה עצמו ביותר בדבר",[["3519","233","<b>קוב\"ה בלילה מאי עביד רוכב</b>: ראה ע\"ז ג, ב."],["3520","234","<b>מט\"ט שנק' כרוב</b>: נסמן לעיל רצב, ג הערה 312."],["3521","235","<b>הדברים שזה הוא</b>: א: הדבר שזהו. ב: הדבר שזה הוא. הו: הדבר ידוע שזהו."],["3522","*236","<b>דאתוון אתגליפו</b>: ראה זהר בראשית טו, ב. שעה\"י קמא, ב הערה 46."],["3523","236","<b>בצורת שנים ומצורף</b>: א: בצור' שני' ומצורה. ב: בצורות שני' ומצור'. הו: בצורה שני' ומצורה."],["3524","237","<b>וברוח פיו כל צבאם</b>: המשך הכתוב בדבר ה' שמים נעשו — לעיל הערה 218."],["3525","238","<b>מן מגליפו' הנ\"ל</b>: אב: מגליפ' הנ\"ל. הו: בגליפות."],["3526","239","<b>ביו\"ד הדברות. . ששמעו מפי הגבורה</b>: ראה תנחומא יתרו יא."],["3527","240","<b>שעל כל דיבור</b>: שבת פח, ב."],["3528","241","<b>קול אלקים אתם שומעים</b>: ואתחנן ד, יב [ושם: וידבר ה'. . קול דברים]."]]],[2300550460,"עמהם, כאשר ידבר האב הגדול בחכמה עם בנו הקטן ורך בשנים שמלביש הדבר חכמה בענינים פשוטים שיהי' מבין התינוק לפי שכלו הקטן ויהי' לו לטובתו וקיומו בנפשו וגופו כל הימים כמו שמע בני מוסר אביך<sup data-n=\"3529\">242</sup> כו', שהן דרכי החיים בסומ\"ר וע\"ט דגשמיות. ואע\"פ שיש בזה צמצום והעלם גמור בהלבשה זו כהתלבשות השכל במשל וכה\"ג, מ\"מ אין בזה האור דתורה שינוי המהות כלל מכמו שהי' במקורו העצמי'. (וראי' לזה ממה שאמר דמשה קיבל תורה מסיני<sup data-n=\"3530\">243</sup> ומסרה ליהושע ויהושע לזקנים כו', בדור אחר דור עד דור האחרון גם בכל מה שתלמיד ותיק עתיד לחדש<sup data-n=\"3531\">244</sup> ניתן למשה כו' בלי שינוי כלל, וכמו שאמר<sup data-n=\"3532\">245</sup> שפיר קאמרת<sup data-n=\"3533\">246</sup> כאלו אמרה משה, וכך הוא בכל מי שיושב וקורא<sup data-n=\"3534\">247</sup> דבר ה' זו הלכה<sup data-n=\"3535\">248</sup>, הרי הקב\"ה יושב ושונה כנגדו ממש כמ\"ש ואשים דברי בפיך<sup data-n=\"3536\">249</sup> כו' בלי שינוי המהות כלל לפי שהוא דבריו ממש כמו במ\"ת שהי' מדבר בעצמו עמהם בבחי' פב\"פ, אע\"פ שאין ערוך כלל ביניהם.\n<b>ויש</b> בזה ב' טעמים א' מצד ההשפעה דאור דתורה ש\"מ<sup data-n=\"3537\">250</sup> בכמה מיני לבושים והעלמות רבות מאד ולא ישונה אורה כלל. לפי שאין כל הצמצומים דאבי\"ע מחשיך אור דתורה כלל גם [בחי' המסך שבין אצי' לבריאה ומבריאה ליצי' כמו שירד ה' על ה\"ס באש הוי' מבלי העלם והסתר כלל, גם] בבא התלבשות חכמה דתורה בענינים גשמיים דנוגה בנשמות שמלובשים בגופים שנק' תורת ה'<sup data-n=\"3538\">251</sup> ומצות ה'<sup data-n=\"3539\">252</sup> ממש כמו במצות תפילין שבראש א' כי שם ה' נקרא עליך<sup data-n=\"3540\">253</sup>. וכן באו\"מ דטלית ול\"ב חוטין דציצית ובמצות סוכה בהמשכת אור מקיף<sup data-n=\"3541\">254</sup> שאין בכל זה שינוי באור העצם כלל וכלל, וכמו שהוא בתו\"מ העליונה שנק' תורותיו ומצותיו וחוקותיו כו' להיות למעלה מההשתלשלו' דקו וחוט הנמשך באצי' עד סוף העשי' רק באה התורה שמ\"ע בהתלבשות דאצי' ונק' תורה דאצי' (כמו הקב\"ה שהוא בחי' ז\"א<sup data-n=\"3542\">255</sup> יושב ועוסק בתורה<sup data-n=\"3543\">256</sup> וכן יושב ושונה כנגד אדם למטה הכל בשוה). ואע\"פ שבמ\"ת ירד הוי' ג\"כ עם המרכבה<sup data-n=\"3544\">257</sup> עליונה שנק' רכב אלקי' רבותיי'<sup data-n=\"3545\">258</sup> כו' סיני בקדש זהו בחי' מרכבה דאותיות התורה דוקא וכמ\"ש ואתא מרבבות קדש<sup data-n=\"3546\">259</sup> כו', וזהו כי תרכב על סוסיך<sup data-n=\"3547\">260</sup> כו' כמ\"ש במ\"א). ואע\"פ שאמר חכמות בחוץ דוקא<sup data-n=\"3548\">261</sup> ג\"כ ע\"י<sup data-n=\"3549\">262</sup> חכ' דתורה הקדומה שנק' ח\"ע בכלל שנמשך",[["3529","242","<b>שמע בני מוסר אביך</b>: משלי א, ח."],["3530","243","<b>דמשה קיבל תורה מסיני</b>: אבות רפ\"א."],["3531","244","<b>בכל מה. . עתיד לחדש</b>: נסמן לעיל פ' יתרו רנג, ד."],["3532","245","<b>שאמר</b>: אב: משה."],["3533","246","<b>משה שפיר קאמרת</b>: ראה גם לעיל פ' שמות י, ב. וש\"נ."],["3534","247","<b>בכל מי שיושב וקורא</b>: ראה תדא\"ר רפי\"ח. לעיל פ' וארא נח, ג הערה 18."],["3535","248","<b>דבר ה' זו הלכה</b>: עמוס ח, יב. שבת קלח, ב."],["3536","249","<b>ואשים דברי בפיך</b>: ישעי' נא, טז."],["3537","250","<b>ש\"מ</b>: אב: שמ\"ע של מעלה."],["3538","251","<b>תורת ה'</b>: בא יג, ט."],["3539","252","<b>ומצות ה'</b>: ויקרא ד, ב. יג. כב. ועוד."],["3540","253","<b>כי שם ה' נקרא עליך</b>: תבוא כח, י."],["3541","254","<b>אור מקיף</b>: אב: אורות מקיפים העליונ'."],["3542","255","<b>הקב\"ה שהוא בחי' ז\"א</b>: ראה סידור שער התפילין ז, ג. תו\"ח נח סט, א הערה 1."],["3543","256","<b>הקב\"ה. . יושב ועוסק בתורה</b>: ע\"ז ג, ב."],["3544","257","<b>שבמ\"ת ירד הוי' ג\"כ עם המרכבה</b>: ראה פסיקתא דר\"כ פסקא יב (בחדש השלישי) ד\"ה אנכי ה\"א (הא') ובהנסמן שם."],["3545","258","<b>רכב אלקי' רבותיי'</b>: תהלים סח, יח."],["3546","259","<b>ואתא מרבבות קדש</b>: ברכה לג, ב [בלקו\"ת ר\"פ ברכה ואתה, אבל ראה שם שה\"ש ה, ב — ראה הנסמן במאמרי אדה\"א בראשית ע' כב]. ראה מאמרי אדה\"ז תקס\"ח ח\"א ע' תקכז. לקו\"ת ברכה צג, ג ואילך."],["3547","260","<b>כי תרכב על סוסיך</b>: ראה גם לעיל פ' בשלח קסט, סע\"א ואילך. וש\"נ."],["3548","261","<b>דוקא</b>: אב: כו' דקאי."],["3549","262","<b>ע\"י</b>: שם: על."]]],[2300550475,"בח\"ת באותיות הדבור ובאותיות הכתב כמו בלוחות בארון בהיכל ק\"ק עד שנמשך בדבור דתורה<sup data-n=\"3550\">263</sup> באנפי זוטרי <span data-k=\"pg\">920</span> ּ דנש\"י בגופים גשמיים, אבל אין בזה שום שינוי במהות כלל, אף שבא מתכלית הגדלות דח\"ע לתכלית הקטנות דח\"ת שבתורה הנגלית לנו לעשות בפו\"מ. וראי' לזה ממה שאמר דצמצם שכינתו בין ב' בדי [ה]ארון<sup data-n=\"3551\">264</sup> דוקא מצד בחי' אור כתר דחכ' דתורה שבארון ולוחות כו', ואע\"פ ששמים ושמי השמים [טה\"ע וטה\"ת]<sup data-n=\"3552\">265</sup> לא יכלכלוהו<sup data-n=\"3553\">266</sup> רק ע\"י צמצומים רבים בקו\"ח כנ\"ל עכ\"ז הרי גילוי אור העצמות דא\"ס ב\"ה ממש הי' שורה בין ב' בדי הארון מטעם הנ\"ל וד\"ל.\n<b>והטעם</b> הב' בענין זה מצד בחי' המקבלים שהן כנס\"י דגם שהן בבחי' נער ורביא אנפי זוטרי מאד, מ\"מ מצד שנק' בנים לה' וכמ\"ש כי אתה אבינו<sup data-n=\"3554\">267</sup> כו' הרי יש בהם גם בבחי' הקטנות דאדם שלהם מעין ודוגמא ממש לבחי' אדם הגדול בחי' אנפי רברבי הנ\"ל, כמו שאנו רואים ש[מהות] מוח ומדות הבן קרובים אל החכמה ומדות דאביו אע\"פ שאין ערך ביניהם כלל כנ\"ל. והוא בחי' אדם אשר יכול לקבל מעצמות אוא\"ס שבחכ' ומדות דתוה\"ק הנ\"ל בלי שינוי המהות כלל כמו במ\"ת וגם עכשיו בכל לימוד תורת ה' ועושה מצות הוי' כנ\"ל. וראי' לזה ממה שאמר למשה וארא אל אברהם<sup data-n=\"3555\">268</sup> כו' ושמי הוי' לא נודעתי להם שזהו שמי הוי' העצמי' ממש אשר בתו\"מ שנק' שמותיו ממש בבחי' שם התואר כנ\"ל לפי שלא קיימו התו' ומצות בפו\"מ. ואע\"פ שהאבות הן המרכבה<sup data-n=\"3556\">269</sup> [ממש] שהוא כמו בחי' פני ארי' ופני שור ופני נשר<sup data-n=\"3557\">270</sup> שהן ג' מדות דאוי\"ר ורחמים דאבות (והן ג' תפלות דכל יום וג' רגלים<sup data-n=\"3558\">271</sup> כנ\"ל<sup data-n=\"3559\">272</sup> ) וכתיב בהן ופני אדם לארבעתן כו', מ\"מ לא נק' בבחי' שם מ\"ה דאדם הגדול שהוא שמו הוי' ממש רק ת\"ר אלף דנש\"י במ\"ת שהיו בבחי' התכללות כאיש א' כמ\"ש ויחן ישראל<sup data-n=\"3560\">273</sup> כו'. ומצד בחי' התכללות של ד' דגלים שהן י\"ב צירופי' דשם הוי'<sup data-n=\"3561\">274</sup> דוקא ונק' אז צבאות הוי' ממש כו', ע\"כ יכלו לקבל התושמ\"ע מפי הגבורה ממש פב\"פ בלי שינוי המהות כלל שלא זכו האבות מטעם הנ\"ל (כמבואר בפ' משפטי' באריכות<sup data-n=\"3562\">275</sup> ) (כמו המלאכים שבקשו הוד דתורה<sup data-n=\"3563\">276</sup> ולא ניתנה להם אף לבחי' נער מט\"ט שנק' אנפי זוטרי כנ\"ל<sup data-n=\"3564\">277</sup> בכלל שכולל כולם<sup data-n=\"3565\">278</sup> ונק' כרוב קל כו' כנ\"ל ה\"ז בא<sup data-n=\"3566\">279</sup> בצמצומי' רבים מאד בקטנות האמיתי בשינוי המהות לגמרי כנ\"ל וד\"ל) (וזהו מ\"ש מ\"ה שמו ומ\"ה שם בנו דוקא",[["3550","263","<b>דתורה</b>: שם: דד\"ת."],["3551","264","<b>דצמצם שכינתו. . [ה]ארון</b>: ראה ב\"ר פ\"ד, ד. הנסמן במאמרי אדה\"א בראשית ע' קכט. שה\"א ז, א הערה 12."],["3552","265","<b>ששמים ושמי השמים [טה\"ע וטה\"ת]</b>: ראה מאמרי אדה\"א שמות ח\"ב ע' שצה וש\"נ. לעיל פ' בשלח קעח, ג. וש\"נ."],["3553","266","<b>ששמים ושמי השמים. . לא יכלכלוהו</b>: ע\"פ מל\"א ח, כז."],["3554","267","<b>כי אתה אבינו</b>: ישעי' סג, טז."],["3555","268","<b>וארא אל אברהם</b>: וארא ו, ג."],["3556","269","<b>שהאבות הן המרכבה</b>: נסמן לעיל פ' יתרו רנא, ג."],["3557","270","<b>שהאבות. . ארי'. . שור. . נשר</b>: ראה לעיל פ' משפטים רפו, ד. וש\"נ."],["3558","271","<b>ג' תפלות. . וג' רגלים</b>: ראה גם לעיל פ' בא צד, ב. וש\"נ."],["3559","272","<b>כנ\"ל</b>: ב: כו'."],["3560","273","<b>ויחן ישראל</b>: יתרו יט, ב וברש\"י שם [ושם: ויחן שם ישראל — ראה הנסמן לעיל פ' שמות יד, א]."],["3561","274","<b>ד' דגלים שהן י\"ב. . הוי'</b>: ראה גם לעיל פ' שמות כ, ג. וש\"נ."],["3562","275","<b>כמבואר בפ' משפטי' באריכות</b>: ראה לעיל רפז, א."],["3563","276","<b>המלאכים שבקשו הוד דתורה</b>: תהלים ח, ב. שבת פח, ב. ראה גם לעיל פ' בא קיח, ד."],["3564","277","<b>כנ\"ל</b>: אב: ליתא."],["3565","278","<b>מט\"ט. . שכולל כולם</b>: ראה גם לעיל רצב, ג. וש\"נ."],["3566","279","<b>בא</b>: אב: כמו."]]],[2300550490,"שהן ישראל שיכולים לקבל משם מ\"ה העצמות והוא ע\"י משה מ\"ה שמו<sup data-n=\"3567\">280</sup>, ובכלל היינו שם האדם<sup data-n=\"3568\">281</sup> קדמאה דח\"ע שמאיר באדם תתאה שהן נש\"י שנק' צבאות הוי' גם בכל דור ודור מטעם הנ\"ל. וע\"כ אמר למה תתעינו<sup data-n=\"3569\">282</sup> כו' שוב למען עבדיך שבטי נחלתיך דוקא [שנק'] שבטי י\"ה כמ\"ש ששם עלו שבטים<sup data-n=\"3570\">283</sup> כו' עדות לישראל שהוא עדות דתורה כמ\"ש ויקם עדות ביעקב<sup data-n=\"3571\">284</sup> ותורה שם בישראל דוקא דג' קשרים הן כנ\"ל וד\"ל).\n<b>ואחר</b> כ\"ז יובן כללות ענין כרובי' שהיו במקדש דכתי' ונועדתי לך שם ודברתי אתך כו' מבין שני הכרובי' דוקא שזהו כמו שצמצם שכינתו בין ב' בדי הארון כנ\"ל, כך הי' מדבר עם משה מבין [ב'] הכרובים, דענין ב' <span data-k=\"pg\">תס</span> ּ הכרובים הוא כמו רביא ונער שהי' ציורם פני אדם קטן. והוא ענין ירידת האור דח\"ע דתוה\"ק שבעצמות א\"ס ממש שירד למטה להאיר ולהתלבש בבחי' אנפי זוטרי דכרוב (כמו רוכב על כרוב כו') לפי צמצום כלי המקבל שהן נשמה בחי' נער קטן, לפי שהארה זו מצומצמת מאד בקטנות המוחין בעצם שאין לו ערך כלל לגבי גדלות החכמה דאדם הגדול כו', כמו צורת רבי' לגבי אדם הגדול בענקים כו', יותר משאין ערך לחכמה שבדיבור לגבי עצם החכ' שבראש. מ\"מ הוא אותו השכל והחכמ' עצמי', אבל מצומצמת באותיות לבד אבל אין<sup data-n=\"3572\">285</sup> ערך חכמה דרביא כלא חשיב ואינו ממהות חכם גדול כלל, וצריך שיומשך ויתלבש בקטנות המוחין מאד לפ\"ע צמצום שכל הרביא. אך עכ\"ז הי' אור דח\"ע דתורה מאיר בח\"ת דהיינו ע\"י הכרובים בלי שינוי [ה]מהות כלל וכלל<sup data-n=\"3573\">286</sup> כמ\"ש ונועדתי לך בעצמי כו', ודברתי אתך מבין שני הכרובים שהי' קול ודבור זה שמבין ב' הכרובים קול ה' שלמעלה בחכ[\"ע] דאצי' ולמעלה מעלה בחכ' דעצמות א\"ס ב\"ה ממש בלי העלם והסתר כלל, כמו שהי' במ\"ת ממש כמ\"ש וישמע את הקול<sup data-n=\"3574\">287</sup> מעל הכפורת מבין ב' הכרובים וידבר אליו כו', והיינו מטעם כל הנ\"ל כהפרש שבין אור חכ' דתורה לחכ' דאצי' בבי\"ע וגם מצד בחי' המקבל[ים] כנ\"ל וד\"ל.\n<b>וזהו</b> שהיו הכרובי' פורשי כנפיים למעלה סוככים בכנפיהם על הכפורת כו' ואמר בזהר דג' זימני ביומא אק[י]שא בגדפהא<sup data-n=\"3575\">288</sup> כו', והיינו בג' תפלות<sup data-n=\"3576\">289</sup> שבכל יום. דהנה בהיות שמבואר למעלה דאין ערוך כלל לאנפי זוטרי דבחי' הכרובים לגבי אנפי רברבי דבחי' ח\"ע דאדם הגדול, וע\"כ הי' צריך להיות",[["3567","280","<b>משה מ\"ה שמו</b>: ראה גם לעיל פ' שמות מג, ד. וש\"נ."],["3568","281","<b>שם האדם</b>: אב: בחי' אדם."],["3569","282","<b>למה תתעינו</b>: ישעי' סג, יז. ראה לעיל רפז, א."],["3570","283","<b>ששם עלו שבטים</b>: תהלים קכב, ד."],["3571","284","<b>ויקם עדות ביעקב</b>: תהלים עח, ה."],["3572","285","<b>אין</b>: אב: ליתא."],["3573","286","<b>וכלל</b>: שם: ליתא."],["3574","287","<b>וישמע את הקול</b>: נשא ז, פט [בדילוגים]."],["3575","288","<b>דג' זימני ביומא אק[י]שא בגדפהא [אב: בגדפייהו]</b>: ראה זהר אחרי נט, א. מאמרי אדה\"א קונטרסים ע' שסג. וש\"נ."],["3576","289","<b>בג' תפלות</b>: רמ\"ז לזהר שם."]]],[2300550504,"עלי' דכרובים בביטול במציאות במה שאקישו בג[ד]פייהו שהן אוי\"ר במקיף דנר\"נ שלהם, כמו מלאכים כשרפים נשר כו', כדי שיוכלו לקבל מבחי' ח\"ע, ואח\"כ יכולים לירד [ו]להשפיע למטה בעולמות הנפרדי' לנש\"י בגופים, בג'<sup data-n=\"3577\">290</sup> פעמים ביום הן עולים לקבל מח\"ע אנפי רברבי על<sup data-n=\"3578\">291</sup> ג' התפלות, וחוזרים ויורדים להשפיע למטה בבי\"ע עד עוה\"ז. ואם לא עולים הכרובים למעלה בהקשת גדפיהון לא היו יכולים לקבל מח\"ע שבראש ולא היו משפיעים למטה, וענין העליות שלהם זה הי' ע\"י פרישת גדפיהון למעלה אל הכפורת (שהוא בחי' כתר דחכ'<sup data-n=\"3579\">*292</sup> כמשי\"ת). וכ\"ז לפי שבחי' הכרובים הן בבחי' צמצום וקטנות המוחין ביותר, ע\"כ צריך שיהי' בהן בחי' הביטול במציאות תחלה, והיינו בבחי' עלייתם באוי\"ר שלמעלה מן ההשגה שבמוחין כמו המתפלל [ו]ידיו פרושו' למעלה<sup data-n=\"3580\">292</sup> מראשו וגם מספקים יד על יד מגודל הביטול, כך אקושי בגדפייהו בזמן ג' תפלות ואז יכולים להאיר למטה דוקא כו') (וכך הן ענין הג' תפלות דישראל בכל יום שנק' אנפי זוטרי כדי שיהיו יכולים לקבל מאור הח\"ע דתורה ולהמשיך בקול ודבור דתו' כמ\"ש הקל קול יעקב<sup data-n=\"3581\">293</sup> כו', ואם לא עלי' דתפלה בבחי' או\"ח לא הי' נמשך בקול דתורה שלהם כלום, וגם הקול <span data-k=\"pg\">922</span> ּ ודיבור דתורה שלהם אינו עולה למעלה להמשיך למטה רק ע\"י אוי\"ר דתפלה כידוע דאורייתא בלא דו\"ר<sup data-n=\"3582\">294</sup> לא פרחא לעילא, וזהו תפלת המנחה שמעלה הקול ודבור דתורה שלמד כל היום) (ודוגמא לזה בכלל הי' בעולי רגלים ג\"פ בשנה שאמר יראה כל זכורך<sup data-n=\"3583\">296</sup> את פני הוי' ממש שזהו ממש כאנפי זוטרי דרביא שמקבל [מ]פני אדם הגדול כו', והי' דוקא ע\"י השתחווא' בעזרה<sup data-n=\"3584\">295</sup> בביטול המציאות כו'). וזהו דוקא בבחי' הקטנות דכרובים כרבי' שצריך תמיד לעלות למעלה לקבל מח\"ע (כדוגמא דיהושע שנק' נער לא ימיש מתוך האוהל<sup data-n=\"3585\">297</sup> דמשה ח\"ע דפני יהושע כפני לבנה<sup data-n=\"3586\">298</sup> כו', וכן בחי' נער מט\"ט דכתיב ונתתי נערים שריהם<sup data-n=\"3587\">299</sup> כו' שצריך ג\"כ עלי' לקבל מאדה\"ע כו'. אבל בבחי' הגדלות דמוחין כמו משה שנק' איש כמ\"ש והאיש משה<sup data-n=\"3588\">300</sup> כו' שידעו ה' פא\"פ<sup data-n=\"3589\">301</sup> כאשר ידבר איש<sup data-n=\"3590\">302</sup> כו', וכן במשיח דכתי' בי' ישכיל עבדי<sup data-n=\"3591\">303</sup> כו' וגבה מאד, וכן בנש\"י שנק' אחים וריעים להקב\"ה (כמשי\"ת) וכמ\"ש ולציון יאמר איש ואיש יולד בה<sup data-n=\"3592\">304</sup> כו' א\"צ עלי' בתחלה כלל (וזהו כמו עכשיו מי שתורתו אומנתו שפטור מן התפלה<sup data-n=\"3593\">305</sup> והוא אדם אדמה לעליון ממש כו').",[["3577","290","<b>בג'</b>: אוצ\"ל: וג'."],["3578","291","<b>על</b>: בה: ע\"י."],["3579","*292","<b>הכפורת. . כתר דחכ'</b>: ראה גם לקמן פ' ויקהל תכ, ג. תמ, ג."],["3580","292","<b>המתפלל [ו]ידיו פרושו' למעלה</b>: ראה מל\"א ח, כב. נד. דהי\"ב ו, יב. יג."],["3581","293","<b>הקל קול יעקב</b>: תולדות כז, כב."],["3582","294","<b>דאורייתא בלא דו\"ר</b>: בתניא פל\"ט: בתיקונים — ת\"ז ת\"י (כה, ב)."],["3583","296","<b>ג\"פ בשנה. . יראה כל זכורך</b>: פ' ראה טז, טז."],["3584","295","<b>בעולי רגלים. . השתחווא' בעזרה</b>: ראה גם לעיל פ' בשלח קמג, א. וש\"נ."],["3585","297","<b>נער לא ימיש מתוך האוהל</b>: תשא לג, יא."],["3586","298","<b>דפני יהושע כפני לבנה</b>: ב\"ב עה, א."],["3587","299","<b>ונתתי נערים שריהם</b>: ישעי' ג, ד."],["3588","300","<b>והאיש משה</b>: בהעלותך יב, ג."],["3589","301","<b>שידעו ה' פא\"פ</b>: ברכה לד, י."],["3590","302","<b>כאשר ידבר איש</b>: תשא לג, יא."],["3591","303","<b>במשיח. . ישכיל עבדי</b>: ישעי' נב, יג. ראה מאמרי אדה\"א ויקרא ח\"א ע' קיב. וש\"נ."],["3592","304","<b>ולציון יאמר איש ואיש יולד בה</b>: תהלים פז, ה."],["3593","305","<b>שתורתו אומנתו שפטור מן התפלה</b>: ראה גם לעיל פ' יתרו רנו, ב. וש\"נ."]]],[2300550518,"<b>והנה</b> מעתה יש להבין מ\"ש ועשית שנים כרובים כו' משני קצות הכפורת למה צריך שיהי' ב' כרובים ושיהי' כרוב אחד מקצה מזה כו' ופניהם יהיו איש אל אחיו דוקא, הנה ידוע שהארון הוא בבחי' כלי לאור החכ' דתורה הגנוזה בלוחות העדות והכפורת אשר על הארון הוא כמו בחי' הכתר והעטרה שע\"ג המוחין דחו\"ב כו'. וידוע בענין ציור הע\"ס דאצי' שיש בו ג' קוין דת\"י<sup data-n=\"3594\">306</sup> קו האמצעי [ש]הוא התורה<sup data-n=\"3595\">307</sup> וב' הקוין חח\"ן מימין ובג\"ה משמאל נכללים בקו האמצעי שנק' בריח התיכון<sup data-n=\"3596\">308</sup> המבריח מן הקצה העליון לקצה התחתון דמל' כו'. וכך הי' ענין ב' הכרובים שנעשו מן הכפורת שעל הארון שהוא בחי' כתר דתורה<sup data-n=\"3597\">309</sup> שנחלק משם לב' קצוות ימין ושמאל, א' בבחי' החסדים דאו\"י ההולך ויורד מלמעלה למטה, והב' בחי' העלאה דאו\"ח שעולה מלמטה למעלה, וז\"ש ועשית כרוב א' מקצה מזה שיומשך ע\"י מקצה העליון דכתר כו'<sup data-n=\"3598\">310</sup> דתורה בבחי' ח\"ע לעורר למטה מטה דהיינו שיומשך גילוי אוא\"ס שבח\"ע דתורה דאצי' למטה בבי\"ע ע\"י כרוב זה שמקצה מזה בצד הימין (כמו קול ודיבור שהוא נמשך מלמעלה למטה שה' יושב ושונה כנגדו כמשי\"ת). וענין כרוב הב' מקצה מזה מצד השמאל דהיינו מה שע\"י הכרוב הזה יכול לעלות למעלה בבחי' או\"ח (כמו שיש בחי' עליי' בקול תורה מלמטה למעלה, והוא כמו יסוד האש שבדבור והיינו תושבע\"פ דוקא שהוא [ב]בחי' מקיף בחי' או\"ח, וכרוב אחד דימין דחסד שנק' תורת חסד זהו תושב\"כ בבחי' דכורא וכידוע דב' הכרובים היו בציור דו\"נ<sup data-n=\"3599\">311</sup>, והיו כלולים זה מזה<sup data-n=\"3600\">312</sup> כמ\"ש ופניהם איש אל אחיו דוקא (כמשי\"ת) (וזהו לכו לחמו בלחמי<sup data-n=\"3601\">313</sup> שהן תושב\"כ <span data-k=\"pg\">תסא</span> ּ ותושבע\"פ שהן ב' מצות קריאה לאותיות דתושב\"כ, והב' בעיון בהגיון<sup data-n=\"3602\">314</sup> המח' העולה בתושבע\"פ דדייק בגירסא וליבון הלכתא<sup data-n=\"3603\">315</sup> שע\"י העלאה דאו\"ח דעיון יומשך באו\"י בתושב\"כ ושניהם כלולים כא' ממש, ובתושב\"כ עצמה יש ג\"כ התחלקות דחו\"ג דאו\"י ואו\"ח ברמ\"ח מ\"ע ושס\"ה ל\"ת שזהו התכללות חו\"ג שבכתר ד\"ב דבתורה<sup data-n=\"3604\">316</sup> דאנכי ולא כו', שבדיבור א' ממש נאמרו<sup data-n=\"3605\">317</sup>, וכך ב' הכרובים בשרשם בכפורת עצמה כלולים כא' ממש, רק שנחלקו לב' הקצוות דכפורת מימין ושמאל, וע\"כ גם<sup data-n=\"3606\">318</sup> בהיותם מפורדים צריך שיהי' פניהם איש אל אחיו דוקא, וראי' לזה ממה שהי' הקול מדבר מעל הכפורת מבין ב' הכרובים יחד דוקא כו') וזה שהי' פניהם איש אל אחיו דוקא. דהנה ידוע שבכל העלאה יש בחי' רו\"ש דוקא וכמו [ו]החיות",[["3594","306","<b>דת\"י. . חח\"ן. . ובג\"ה</b>: נסמן לעיל פ' יתרו רסט, ג."],["3595","307","<b>קו האמצעי [ש]הוא התורה</b>: ראה גם לקמן פ' פקודי תנא, ב. תו\"ח בראשית מא, סע\"ד."],["3596","308","<b>בקו האמצעי שנק' בריח התיכון</b>: ראה גם ביאוה\"ז תשא נד, ב. שעה\"י קכה, א ובהערה 6. לקמן פ' פקודי שם."],["3597","309","<b>הכפורת. . כתר דתורה</b>: ראה לקו\"ת להאריז\"ל תרומה כה, י. אוה\"ת תרומה (כאן) ע' א'תנח."],["3598","310","<b>כו'</b>: אב: ליתא."],["3599","311","<b>הכרובים היו בציור דו\"נ</b>: ראה יומא נד, א. זהר אחרי נט, א. בחיי תרומה כה, יח."],["3600","312","<b>זה מזה</b>: אב: זה על זה. ה: זע\"ז."],["3601","313","<b>לכו לחמו בלחמי</b>: משלי ט, ה. ראה זח\"א (השמטות) רס, א."],["3602","314","<b>ב' מצות קריאה. . בעיון בהגיון</b>: ראה הל' ת\"ת לאדה\"ז פ\"ב, הי\"ב. לעיל פ' בשלח קסט, ב. וש\"נ."],["3603","315","<b>וליבון הלכתא</b>: ראה לעיל פ' שמות ג, ב ואילך (ובהערה 130)."],["3604","316","<b>ד\"ב דבתורה</b>: הו: דב' דברות שבתו'."],["3605","317","<b>דאנכי ולא. . שבדיבור א'. . נאמרו</b>: נסמן לעיל פ' יתרו רסד, א."],["3606","318","<b>גם</b>: אב: ליתא."]]],[2300550531,"רצוא ושוב<sup data-n=\"3607\">319</sup>, וכך במס\"נ דישראל באחד פשוט דהנפש הוא בע\"ג וכאשר תכלה הנפש לדבק באח\"פ כמו כלתה נפשי<sup data-n=\"3608\">320</sup> כו' הרי יש בזה עצמו בחי' שוב להמשיך גילוי אלקות בנפשו והעלאה זו מתכללת עם המשכה כא', ועי\"ז נמשך אתעדל\"ע ג\"כ בבחי' התכללו' בירידה והעלאה כא', וכידוע שיש אתעדל\"ע שנמשך אחר אתעדל\"ת בבחי' ירידה למטה דוקא, ויש אתעדל\"ע שעושה אתעדל\"ת<sup data-n=\"3609\">321</sup> שהוא כח המעורר את הלב לעלות למעלה בתשובה ואוי\"ר, ונמצא מובן מזה דרוח אייתי רוח<sup data-n=\"3610\">322</sup> כו' שע\"י העלאה דאתעדל\"ת במס\"נ הנ\"ל מעורר אתעדל\"ע לירד למטה, ואתעדל\"ע זו עצמו הוא שעושה אתעדל\"ת והכל מתאחד כא' כמו שרו\"ש מתכללים כא' כנ\"ל וד\"ל.\n<b>ויובן</b> זה במצות היחוד עילאה בק\"ש בשמע ישראל למסור נפשו באחד<sup data-n=\"3611\">323</sup> שזהו בחי' העלאה דאו\"ח ואח\"כ מאריך באחד להמליכו בשמים ובארץ<sup data-n=\"3612\">324</sup> כו' שזהו בחי' הירידה והמשכה למטה וכמו\"כ בואהבת כו' גימט' ב\"פ אור<sup data-n=\"3613\">325</sup> או\"ח ואו\"י רו\"ש. וזהו והיו הדברים האלה<sup data-n=\"3614\">326</sup> כו' שע\"י העלאה במס\"נ בעצמות אוא\"ס לאשתאבא בגופא דמלכא<sup data-n=\"3615\">327</sup> כו' עי\"ז חוזר ונמשך מעצמות אוא\"ס בחכ' שבתורה מח\"ע בחי' אנפי רברבי שיומשך למטה בח\"ת דבי\"ע, והוא ע\"י בחי' הכרוב הא' מקצה הימין והוא מפני שהכרובי' היו שניהם נמשכים מב' קצות הכפורת דוקא כנ\"ל. וענין הכפורת שע\"ג הארון הוא בחי' כתר וסובב הכללי שלמעלה מבחי' ח\"ע וח\"ת שנק' חכמה בראש וחכ' בסוף, כי בחי' סובב הכללי מחבר ראש וסוף כא', וע\"כ ב' הכרובים שהמה בחי' או\"י ואו\"ח מקורם הוא בבחי' הכתר שעל הארון, והכרוב הא' מקצה הימין אשר נמשך מן הכפורת בקצה הימי[ני] הוא הממשיך וסובב הכללי להאיר בח\"ע לח\"ת שהוא בחי' הכרובים כרוב א' מקצה מזה כו' כנ\"ל עד שיכול למשוך אור החכ' דתו' לנש\"י בגופים. אך פני הכרוב הימני הזה הי' לפני הכרוב השמאלי שעומד בקצה השמאל שנמשך מקצהו השמאלי שעל הכפורת וכמ\"ש ופניהם איש אל אחיו דוקא, וענין הכרוב הב' מהשמאל הוא בחי' העלאה דאו\"ח מלמטה למעלה מח\"ת לח\"ע, והוא כמו הנ\"ל בדבור<sup data-n=\"3616\">328</sup> דתורה שלומדים למטה שעולה למעלה עד בחי' אנפי רברבי דח\"ע, דאדם הגדול כמ\"ש הקול קול יעקב קלא דאוריי'<sup data-n=\"3617\">329</sup> דוקא וכן השמיעני את קולך<sup data-n=\"3618\">330</sup> כו', וע\"ז <span data-k=\"pg\">924</span> ּ אמר קרוב ה' כו' באמת דתורה יקראוהו כקורא בשמותיו העצמיים ממש. וכמו\"כ בחי' העלאה במס\"נ באחד הנ\"ל הוא בכרוב הב' דוקא שעולה בבחי' או\"ח, וע\"כ אמר דפניהם איש אל אחיו דוקא שהיו כלולים כא' פב\"פ דוקא (דהיינו ביחוד דו\"נ שהכרוב הימני הוא בדמות זכר שהוא בבחי' החסדים דאו\"י",[["3607","319","<b>[ו]החיות רצוא ושוב</b>: יחזקאל א, יד."],["3608","320","<b>כלתה נפשי</b>: תהלים פד, ג."],["3609","321","<b>אתעדל\"ע שנמשך. . שעושה אתעדל\"ת</b>: ראה סידור שער התפלה יט, א ואילך. לקמן פ' תשא שפב, ד. ויקהל תכג, א. מאמרי אדה\"ז תקס\"ג ח\"א ע' קפ. תו\"א ויקהל קיב, רע\"ג. מאמרי אדה\"א שמות ח\"ב ע' תרמא. לעיל פ' משפטים רפא, א."],["3610","322","<b>דרוח אייתי רוח</b>: נסמן לעיל פ' יתרו רנא, א."],["3611","323","<b>למסור נפשו באחד</b>: ראה זהר (רע\"מ) משפטים קיט, א. צו לג, א. מאמרי אדה\"א דברים ח\"ב ע' תו. וש\"נ. שמות ח\"א ע' רעח ואילך. הנחות תקע\"ז ע' שא."],["3612","324","<b>מאריך באחד להמליכו בשמים ובארץ</b>: ראה ברכות יג, ב."],["3613","325","<b>בואהבת. . גימט' ב\"פ אור</b>: פע\"ח (שער הק\"ש) ש\"ח, פכ\"ג. ראה לעיל פ' וארא סה, ג. וש\"נ."],["3614","326","<b>והיו הדברים האלה</b>: ואתחנן ו, ו."],["3615","327","<b>לאשתאבא בגופא דמלכא</b>: נסמן לעיל פ' יתרו רסט, ד."],["3616","328","<b>הנ\"ל בדבור</b>: אב: הבל הדבור."],["3617","329","<b>הקול קול יעקב קלא דאוריי'</b>: ראה זהר ויצא קנא, סע\"א."],["3618","330","<b>השמיעני את קולך</b>: שה\"ש ב, יד. ראה זהר אחרי סא, א. פינחס ריג, א. לעיל פ' בא קח, ג. וש\"נ."]]],[2300550544,"וכרוב א'<sup data-n=\"3619\">331</sup> הב' בציור נוק' ומתייחדים יחד), משום דמבחי' או\"י דחסדי' דכרוב הא' היורד מלמעלה למטה עושה העלאה דאו\"ח שבכרוב הב', וגם זה אמת שאם לא אתעדל\"ת בהעלאה דאו\"ח בכרוב הב' במס\"נ בא' באוי\"ר אמיתי' לא הי' נמשך מח\"ע לח\"ת בכרוב א' (וכמאמר אין לי אלא תורה<sup data-n=\"3620\">332</sup> אפי' תורה אין לו כו') כמ\"ש כמים הפנים אל פנים דוקא כפי העלאת מ\"ן כך לב האדה\"ע לאדה\"ת שזהו מאנפי רברבי לאנפי זוטרי כנ\"ל וד\"ל.\n<b>וזהו</b> ופניהם איש אל אחיו דוקא, ויש בזה ב' טעמים א' מצד התכללו' דאו\"י ואו\"ח יחד שמתאחדים כא' לפי שאין זה בלא זה כו' כנ\"ל, והטעם הב' דזה גופא מה שמתכללים כא' ממש זהו לפי שנמשכים שניהם מן הכפורת שעל הארון שהוא כתר דח\"ע וח\"ת כנ\"ל, ששם אין הפרש כלל בין עלי' לירידה כי סובב למעלה ולמטה בשוה שמעלה ומטה שוה ממש, ולפי\"ז הרי אין הפרש שם בין המשכה מאור א\"ס למטה בח\"ת דכנס\"י ובין העלאה דכנס\"י באו\"ח למעלה ליכלל באחד כמו שהוא למעלה כו'. והיינו ענין הכפורת שעל הארון שכולל ב' הכרובים הללו שנמשכים ממנו ושוין הם שם ממש בחי' העלאה עם בחי' ההמשכה מטעם שהוא בחי' סובב הכללי כנ\"ל, ולזאת גם בירידת והמשכת הב' כרובים ממנו נעשה בחי' התכללו' להיות פניהם איש אל אחיו דוקא כנ\"ל (כענין עושה השלום<sup data-n=\"3621\">333</sup> כו') מצד שכלולים כאחד במקורם בכפורת שעל הארון, וע\"כ הן בבחי' אחוה ממש עד שבאמצעות חיבורם יחד הן בחי' אדם אחד (בהתכללות דו\"נ כנ\"ל כו') וד\"ל.\n<b>ובכ\"ז</b> יובן הטעם שכנס\"י נקראים אחים וריעים כו', כמ\"ש למען אחיי וריעיי כנ\"ל והוא בבחי' התקשרות האחוה והריעות שמתקשרים בדבר א' שהוא התורה, דישראל מתקשראן באוריי' בבחי' אדם תתאה ואוריי' בקוב\"ה בבחי' אדם עילאה כו', וכמו במ\"ת שחכמת אדם עילאה האיר פניו לנש\"י ע\"י התורה כו' בבחי' פב\"פ דאדם הגדול עם אנפי זוטרי דכנס\"י כו', וכמו בכרובים שהיו פניהם איש אל אחיו כו', וכתיב ונועדתי לך שם ודברתי אתך מעל הכפורת מבין ב' הכרובי' דוקא, ודקדק לומר מעל הכפורת ששם שוין ב' הכרובים דאו\"י ואו\"ח להיותו בבחי' סובב הכללי כנ\"ל, וא\"כ גם בירידת האור בכרובים הי' מדבר מבין ב' הכרובים יחד דוקא מטעם הנ\"ל וד\"ל.\n<b>וזהו</b> ועשית ב' כרובים זהב כו' כרוב א' מקצה מזה כו' מן הכפורת תעשה את הכרובים מב' קצותיו מטעם הנ\"ל ששרש הכרובים הוא בחו\"ג שבעצמות אור הכתר שכלולים שם",[["3619","331","<b>א'</b>: אב: ליתא."],["3620","332","<b>אין לי אלא תורה</b>: ראה יבמות קט, ב."],["3621","333","<b>עושה השלום</b>: נסמן לעיל פ' יתרו ערה, ג."]]],[2300550557,"כא' ממש (כענין שאמר אנכי <span data-k=\"pg\">תסב</span> ּ ולא יהי' לך בדבור א' נאמרו כו', ומטעם הנ\"ל שבחי' סובב הכללי שם כלולים כאחד העלאה עם המשכה כו'). וזהו מן הכפורת דוקא תעשה את הכרובים כו' דגם שהארון שב[ו] לוחות העדות הוא עיקר התורה שנמשך מח\"ע וע\"כ נק' ארון העדות וכמו ויקם עדות ביעקב כו' שהוא בחי' קו האמצעי דעת ות\"ת כו', עכ\"ז הי' העיקר ומקור לאור דתורה זו שבארון העדות דוקא מן הכרובים שבב' קצות הכפורת שהי' שרשם בכפורת שעל הארון שהוא למעלה מבחי' ח\"ע דאותיות התורה שבלוחות כו'. וראי' לזה ממה שהי' הקול מדבר מעל הכפורת מבין ב' הכרובים כנ\"ל וכמ\"ש ונועדתי לך שם כו' להיות הכפורת בבחי' מקיף וכתר דאור הח\"ע כנ\"ל (וע\"כ הי' הקול מורכב מבין ב' הכרובים שהוא בחי' התכללות בכח ומקור השכל באין דכתר שהן ב' הפכים כא' כמו תורה של חסד ותורה של דין<sup data-n=\"3622\">334</sup>, כידוע שיש בכח ומקור החכ' להשכיל מאין ליש כל מיני שכל לזכות וחסד דוקא להכשיר את הפסול ולטהר את הטמא ולהצדיק [את] הרשע, ולהיפוך יש בכח הדין במקור החכ' להמשיך שכל לדין וחוב להרשיע את הצדיק ולטמא [גם] את הטהור כו', וא\"כ לא הי' יוצא דבר ברור לפסק הלכה למעשה. אך בחי' הממוצע הוא המכריע להביא אור השפע בבחי' היושר בלי נטי' לימין ושמאל כלל שזהו שרש התורה שנק' ספר הישר<sup data-n=\"3623\">335</sup> שהוא קו האמצעי בקו המשקולת להבדיל בין טוב<sup data-n=\"3624\">336</sup> כו' במדה ברורה ויפה, ומאין יש כח הכרעה זו ובירור זה בחכ' דתורה שנק' עדות זהו מבחי' התכללות דב' הכרובים למעלה בכפורת דוקא שעל הארון שמשם נמשך הבדלה זו לימין ושמאל במדידה יפה באו\"י דחסד ואו\"ח דגבו'. וע\"כ הי' הקול דתורה מדבר מחיבור והתכללות דבין ב' הכרובים דוקא שמהן הי' שורש להתכללות דחו\"ג שבתורה בגילוי ברמ\"ח מ\"ע ושס\"ה ל\"ת דאנכי ולא כו', וע\"כ אחר שאמר ונתת אל הארון את העדות<sup data-n=\"3625\">337</sup> ציוה לעשות כפורת וכרובים והי' פניהם איש אל אחיו אל הכפורת דוקא יהיו פני הכרובים מטעם הנ\"ל, ואח\"כ אמר ונתת את הכפורת על הארון מלמעלה ואל הארון תתן כו' ואז ונועדתי לך שם דהא בהא תליא מטעם כל הנ\"ל). וכן לענין תושב\"כ ותושבע\"פ<sup data-n=\"3626\">338</sup> כנ\"ל שזהו ג\"כ כמו ב' הפכים דחו\"ג כי שרש אותיות דתושב\"כ הוא בבחי' החסדים דאו\"י ושורש ההלכות דתורה שבע\"פ בבחי' הגבורות ופניהם איש אל אחיו דאין בתושבע\"פ רק מה שמקבל מתושב\"כ כמו מנלן אמר קרא<sup data-n=\"3627\">339</sup> כו', ונק' פנים מאירות ופנים מסבירות<sup data-n=\"3628\">340</sup> כתרין ריעין דל\"מ<sup data-n=\"3629\">341</sup> כו'. וזהו הקל קול יעקב ב' קולות דאו\"י ואו\"ח דתושב\"כ ושבע\"פ",[["3622","334","<b>תורה של חסד ותורה של דין</b>: ראה גם לעיל פ' בשלח רמד, ג. וש\"נ."],["3623","335","<b>התורה שנק' ספר הישר</b>: ראה לעיל פ' שמות י, ג. וש\"נ."],["3624","336","<b>טוב</b>: אב: טו\"ט טומאה וטהרה."],["3625","337","<b>ונתת אל הארון את העדות</b>: תרומה כה, טז."],["3626","338","<b>תושב\"כ ותושבע\"פ</b>: אבה: ב' תורות שבכתב ושבע\"פ."],["3627","339","<b>מנלן אמר קרא</b>: ראה פסחים סא, סע\"א. סה, רע\"א. ועוד."],["3628","340","<b>פנים מאירות ופנים מסבירות</b>: ראה גם לעיל פ' שמות יא, ב. וש\"נ."],["3629","341","<b>דל\"מ</b>: ה: דלא מתפרשין."]]],[2300550570,"שהי' הקול מדבר מן ב' הכרובים יחד דוקא, וכמ\"ש את כל אשר אצוה אותך<sup data-n=\"3630\">342</sup> אל בנ\"י דכל זה מרבה גם תושבע\"פ כמו תורה צוה לנו משה<sup data-n=\"3631\">343</sup> כו'). ומ\"ש והיו הכרובים פורשי כנפים למעלה סוככים בכנפיהם על הכפורת כו', זהו כמ\"ש במ\"א ע\"פ וקוי ה' יחליפו כח<sup data-n=\"3632\">344</sup> יעלו אבר כנשרים שעתיד הקב\"ה לעשות כנפים לצדיקים ככנפי נשרים כו' שזהו מצד הבירורים דתו\"מ דנשמות הצדיקי' שנק' אנפי זוטרי ככרובי' שיעלו בכנפיהם באוי\"ר שלהם בסוף <span data-k=\"pg\">926</span> ּ מעשה בפו\"מ למעלה גם מעל הכפורת שזהו בבחי' מקיף למקיף להיות סוככים בכנפיהם על הכפורת כו' וד\"ל.\n<b>ומעתה</b> [הנה] יש להבין במ\"ש למען אחיי וריעיי כו', איך נק' ישראל אחים וריעים לקוב\"ה כו', ואין זה אלא בזמן בהמ\"ק, וכמו שאו' אח\"ז למען בית ה' אלקינו כו' כנ\"ל דהא בהא תליא דאין נק' אחים רק כאשר בית ה' אלקינו קיים כו'. והענין הוא שבזמן בהמ\"ק דוקא שאז [הי'] בחי' יחוד פב\"פ ע\"י ב' הכרובים שבארון שהיו פניהם איש אל אחיו דוקא מטעם הנ\"ל, אבל בזמן הגלות דכנס\"י הוא בבחי' הריחוק והסתר פנים העליונים וכמאמר דגם קוב\"ה בגלותא אסתלק לעילא<sup data-n=\"3633\">345</sup> כו' אז לא נק' ישראל אחים וריעים כלל, וע\"כ מבקשת כנס\"י בזמן הגלות מי יתנך כאח לי כו'. אך א\"כ מהו שמבקשת מי יתנך כאח לי כו' משמע מזה שגם בזמן הגלות שאין בהמ\"ק יכול להיות בחי' יחוד [ד]פב\"פ העליונים כמו שהי' בזמן בהמ\"ק ממש, ולהיות נק' בשם אחים וריעים<sup data-n=\"3634\">346</sup> ממש, והיינו ע\"י מצות ת\"ת בדבור כנ\"ל, שהרי ארז\"ל דמשחרב בהמ\"ק אין לו להקב\"ה רק ד\"א של הלכה<sup data-n=\"3635\">347</sup> בלבד שהוא במקום היכל קד\"ק בזמן בהמ\"ק ממש. ובאמת יש להבין איך יתכן להיות שיהי' ד' אמות של הלכה שלומדי' בעוה\"ז כמו היכל ק\"ק שבו הי' הארון והלוחות וגילוי שכינה בין ב' הכרובים כנ\"ל. וגם מה זה שא' לשון ד' אמות של הלכה, איך שייך ענין מקום ושטח ד\"א בהלכה, ולמה ד' אמות דוקא ולא יותר כו'.\n<b>אך</b> הנה להבין ביאור הדבר יש להקדים מה שאו' בלשון הקב\"ה דוקא, וכן בכ\"מ בדרז\"ל נזכר שם זה<sup data-n=\"3636\">348</sup> דהקב\"ה שהוא מורכב מב' ענינים קדוש וברוך שאומרים השרפי' ואופנים וחיות<sup data-n=\"3637\">349</sup>, שלכאו' הרי הן כמו ב' הפכים ממש שהרי או' והאופנים וחיוה\"ק מתנשאים לעומתם<sup data-n=\"3638\">350</sup> ואו' ברוך כו', וכידוע דפי' קדוש הוא בחי' הבדלה<sup data-n=\"3639\">351</sup> והפלאה בערך למעלה מהכל, ופי' ברוך הוא בחי' ההמשכה<sup data-n=\"3640\">352</sup> בירידת האור בגילוי למטה",[["3630","342","<b>את כל אשר אצוה אותך</b>: תרומה כה, כב."],["3631","343","<b>תורה צוה לנו משה</b>: ברכה לג, ד."],["3632","344","<b>וקוי ה' יחליפו כח</b>: ישעי' מ, לא. ראה יל\"ש שם. סנהדרין צב, רע\"ב. מאמרי אדה\"א בראשית ע' עז ואילך וע' קל ואילך."],["3633","345","<b>קוב\"ה בגלותא אסתלק לעילא</b>: ראה זהר ויגש רי, א. ויקרא כ, ב. לעיל פ' שמות לט, א. וש\"נ."],["3634","346","<b>וריעים</b>: אב: ליתא."],["3635","347","<b>של הלכה</b>: שם: ליתא."],["3636","348","<b>הקב\"ה. . בדרז\"ל נזכר שם זה</b>: ראה ברכות ג, א. ב. מאמרי אדה\"ז תקע\"א כאן (ע' צו). מאמרי אדה\"א ויקרא ח\"ב ע' תמה ואילך. וש\"נ. ס\"ע תנז ואילך ובהנסמן שם בח\"א ע' רעו."],["3637","349","<b>קדוש וברוך שאומרים השרפי' ואופנים וחיות</b>: ראה חולין צב, רע\"א ובתוד\"ה ברוך."],["3638","350","<b>והאופנים וחיוה\"ק מתנשאים לעומתם</b>: ברכת יוצר [בדילוג]."],["3639","351","<b>קדוש. . הבדלה</b>: ראה רש\"י ותו\"כ ר\"פ קדושים. תניא כמצויין במפתח ענינים בערך קדושה. מאמרי אדה\"ז תקס\"ו ע' קז. לקמן פ' תצוה שנט, ד. לעיל בהערה 348."],["3640","352","<b>ברוך. . ההמשכה</b>: ראה לעיל פ' בשלח קס, ג. וש\"נ."]]]]});
